COLLDATA("qenc","ur",[[336,"§سمویل\nسمویل بنی اسرائیل کے ایک نبی کا نام ہے۔قرآن میں ان کا ذکر نہیں آیا ہے۔ تاہم بیشترعلما کی رائے ہے کہ سورہ البقرہ:۲۴۶۔میں جس نبی کی طرف اشارہ کیا گیا ہے وہ یہی سمویل ہیں: ﴿أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ مِنۢ بَعۡدِ مُوسَىٰٓ إِذۡ قَالُواْ لِنَبِيࣲّ لَّهُمُ ٱبۡعَثۡ لَنَا مَلِكࣰ ا نُّقَٰتِلۡ فِي سَبِيلِ﴾ [البقرة: ۲۴۶] \"کیا تم نے موسیٰ کےبعد بنی اسرائیل کے سرداروں کو نہیں دیکھا، جب انھوں نے اپنے ایک نبی سے کہا: ہمارے لیے ایک بادشاہ مقرر کر دیں تاکہ ہم اللہ کی راہ میں جہاد کریں\"۔\nقرآن اور صحیح احادیث میں ان کے متعلق کچھ اور نہیں آیا ہے۔ لیکن بائبل میں ان کے نام کی دو کتابیں ہیں، جو درحقیقت ایک ہی کتاب تھی۔ تقریباً ۱۵۱۶ء میں اس کو دو حصوں میں منقسم کر دیا گیا۔\nاس سے پتا چلتاہے وہ نبی اور منصف(قاضی) بھی تھے۔ آپ رامہ شہر میں رہتے تھےاور بیت ایل، جلجال اور مصفاة وغیرہ میں گھوما کرتے تھےاور رامہ ہی میں ایک مسجد بھی تعمیرکرائی تھی۔ ایک بار فلسطینیوں نے حملہ کر دیا تو بنی اسرائیل کو لے کر اللہ سے دعا کرنے لگے اور آپ کو فتح حاصل ہوئی۔ (دیکھئے: سمویل: ۷/۳ـ۴ا)\nجب آپ ضعیف ہوگئے تو بنی اسرائیل نے خواہش ظاہر کی کہ ہمارے لیے کوئی حکمراں مقرر کردیں تو آپ نے طالوت نامی ایک شخص کو بنی اسرائیل کا حکمراں مقرر کر دیا اور اس کے بعد بنی اسرائیل میں یہ ایک سلسلہ چل پڑا۔","",{}],[337,"§سمیع\nدیکھیے: اسماےحسنی","",{}],[338,"§سنیاس\nدیکھیے: رہبانیت","",{}],[339,"§سواع\nیہ ہذیل قبیلے کا بت تھا۔ (مزید جانکاری کے لیے دیکھیں: ود)","",{}],[340,"§سوالی\nدیکھیے: سائل","",{}],[341,"§سود\nدیکھیے: ربا","",{}],[342,"§سور\nدیکھیے: خنزير","",{}],[343,"§سورج\nدیکھیے: شمس","",{}],[344,"§سورہ\nسورہ شہر کی اس دیوار کو کہتے ہیں جو اس کو گھیرے رہتی ہے۔ اس طرح کسی گھر کو جس دیوار سے گھیرا جاتا ہے، اس کو بھی سورہ کہا جاتا ہے۔ اسی طرح قرآن کریم کے اندر (۱۱۴)سورتیں ہیں۔\nانھیں سورہ اس لیےکہتے ہیں کہ ان سورتوں کے اندر جو معانی ومطالب اور مفاہیم ہوتے ہیں،وہ ان سب کو گھیرے ہوے ہوتی ہے۔\nان سورتوں کو الگ کرنے کے لیے ہرسورہ کے شروع میں بسم اللہ الرحمٰن الرحیم لکھا جاتاہے۔ صرف سورہ توبہ کےشروع میں بسم اللہ الرحمٰن الرحیم نہیں لکھاگیا۔کیوں کہ کچھ لوگوں کا خیال ہے کہ سورہ توبہ سورہ انفال کا ہی ایک حصہ ہے۔ مصحف میں ہرسورہ کے شروع میں مکی یا مدنی بھی لکھا جاتا ہے۔جس کے معنی ہیں کہ یہ سورہ مکی دور میں نازل ہوئی یا مدنی دور میں۔","",{}],[345,"§سونٹھ\nدیکھیے: زنجبيل","",{}],[346,"§سيل عرم\nسیل کے معنی ہیں: سیلاب، باڑھ۔عرم کے معنی ہیں بند۔ سیل عرم کا مطلب ہے وہ بندجو سیلاب کے سبب ٹوٹ گیا تھا۔ اسے دوسرے لفظوں میں بند توڑ سیلاب کہا جا سکتا ہے۔\nسیل عرم کا ذکر قرآن کریم میں صرف ایک بار آیا ہے:﴿لَقَدۡ كَانَ لِسَبَإࣲ فِي مَسۡكَنِهِمۡ ءَايَةࣱۖ جَنَّتَانِ عَن يَمِينࣲ وَشِمَالࣲۖ كُلُواْ مِن رِّزۡقِ رَبِّكُمۡ وَٱشۡكُرُواْ لَهُۥۚ بَلۡدَةࣱ طَيِّبَةࣱ وَرَبٌّ غَفُورࣱ فَأَعۡرَضُواْ فَأَرۡسَلۡنَا عَلَيۡهِمۡ سَيۡلَ ٱلۡعَرِمِ وَبَدَّلۡنَٰهُم بِجَنَّتَيۡهِمۡ جَنَّتَيۡنِ ذَوَاتَيۡ أُكُلٍ خَمۡطࣲ وَأَثۡلࣲ وَشَيۡءࣲ مِّن سِدۡرࣲ قَلِيلࣲ‏﴾ [سبأ: ۱۵-۱۶] \"(اہل) سبا کے لیے ان کے مقام بودوباش میں (قدرت کی) ایک نشانی تھی (یعنی) دو باغ (ایک) داہنی طرف اور (ایک) بائیں طرف۔ (ہم نے ان کو حکم دیا تھا کہ)اپنے رب کا رزق کھاؤ اور اس کا شکر کرو۔ (یہاں تمھارے رہنے کو یہ) پاکیزہ شہر ہے اور (وہاں بخشنے کو) خدائے غفار۔ تو انھوں نے (شکرگزاری سے) منہ پھیر لیا، پس ہم نےان پر زور کا سیلاب چھوڑ دیا اور انھیں ان کے باغوں کےبدلے دو ایسے باغ دیئے جن کے میوے بدمزہ تھے اور جن میں کچھ تو جھاؤ تھا اور تھوڑی سی بیریاں\"۔\nسبا یمن کی ایک قوم تھی جو بڑی ترقی کر گئی تھی۔ (دیکھیے: سبا)\nاس قوم کی ترقی کا سبب ایک تو ان کا کاروبار تھا دوسرےانھوں نے پہاڑوں کے بیچ بند بنا کر پانی روک رکھا تھا۔جس سے وہ کھیتی کیا کرتے تھے۔ جس کے نتیجے میں ان کا ملک کھیتی باڑی میں بے حد ترقی کر گیاتھا۔جدھر وہ آنکھ اٹھا کر دیکھتے ادھر ہریالی ہریالی ہی نظر آتی تھی۔ ایسی حالت میں تو انھیں تو یہ چاہیےتھا کہ وہ لوگ اللہ تعالیٰ کے بتائے ہوے دین پر چلتےاور اس کے احکام و فرامین کے مطابق زندگی گزارتے اور اس پر عمل کرتے۔ لیکن وہ اپنی اس ترقی اور خوشحالی پرگھمنڈ کرنے لگے تھے۔ وہ لوگ اللہ تعالیٰ کے بتائے ہوے دین پر چلنے،اس کے احکام و فرامین کے مطابق زندگی گزارنےاور اس پر عمل کرنے کی بجائےاس کی خلاف ورزی کرنے اور اس کی مخالفت پر آمادہ ہوگئے اور اسے یکسر ٹھکرادیا۔جس کی پاداش میں اللہ تعالیٰ نے ان کو سیل عرم کے ذریعے سے ہلاک وبرباد کردیا۔ وہ بستیاں جو آپس میں ملی جلی تھیں ویران و برباد ہو گئیں۔ ان میں جو کھیتیاں تھیں وہ تباہ و برباد ہو گئیں۔ جو لوگ اس سے بچ گئے تھے وہ وہاں سے نکل بھاگے۔ غسان قبیلے کے لوگ شام کی طرف ہجرت کر گئے۔ اوس اور خزرج قبائل مدینے میں آکر آباد ہو گئے، جس کو اس وقت یثرب کہا جاتا تھا۔بنی خزاعہ نے مکہ و جدہ کا رخ کیا اور وہاں جاکربس گئے۔ اس طرح قوم سبا کا یمن سے خاتمہ ہو گیا اور پوری قوم تتر بتر ہوگئی۔ صرف کچھ ہی لوگ بچےجو توحید پر یقین رکھتے تھے۔ قرآن کریم میں اس قوم کا نقشہ یوں کھینچا ہے:﴿لَقَدۡ كَانَ لِسَبَإࣲ فِي مَسۡكَنِهِمۡ ءَايَةࣱۖ جَنَّتَانِ عَن يَمِينࣲ وَشِمَالࣲۖ كُلُواْ مِن رِّزۡقِ رَبِّكُمۡ وَٱشۡكُرُواْ لَهُۥۚ بَلۡدَةࣱ طَيِّبَةࣱ وَرَبٌّ غَفُورࣱ فَأَعۡرَضُواْ فَأَرۡسَلۡنَا عَلَيۡهِمۡ سَيۡلَ ٱلۡعَرِمِ وَبَدَّلۡنَٰهُم بِجَنَّتَيۡهِمۡ جَنَّتَيۡنِ ذَوَاتَيۡ أُكُلٍ خَمۡطࣲ وَأَثۡلࣲ وَشَيۡءࣲ مِّن سِدۡرࣲ قَلِيلࣲ ذَٰلِكَ جَزَيۡنَٰهُم بِمَا كَفَرُواْۖ وَهَلۡ نُجَٰزِيٓ إِلَّا ٱلۡكَفُورَ وَجَعَلۡنَا بَيۡنَهُمۡ وَبَيۡنَ ٱلۡقُرَى ٱلَّتِي بَٰرَكۡنَا فِيهَا قُرࣰ ى ظَٰهِرَةࣰ وَقَدَّرۡنَا فِيهَا ٱلسَّيۡرَۖ سِيرُواْ فِيهَا لَيَالِيَ وَأَيَّامًا ءَامِنِينَ فَقَالُواْ رَبَّنَا بَٰعِدۡ بَيۡنَ أَسۡفَارِنَا وَظَلَمُوٓاْ أَنفُسَهُمۡ فَجَعَلۡنَٰهُمۡ أَحَادِيثَ وَمَزَّقۡنَٰهُمۡ كُلَّ مُمَزَّقٍۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّكُلِّ صَبَّارࣲ شَكُورࣲ وَلَقَدۡ صَدَّقَ عَلَيۡهِمۡ إِبۡلِيسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِيقࣰ ا مِّنَ ٱلۡمُؤۡمِنِينَ وَمَا كَانَ لَهُۥ عَلَيۡهِم مِّن سُلۡطَٰنٍ إِلَّا لِنَعۡلَمَ مَن يُؤۡمِنُ بِٱلۡأٓخِرَةِ مِمَّنۡ هُوَ مِنۡهَا فِي شَكࣲّۗ وَرَبُّكَ عَلَىٰ كُلِّ شَيۡءٍ حَفِيظࣱ‏﴾ [سبأ: ۱۵-۲۱] \"(اہل)سبا کے لیے ان کے مقام بودوباش میں ایک نشانی تھی (یعنی) دو باغ (ایک) داہنی طرف اور (ایک) بائیں طرف۔(ہم نے ان کو حکم دیا تھا کہ) اپنے رب کا رزق کھاؤ اور اس کا شکر کرو۔ (یہاں تمھارے رہنے کو یہ) پاکیزہ شہر ہے اور (وہاں بخشنے کو) خدائے غفار۔ تو انھوں نے (شکرگزاری سے) منہ پھیر لیا پس ہم نے ان پر زور کا سیلاب چھوڑ دیا اور انھیں ان کے باغوں کے بدلےدو ایسے باغ دیے جن کے پھل بدمزہ تھے اور جن میں کچھ تو جھاؤ تھا اور تھوڑی سی بیریاں۔ یہ ہم نےان کی ناشکری کی ان کو سزا دی۔ اور ہم سزا ناشکرے ہی کو دیا کرتے ہیں۔ اور ہم نے ان کے اور (شام کی) ان بستیوں کے درمیان جن میں ہم نے برکت دی تھی (ایک دوسرے کے متصل) دیہات بنائے تھے جو سامنے نظر آتے تھے اور ان میں آمد ورفت کا اندازہ مقرر کردیا تھا کہ رات دن بےخوف وخطر چلتے رہو۔تو انھوں نے دعا کی کہ اے رب ہماری مسافتوں میں بُعد (اور طول پیدا) کردے اور (اس سے) انھوں نے اپنے حق میں ظلم کیا تو ہم نے (انھیں نابود کرکے) ان کے افسانے بنادیئے اور انھیں بالکل منتشر کردیا۔ اس میں ہر صابر وشاکر کے لیے نشانیاں ہیں۔ اور شیطان نے ان کےبارے میں اپنا خیال سچ کر دکھایا کہ مومنوں کی ایک جماعت کے سوا وہ اس کے پیچھے چل پڑے۔ اور اس کا ان پر کچھ زور نہ تھامگر (ہمارا) مقصود یہ تھا کہ جو لوگ آخرت میں شک رکھتے ہیں ان سے ان لوگوں کو جو اس پر ایمان رکھتے تھے متمیز کردیں۔ اور تمھارا رب ہر چیز پر نگہبان ہے\"۔\nسباکا یہ بند(ڈیم) جس کا علم تاریخ سے ہوتا ہے سن(۵۴۲ء) میں ٹوٹ گیا۔اس بند(ڈیم)کی لمبائی(۱۷۶۰ فٹ) اور چوڑائی(۶۰ فٹ) تھی اس بند کی تعمیر میں بہت سے بادشاہوں نے حصہ لیا اور تعاون کیا۔آج بھی اس وادی کو جس میں یہ بند تھا عرم کہتے ہیں۔ یہ چھٹی صدی سے پہلے بھی ایک بار ٹوٹ چکا تھا۔ لیکن چھٹی صدی ۵۴۲م میں مکمل طور پر ٹوٹ گیا اور قوم سبا پوری طرح بکھر گئی۔\nیہی اللہ تعالی کا قانون ہے کہ وہ کفر کرنے والوں کو ڈھیلا چھوڑتا رہتا ہے لیکن ایک دن ایساآجاتا ہے کہ وہ انھیں اپنی زمین سے برباد اور تہس نہس کرکے بکھیر دیتا اور ان کا وجود مٹا دیتا ہے اورہوتا یہ ہے کہ ان کا ذکر صرف تاریخ کی کتابوں میں ہی رہ جاتا ہے۔ اس بند کے کچھ آثار اور حصےآج بھی پائے جاتے ہیں۔ سن(۱۸۴۳ء) کو آرنولڈ نامی فرانسیسی سائنسدان وہاں تک پہنچنے میں کامیاب ہوگیا۔اس نے جو کچھ اس بند کے بارے میں بتایا وہ یہ ہے کہ وہ بند دو پہاڑوں کے بیچ بنا ہوا ہے۔اس کو مٹی اور پتھروں کو آپس میں جوڑ ملا کر بنایا گیا ہے۔ ان دونوں پہاڑوں کے نچلے حصے میں پانی نکلنے کےلیے راستہ بنایا گیا ہے۔ وہاں سے پانی نکل کر کھیتوں کی سنچائی کرتا ہے۔ان راستوں کو بند کرنے کے لیے بھاری بھاری اور بڑے بڑے دروازے بنائے گئے ہیں۔ ضرورت کے مطابق پانی چھوڑا جاتا ہے پھر بند کردیا جاتا ہے۔\nکہتے ہیں کہ اس بند کو مختلف بادشاہوں کے عہد حکومت میں اونچا اور بڑا بنایا جاتا رہا، یہاں تک کہ سن(۳۰۰ء) میں پوری طرح بن کر تیار ہوا اور سن۵۴۲م میں صرف ایک مرتبہ کے سیلاب میں پوری طرح تباہ برباد ہوگیا۔","",{}],[347,"§سيناء\nیہ وہ ریگستان ہے جو خلیج عقبہ اورخلیج سویز کے درمیان میں واقع ہے۔ اس کی لمبائی تقریبا تین سو (۳۰۰)کیلو میٹر اور چوڑائی تقریبا ایک سو پچاس (۱۵۰)کیلو میٹر ہے۔ بنی اسرائیل اسی صحراے سیناء میں چالیس سال تک بھٹکتے رہے۔ سیناءایک پہاڑ کا بھی نام ہے،جس کو طور سیناء کہتے ہیں۔ موسیٰ علیہ السلام کو اسی پہاڑ پر اللہ تعالیٰ نے اپنی کتاب تورات عطا کی تھی۔ قرآن کریم کے اندر دو جگہوں پر لفظ سیناء کا استعمال لفظ طور کے ساتھ ہوا ہے:\n۱- ﴿وَشَجَرَةࣰ تَخۡرُجُ مِن طُورِ سَيۡنَآءَ تَنۢبُتُ بِٱلدُّهۡنِ وَصِبۡغࣲ لِّلۡأٓكِلِينَ﴾ [المومنون: ۲۰] \"اور وہ درخت بھی (ہم ہی نے پیدا کیا) جو طور سینا میں پیدا ہوتا ہے (یعنی زیتون کا درخت کہ) کھانے کے لیے روغن اور سالن لیے ہوے اُگتا ہے\"۔\n۲- ﴿وَٱلتِّينِ وَٱلزَّيۡتُونِ وَطُورِ سِينِينَ﴾ [التین: ۱-۲] \"انجیر کی قسم اور زیتون کیاور طور سینین کی\"۔یہ طورسینین وہی طور سینا ہے، جس پہاڑ پر موسیٰ علیہ السلام کو تورات دی گئی۔ سیناء ایک پہاڑ کا بھی نام ہے جس کو حوریب پہاڑ بھی کہتے ہیں۔جس کا تذکرہ تورات کے اندر بار بار آیا ہے جہاں بنی اسرائیل نے اپنا ڈیرا ڈالا اور پھر ان کے ساتھ مختلف قسم کے مصائب وآلام پیش آئے تھے۔","",{}],[348,"§شادی بیاہ\nدیکھیے: نکاح","",{}],[349,"§شاکر\nدیکھیے: اسماےحسنی","",{}],[350,"§شب قدر\nدیکھیے: لیلۃ القدر","",{}],[351,"§شخصی آزادی\nدیکھیے: حریت","",{}],[352,"§شراب\nدیکھیے: خمر","",{}],[353,"§شرک\nاللہ تعالیٰ نے انسان کوتوحیدکی فطرت پر پیدا کیا۔ لیکن جیسے جیسے وقت گزرتا رہا،توحید پر یقین کمزور پڑتا گیا۔انسانی زندگی میں شرک سرایت کرنے لگا۔ اللہ تعالیٰ نے اس بھولے ہوے سبق کو یاد دلانے اور شرک کے نقصان اور انجام سے لوگوں کو خبردار کرنے کے لیے مختلف قسم کے ذرائع کا استعمال کیا۔ تاکہ قیامت میں کوئی یہ نہ کہہ سکے کہ ہمارے پاس کوئی یاد دلانے والا نہیں آیا۔ ان ذرائع میں سے کچھ اہم ذرائع مندرجہ ذیل ہیں :\n§۱- انبیاورسل کی سلسلہ واربعثت:\nارشادباری تعالیٰ ہے: ﴿يَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ أَلَمۡ يَأۡتِكُمۡ رُسُلࣱ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَاۚ قَالُواْ شَهِدۡنَا عَلَىٰٓ أَنفُسِنَاۖ وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ﴾ [الأنعام: ۱۳۰] \"اے جنوں اور انسانوں کے گروہ! کیا تمھارے پاس خود تمھیں میں سے رسول نہیں آئےجو تمھیں میری آیتیں سناتے اور اس دن کے آجانے سے ڈراتے؟ وہ کہیں گے: کیوں نہیں! (رسول تو آئے تھے) ہم خود اپنے خلاف گوہ ہیں، انھیں تو دُنیوی زندگی نے دھوکے میں رکھ مگر اب وہ خود اپنے خلاف گواہی دیں گے کہ وہ انکار کرنے والے تھے\"۔\nاورفرمایا: ﴿ثُمَّ أَرۡسَلۡنَا رُسُلَنَا تَتۡرَاۖ كُلَّ مَا جَآءَ أُمَّةࣰ رَّسُولُهَا كَذَّبُوهُۖ فَأَتۡبَعۡنَا بَعۡضَهُم بَعۡضࣰ ا وَجَعَلۡنَٰهُمۡ أَحَادِيثَۚ فَبُعۡدࣰ ا لِّقَوۡمࣲ لَّا يُؤۡمِنُونَ﴾ [المؤمنون: ۴۴] \"پھر ہم نے لگاتار رسول بھیجےجب جب جس امت کے پاس اس کا رسول آیا اس نے جھٹلایا، پس ہم نے ایک کو دوسرے کے پیچھے لگا دیا اور انھیں افسانہ بنا دیا۔ ان لوگوں کو دوری ہے جو ایمان قبول نہیں کرتے\"۔\nان نبیوں نے بھولے ہوے سبق کو یاد دلایا: ﴿أَلَمۡ أَعۡهَدۡ إِلَيۡكُمۡ يَٰبَنِيٓ ءَادَمَ أَن لَّا تَعۡبُدُواْ ٱلشَّيۡطَٰنَۖ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِينࣱ وَأَنِ ٱعۡبُدُونِيۚ هَٰذَا صِرَٰطࣱ مُّسۡتَقِيمࣱ‏﴾ [یس: ۶۰-۶۱] \"اے اولاد آدم! کیا میں نے تمھیں تاکید نہیں کی تھی کہ تم شیطان کی عبادت (اطاعت) نہ کرنا۔وہ تمھارا کھلا ہوا دشمن ہے اور میری ہی عبادت کرنا، سیدھا راستا یہی ہے\"۔\n۲- ہر نبی نے اپنی قوم کواللہ کی عبادت کرنےاور شرک سےدوررہنے کی تعلیم دی:\nارشادباری تعالیٰ ہے: ﴿وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٍ إِلَّا نُوحِيٓ إِلَيۡهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدُونِ﴾ [الأنبیاء: ۲۵] \"اے محمد! آپ سے پہلے بھی جو رسول ہم نے بھیجا اس کی طرف یہی وحی نازل فرمائی کہ میرے سوا کوئی معبود برحق نہیں، پس تم سب میری ہی عبادت کرو\"۔\nنوح علیہ السلام نے اپنی قوم سے کہا: ﴿يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمࣲ‏﴾ [الأعراف: ۵۹] \" اے میری قوم کے لوگو! اللہ کی عبادت کرو۔ اس کے سوا تمھارا کوئی الہ (معبود) نہیں۔ مجھے تمھارے بارے میں ایک بھاری دن کے عذاب کا ڈر ہے\"۔\nہود علیہ السلام نے کہا: ﴿يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ﴾ [الأعراف: ۶۵] \"اے میری قوم! اللہ کی عبادت کرو، اس کے سوا تمھارا کوئی الہ (معبود) نہیں تو کیا تم ڈرتے نہیں\"۔\nیعنی تم اللہ کے ساتھ دوسروں کو شریک کرنے سے ڈرتے نہیں۔\nصالح علیہ السلام نے کہا : ﴿وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحࣰ اۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةࣱ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةࣰۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءࣲ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمࣱ‏﴾ [الأعراف: ۷۳] \"اے میری قوم کے لوگو! اللہ کی عبادت کرو، اس کے سوا تمھارا کوئی الٰہ (معبود) نہیں۔ تمھارے پاس تمھارے رب کی طرف سے واضح دلیل آچکی ہے\"۔\nشعیب علیہ السلام نے کہا: ﴿وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبࣰ اۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةࣱ مِّن رَّبِّكُمۡۖ فَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَاۚ ذَٰلِكُمۡ خَيۡرࣱ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ﴾ [الأعراف: ۸۵] \"اے میری قوم کے لوگو! اللہ کی عبادت کرو، اس کے سوا تمھارا کوئی الہٰ (معبود) نہیں۔ تمھارے پاس تمھارے رب کی جانب سے کھلی دلیل آچکی ہے\"۔\nتمام انبیاورسل کی دعوت اللہ کی عبادت اورشرک سے پرہیزکی تھی: ﴿وَلَقَدۡ بَعَثۡنَا فِي كُلِّ أُمَّةࣲ رَّسُولًا أَنِ ٱعۡبُدُواْ ٱللَّهَ وَٱجۡتَنِبُواْ ٱلطَّٰغُوتَۖ فَمِنۡهُم مَّنۡ هَدَى ٱللَّهُ وَمِنۡهُم مَّنۡ حَقَّتۡ عَلَيۡهِ ٱلضَّلَٰلَةُۚ فَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ﴾ [النحل: ۳۶] \"ہم نے ہر قوم میں کوئی نہ کوئی رسول بھیجا (اس پیغام کے ساتھ) کہ اللہ کی عبادت کرو اور طاغوت سے بچو، تو ان میں کسی کوااللہ نے ہدایت دی اور ان میں سے کسی کا گمراہ ہونا ثابت ہوگیا، پس تم زمین میں چل پھر کر دیکھو کہ جھٹلانے والوں کا کیسا انجام ہوا\"۔\nلقمان نے بھی اپنے بیٹے کو شرک سے روکا: ﴿وَإِذۡ قَالَ لُقۡمَٰنُ لِٱبۡنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَيَّ لَا تُشۡرِكۡ بِٱللَّهِۖ إِنَّ ٱلشِّرۡكَ لَظُلۡمٌ عَظِيمࣱ‏﴾ [لقمان: ۱۳] \"یاد کرو جب لقمان نے اپنے بیٹے سے کہا جب کہ وہ اسے نصیحت کر رہے تھے : اے میرے بیٹے! اللہ کے ساتھ شرک نہ کرو۔ يقيناً شرک بہت بڑا ظلم ہے\"۔\n۳- اللہ تعالیٰ نے اپنے ایک ہونے کے لیے اس کائنات میں بے شمار دلیلیں چھوڑ رکھی ہیں، جن کے ذریعےسے کوئی بھی عقل مند اللہ کی توحید تک پہنچ سکتا ہے اور اس کے ساتھ کسی طرح کی شرکت کا انکارکرسکتا ہے: ﴿ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ فِرَٰشࣰ ا وَٱلسَّمَآءَ بِنَآءࣰ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءࣰ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزۡقࣰ ا لَّكُمۡۖ فَلَا تَجۡعَلُواْ لِلَّهِ أَندَادࣰ ا وَأَنتُمۡ تَعۡلَمُونَ﴾ [البقرة: ۲۲] \"وہی ہے جس نے تمھارے لیےزمین کو بچھونا اور آسمان کوچھت بنایا اور آسمان سے پانی اتارا اور اس کے ذریعےسے تمھارے رزق کے لیے ہر طرح کے کھانے کی چیزیں پیدا کی، تو اللہ کا ہمسر نہ بناؤ اور تم (اس بات کو) تو جانتے ہو\"۔\n۴- آخر میں اللہ تعالیٰ نے خاتم الانبیامحمد صلی اللہ علیہ وسلم کو بھیج کر ہر طرح کے شرک کے دروازے بند کردیے۔ اس لیے اب شرک کرنے والوں کے لیے کوئی بہانا نہیں ہے، جب کہ مشرکین عذاب کے ڈر سے یہی کہیں گے: ﴿ثُمَّ لَمۡ تَكُن فِتۡنَتُهُمۡ إِلَّآ أَن قَالُواْ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشۡرِكِينَ﴾ [الأنعام: ۲۳] \"اللہ کی قسم، جو ہمارا رب ہے، ہم مشرک نہیں تھے\"۔\nلیکن وہ اپنے اس دعوے میں جھوٹے ہوں گے۔ اس لیے قیامت کے دن ان کے منہ پر مہر لگا دی جائے گی، تاکہ ان کے ہاتھ پیر گواہی دیں : ﴿ٱلۡيَوۡمَ نَخۡتِمُ عَلَىٰٓ أَفۡوَٰهِهِمۡ وَتُكَلِّمُنَآ أَيۡدِيهِمۡ وَتَشۡهَدُ أَرۡجُلُهُم بِمَا كَانُواْ يَكۡسِبُونَ﴾ [یس: ۶۵] \"ہم آج کے دن ان کے منہ پر مہر لگا دیں گے۔ اور ان کے ہاتھ ہم سے باتیں کریں گے اور ان کے پیر گواہی دیں گے اس کی جو کچھ وہ کرتے تھے\"۔\nاس لیے اللہ تعالی شرک کرنے والوں کو کبھی معاف نہیں کرے گا۔ارشادباری تعالیٰ ہے: ﴿إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدِ ٱفۡتَرَىٰٓ إِثۡمًا عَظِيمًا﴾ [النساء: ۴۸] \"یقینا اللہ اس کو معاف نہیں کرے گا کہ اس کا شریک ٹھہرایا جائے۔ اور اس کے سوا جو گناہ ہے، اسے جس کے لیے چاہے گا معاف کر دے گا اور جس نے اللہ کا شریک ٹھہرایا، اس نے بہت بڑا گناہ کیا\"۔\nايک دوسری جگہ فرمایا: ﴿إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا﴾ [النساء: ۱۱۶] \"بلاشبہ اللہ اس کو معاف نہیں کرے گا جس نے اس کے ساتھ کسی کو شریک بنایا اور اس کے علاوہ جسے چاہے معاف کردے اورجس نے اللہ کے ساتھ کسی کو شریک ٹھہرایا وہ گمراہ ہو کر بہت دور جاپڑا\"۔\nعبد اللہ بن مسعود رضی اللہ عنہ کہتےہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سےپوچھا: «أَيُّ الذَّنْبِ أَعْظَمُ عِنْدَ اللَّهِ؟ قَالَ: أَنْ تَجْعَلَ لِلَّهِ نِدًّا وَهُوَ خَلَقَکَ، قُلْتُ: إِنَّ ذَلِکَ لَعَظِيمٌ، قُلْتُ: ثُمَّ أَيُّ؟ قَالَ: وَأَنْ تَقْتُلَ وَلَدَکَ تَخَافُ أَنْ يَطْعَمَ مَعَکَ، قُلْتُ: ثُمَّ أَيُّ؟ قَالَ: أَنْ تُزَانِيَ حَلِيلَةَ جَارِکَ». (صحیح البخاری: ۴۴۷۷، وصحیح مسلم: ۸۶/۱۴۱) \"سب سے بڑاگناہ کیا ہے؟۔آپ نے فرمایا: تم کسی کو اللہ کا ہمسر ٹھہراؤ، جب کہ اسی نے تم کو پیدا کیا۔میں نے پوچھا: پھر اس کے بعد؟ فرمایا: تم اپنی اولاد کو اس ڈر سے قتل کردو کہ وہ تمھارے ساتھ تمھاری کمائی میں سے کھائیں، میں نے پوچھا: پھر اس کے بعد؟ فرمایا: یہ کہ تم اپنے پڑوسی کی بیوی سے زنا کرو\"۔\nدوسری صحیح حدیث میں ابو بکرہ رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس تھے،آپ نے تین بار فرمایا: «أَلا أُنَبِّئُکُمْ بِأَکْبَرِ الْکَبَائِرِ ثَلاثًا: الإِشْرَاکُ بِاللَّهِ وَعُقُوقُ الْوَالِدَيْنِ وَشَهَادَةُ الزُّورِ أَوْ قَوْلُ الزُّورِ». (صحیح مسلم: ۱۴۳/۸۷) \"کیا میں تم لوگوں کو نہ بتاؤ ں کہ گناہ اکبر کیا ہے؟ لوگوں نے کہا: ہاں! اے اللہ کے رسول!آپ صلی اللہ علیہ وسلم نےفرمایا: اللہ کے ساتھ کسی کو شریک بنانا، ماں باپ کا حکم نہ ماننا اور جھوٹی گواہی دینا\"۔\nايک اورصحيح حديث میں فرمايا: «اجْتَنِبُوا السَّبْعَ الْمُوبِقَاتِ، قِيلَ: يَا رَسُولَ اللَّهِ وَمَا هُنَّ؟ قَالَ: الشِّرْکُ بِاللَّهِ، وَالسِّحْرُ، وَقَتْلُ النَّفْسِ الَّتِي حَرَّمَ اللَّهُ إِلا بِالْحَقِّ، وَأَکْلُ مَالِ الْيَتِيمِ، وَأَکْلُ الرِّبَا، وَالتَّوَلِّي يَوْمَ الزَّحْفِ، وَقَذْفُ الْمُحْصِنَاتِ الْغَافِلاتِ الْمُؤْمِنَاتِ». (صحیح مسلم: ۱۴۵/۸۹ بروایت ابوہریرہ رضی اللہ عنہ )\n\"سات تباہ کرنے والی چیزوں سے بچے رہو۔ لوگوں نے پوچھا: وہ کیا ہیں؟ آپ نے فرمایا: اللہ کےساتھ کسی کو شریک بنانا، جادو کرنا، کسی کو ناحق قتل کرنا، سود کھانا، یتیم کا مال کھانا، جہاد میں میدان سے منہ موڑ کر بھاگنا اور مومن پاک دامن عورتوں پر جھوٹی تہمت لگانا\"۔\nجب سورہ الممتحنہ کی آیت: ۱۲ اتری تو نبی اکرم صلی اللہ علیہ وسلم نے عورتوں سےجن باتوں کی بیعت لی ان میں ایک یہ بھی تھی کہ اللہ کے ساتھ کسی کو شریک نہیں بنائیں گی۔\nام عطیہ ڤکہتی ہیں: «بَايَعْنَا رَسُولَ اللهِ صلی اللہ علیہ وسلم، فَقَرَأَ عَلَيْنَا:﴿أَن لَّا يُشۡرِكۡنَ بِٱللَّهِ شَيۡـࣰٔ﴾ [الممتحنة: ۱۲]» \" ہم نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی تو آپ نے ہم پر یہ آیت تلاوت فرمائی: مسلمان عورتیں اللہ کے ساتھ کسی کو شریک نا ٹہرائیں\"۔ (صحیح البخاری:۴۸۹۲)\nنبی اکرم صلی اللہ علیہ وسلم مردوں سے بھی اسی توحیدپرقائم رہنے اورشرک سے دوررہنے کی بیعت لیتے تھے:\nجریر بن عبداللہ رضی اللہ عنہ کہتے ہیں: «بَايَعْتُ رَسُولَ اللَّهِ صلی اللہ علیہ وسلم عَلَی شَهَادَةِ أَنْ لا إِلَهَ إِلا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ». (صحیح البخاری: ۵۷، وصحیح مسلم: ۵۶/۹۷) \"میں نے نبی اکرم صلی اللہ علیہ وسلم کے ہاتھ پر جو بیعت کی اس میں یہ بھی تھی اللہ تعالیٰ کے سوا کوئی حقیقی معبود نہیں اور محمد اللہ کے رسول ہیں\"۔\n§شرک کی ابتدا کیسے ہوئی؟\nشرک کی سب سے بڑی وجہ شیطان کا بہکانا ہے۔ جب کسی نبی یا عظیم ہستی کی وفات ہوجاتی تھی تو ان کے پیروکار بڑے رنج و غم میں پڑ جاتے تھے۔ ایسی حالت میں ان کے سوچنے سمجھنے کی قوت سلب ہوجاتی تھی۔ بس اس وقت کو شیطان غنیمت سمجھ کر یہ کہتا کہ آؤ میں تم لوگوں کا غم دور کرنے کی کوئی ترکیب بتاتاہوں۔ ان میں سے ایک یہ کہ مرنے والے کی قبر پر ایک عبادت گاہ بنالو تاکہ قبر زمین کے مساوی نہ ہوجائے اورجب عبادت گاہ بن جاتی تو پھر اس میں عبادت کرتے کرتے کبھی قبر کو بھی سجدہ کر لیتے، کبھی اس کا طواف کرنے لگتے اور پھر دھیرے دھیرے اسی قبر سے اپنی ضرورتیں بیان کرنے لگتے یہاں تک کہ وہ بندہ جو خود پوری زندگی اللہ کی عبادت میں گزار کر اس دنیا سے چلا گیا تھا، اب وہی خود معبود بن جاتا۔ اسی لیےنبی اکرم صلی اللہ علیہ وسلم نے قبروں کو پکی کرنے سے منع فرمایا ہے۔ثمامہ بن شفی کہتے ہیں: ہم لوگ فضالہ بن عبید رضی اللہ عنہ کے ساتھ سر زمین روم میں رودس تھے کہ ہمارا ایک ساتھی انتقال کر گیا، تو فضالہ بن عبید رضی اللہ عنہ نے اس کی قبر کے بارے میں حکم دیا تو وہ برابر کر دی گئی، پھر انھوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا :آپ قبر کو برابر کرنے کا حکم دیتے تھے\"۔ (صحیح مسلم: ۹۲/۹۶۸)\nاب ایک طرف نبی اکرم صلی اللہ علیہ وسلم کا یہ حکم دیکھیے اوردوسری طرف قبر وں پر چڑھاوے چڑھانا، ان کو پکی کرنااور ان پر مسجدیں بنوانا دیکھیے۔ یہ سب شیطان کے بہکاوے نہیں تو اور کیا ہیں؟ شیطان کے بہکاوے میں سے ایک یہ بھی تھاکہ جب کوئی نبی،عظیم ہستی،عابد وغیرہ کی موت ہوجاتی تھی تو ان کے پیروکاروں سے وہ کہتا تھا کہ آپ اتنے غمگین نہ ہوں۔میں ان کیا مجسمہ بنا دیتا ہوں۔ اس کو سامنے رکھ کر اپنے رب کا ذکرکرو، آپ کا غم دور ہوجائے گا۔اس طرح انسان کے ہاتھ کی بنائی ہوئی مورتی (صنم )کی پوجا ہونے لگی۔قرآن مجید نے اس کی طرف کتنے خوبصورت انداز میں اشارہ کیا ہے: ﴿ٱلطَّالِبُ وَٱلۡمَطۡلُوبُ﴾ [الحج: ۷۳] \"پوجنے والا اور جس کی پوجا کی جائے دونوں کتنے کمزور ہیں\"۔\nدرحقیقت شیطان کا کام یہی ہے کہ نت نئی تدبیر سوچ کر انسان کو اللہ کی عبادت سے دور کرتا رہے۔","",{}],[354,"§شِعری\nشِعریٰ ایک ستارے کا نام ہے، جو گرمیوں میں نکلتا ہے۔ عرب کے ایک قبیلے بنوخزاعہ کے لوگ اس کی عبادت کرتے تھے۔اس کے نام پر قربانی دیتے اور اس سے اپنی حاجتیں مانگتے تھے۔ جب کہ اس ستارے اور پوری کائنات کا رب اورحقیقی معبود تو صرف اللہ ہے۔ قرآن میں ایک جگہ پر اسی کی طرف اشارہ کیا گیا ہے:﴿وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعۡرَىٰ﴾ [النجم: ۴۹] \"اور یہ کہ وہی ہے جو شعریٰ (ستارے) کا رب ہے\"۔\nجیسے ساری کائنات کا رب اللہ ہے اسی طرح شعریٰ کا بھی رب وہی ہے۔ تو پھر اس کی عبادت کیوں؟","",{}],[355,"§شعيب علیہ السلام\nشعیب علیہ السلام کو اللہ تعالیٰ نے نبی بنا کر مدین والوں کی طرف بھیجا۔ ان کی قوم مدین میں آباد تھی۔مدین کا نام ابراہیم علیہ السلام کے بیٹے مدیان کے نام پر رکھا گیا تھا۔ مدیان ابراہیم کی بیوی قطورہ سے پیدا ہوا تھا۔ مدین قوم خلیج عقبہ کے مشرقی اور مغربی ساحل پر آباد تھی۔ شعیب علیہ السلام ان کی چوتھی پشت میں سے تھے۔ اسی لیے قرآن کریم نے ان کو ’اخ‘ یعنی بھائی کے نام سے مخاطب کیا: ﴿وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبࣰ اۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةࣱ مِّن رَّبِّكُمۡۖ فَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَاۚ ذَٰلِكُمۡ خَيۡرࣱ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ﴾ [الأعراف: ۸۵] \"مدین کی طرف ان کے بھائی شعیب کو بھیجا\"۔\nاورفرمایا: ﴿وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبࣰ اۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ وَلَا تَنقُصُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَۖ إِنِّيٓ أَرَىٰكُم بِخَيۡرࣲ وَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمࣲ مُّحِيطࣲ‏﴾ [ہود: ۸۴] \"مدین والوں کی طرف ان کے بھائی شعیب کو بھیجا\"۔\nشعیب علیہ السلام نے بھی دوسرے انبیا کی طرح اپنی قوم کو ایک اللہ کی عبادت کی طرف دعوت دی۔ کیوں کہ یہی تمام انبیاورسل کی دعوت کاخلاصہ تھا۔ اسی کے ساتھ ان کی قوم بہت ساری برائیوں میں بھی پڑ گئی۔ ناپ تول میں گڑ بڑ کرنے لگی۔لینےمیں زیادہ تولتی اور دینے میں کم۔ ارشادباری تعالیٰ ہے: ﴿وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبࣰ اۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةࣱ مِّن رَّبِّكُمۡۖ فَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَاۚ ذَٰلِكُمۡ خَيۡرࣱ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ﴾ [الأعراف: ۸۵] \"اس نے کہا: اے میری قوم کے لوگو! اللہ کی عبادت کرو، اس کے سوا تمھارا کوئی الہ (معبود برحق) نہیں۔ تمھارے پاس تمھارے رب کی کھلی دلیل آچکی ہے۔ تو تم پورا پورا ناپو اور تولو اور لوگوں کو ان کی چیزوں میں کم کرکے نہ دو۔ اور زمین میں فساد نہ مچاؤ جبکہ اس کا سدھار ہو چکا ہو\"۔\nناپ تول میں کمی سے فساد پھیلتا ہے، کیوں کہ لوگوں کے دل ایک دوسرے سے پھر جاتے ہیں۔ جس سے باہمی رضا ومحبت ختم ہوجاتی ہےجو فسادکاباعث بن جاتا ہے۔ارشادباری تعالیٰ ہے: ﴿وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبࣰ اۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ وَلَا تَنقُصُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَۖ إِنِّيٓ أَرَىٰكُم بِخَيۡرࣲ وَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمࣲ مُّحِيطࣲ‏﴾ [ہود: ۸۴] \"اس نے کہا:اے میری قوم کے لوگو! اللہ کی عبادت کرو، اس کے سوا تمھارا کوئی الہ(معبود برحق)نہیں اور تم ناپ تول میں کمی بھینہ کیا کرو\"۔\nلیکن شعیب علیہ السلام کی قوم بھی اپنے خود ساختہ بتوں کی عبادت سے نہ رکی۔بلکہ الٹا انھوں نے نبی کو ڈرایا دهمکایا:﴿قَالُواْ يَٰشُعَيۡبُ أَصَلَوٰتُكَ تَأۡمُرُكَ أَن نَّتۡرُكَ مَا يَعۡبُدُ ءَابَآؤُنَآ أَوۡ أَن نَّفۡعَلَ فِيٓ أَمۡوَٰلِنَا مَا نَشَٰٓؤُاْۖ إِنَّكَ لَأَنتَ ٱلۡحَلِيمُ ٱلرَّشِيدُ﴾ [ہود: ۸۷] \"اے شعیب!کیا تمھاری نماز تجھے یہی حکم دیتی ہے کہ ہم اسے چھوڑ دیں جسے ہمارے آباؤ اجداد پوجتے آئے ہیں\"۔\nمشرک اس بات پر بڑی مضبوطی سے جمے رہتے ہیں،جس پر انھوں نے اپنے آباو اجداد کو پایا ہے۔ ان کو لاکھ سمجھائیں کہ یہ کام غلط ہے۔ االلہ کے قانون اور اس کےنبیوں کی تعلیم کےخلاف ہے، مگر وہ کسی طرح اسےچھوڑنے کو تیار نہیں ہوتے، بلکہ ان کی وہی دلیل ہوتی ہے کہ جو کام ہمارے باپ دادا کرتے آئے ہیں،اسے کیسے چھوڑ دیں۔ کیا تم ہی سب سے بڑے عالم ہو؟ شعیب کی قوم نے کہا : ﴿قَالُواْ يَٰشُعَيۡبُ أَصَلَوٰتُكَ تَأۡمُرُكَ أَن نَّتۡرُكَ مَا يَعۡبُدُ ءَابَآؤُنَآ أَوۡ أَن نَّفۡعَلَ فِيٓ أَمۡوَٰلِنَا مَا نَشَٰٓؤُاْۖ إِنَّكَ لَأَنتَ ٱلۡحَلِيمُ ٱلرَّشِيدُ﴾ [ہود: ۸۷] \"(کیا) تو ہی ایک صحیح اور باوقار آدمی رہ گیا ہے؟\"\nپھروہ دھمکی پر اتر آئے۔اس سلسلے میں قرآن مجیدکاارشادہے: ﴿قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لَنُخۡرِجَنَّكَ يَٰشُعَيۡبُ وَٱلَّذِينَ ءَامَنُواْ مَعَكَ مِن قَرۡيَتِنَآ أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۚ قَالَ أَوَلَوۡ كُنَّا كَٰرِهِينَ﴾ [الأعراف: ۸۸] \"اس کی قوم کے سرداروں نے جو اپنے آپ کو بڑا سمجھتے تھے، کہا: اے شعیب!ہم تجھے اور ان لوگوں کو جو تمھارے ساتھ ایمان لائے ہیں، اپنی بستی سے نکال دیں گے۔ یا پھر تم ہمارے معاشرہ (سماج) میں لوٹ آؤ\"۔\nاورپھر انھوں نے اپنی قوم کے لوگوں سے بھی کہا:﴿وَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ لَئِنِ ٱتَّبَعۡتُمۡ شُعَيۡبًا إِنَّكُمۡ إِذࣰ ا لَّخَٰسِرُونَ﴾ [الأعراف: ۹۰] \" اگر تم شعیب کے پیر وکاربنے تو یقیناً تم خسارے میں پڑ جاؤ گے\"۔\nشعیب کی قوم کا بھی ویسا ہی انجام ہوا جیسا اس سے پہلے دوسری قوموں کا ہوچکا تھا۔ان کو بھی اللہ کے عذاب نےاپنی گرفت میں لےلیا۔ارشادباری تعالی ہے: ﴿فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ ٱلَّذِينَ كَذَّبُواْ شُعَيۡبࣰ ا كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَاۚ ٱلَّذِينَ كَذَّبُواْ شُعَيۡبࣰ ا كَانُواْ هُمُ ٱلۡخَٰسِرِينَ﴾ [الأعراف: ۹۱-۹۲] \"بالآخر زلزلےنےانهیں آپکڑا اور وہ اپنے گھروں میں اوندھے منہ پڑے رہ گئے۔ جن لوگوں نے شعیب کو جھٹلایا،ان کی حالت ایسی ہوگئی مانووہ کبھی یہاں بسے ہی نہیں تھے۔شعیب کو جھٹلانے والے ہی گھاٹے میں رہے\"۔\nاورفرمایا: ﴿وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا شُعَيۡبࣰ ا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةࣲ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ﴾ [ہود: ۹۴] \"جب ہمارا حکم آپہنچا تو ہم نے پنی مہربانی (رحم دلی) سے شعیب اور ان لوگوں کو جو اس کے ساتھ ایمان لائے تھے، بچا لیا۔ اور جن لوگوں نے ظلم کیا تھا انھیں ایک خوف زدہ کر دینے والی چیخ نے آلیا اور وہ اپنے گھروں میں اوندھے منہ پڑے رہ گئے\"۔\nپھرشعیب علیہ السلام مدین سے نکل کر ایکہ کی طرف چلے گئے۔ ایکہ ایک جنگل تھا اوربحراحمر (قلزم) کے کنارے پھیلا ہوا تھا۔ان لوگوں کو بھی شعیب نے اللہ کاپیغام پہنچایا۔اس قوم کے متعلق کچھ نہیں کہا جاسکتا، تاہم اتنی بات ضرور ہے کہ یہ شعیب کی نسل کے لوگ نہیں تھے۔ اس لیے ان کو بھائی کہہ کر نہیں پکارا۔ لیکن ان لوگوں نے بھی شعیب کی دعوت کا انکار کر دیا: ﴿كَذَّبَ أَصۡحَٰبُ لۡـَٔيۡكَةِ ٱلۡمُرۡسَلِينَ إِذۡ قَالَ لَهُمۡ شُعَيۡبٌ أَلَا تَتَّقُونَ إِنِّي لَكُمۡ رَسُولٌ أَمِينࣱ‏﴾ [الشعراء: ۱۷۶-۱۷۸] \"الایکہ(جنگل کےرہنے) والوں نے بھی رسولوں کو جھٹلایا۔ جب ان سے شعیب نے کہا: کیا تم لوگ(اللہ سے) ڈرتے نہیں؟ یقینا میں تمھارے لیے ایک امانت دار (بااعتماد) رسول ہوں\"۔\nیعنی تم لوگ بھی اللہ کو چھوڑ کر دیوی،دیوتاؤ ں اور پیروں فقیروں کی پوجا کرتے ہو جب کہ تم کو پیداکرنے والا اور رزق دینے والا تو اللہ ہی ہے۔ جس کو تم خوب جانتے ہو۔ اور پھر ناپ تول میں بھی کمی کرتے ہو۔\nاس سلسلے میں قرآن مجیدمیں ارشادہے: ﴿أَوۡفُواْ ٱلۡكَيۡلَ وَلَا تَكُونُواْ مِنَ ٱلۡمُخۡسِرِينَ وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ﴾ [الشعراء: ۱۸۱-۱۸۳] \"تو تم پورا پورا پیمانہ بھرو اور کم دینے والوں میں مت بنو اورسیدھی صحیح ترازو سے تولو۔ اور لوگوں کو ان کی چیزوں کمی سے نہ دو اور زمین میں فساد نہ پھیلاتے پھرو\"۔\nمگر ایکہ والوں نے بھی شعیب کی بات نہ مانی۔ انھوں نےبھی ان کو جھٹلا دیا۔ جس کی وجہ سے ان کو بھی اللہ کے عذاب نے پکڑ لیا۔چنانچہ ان کے انجام کے بارے میں ارشادباری تعالیٰ ہے: ﴿فَكَذَّبُوهُ فَأَخَذَهُمۡ عَذَابُ يَوۡمِ ٱلظُّلَّةِۚ إِنَّهُۥ كَانَ عَذَابَ يَوۡمٍ عَظِيمٍ﴾ [الشعراء: ۱۸۹] \"انھوں نے اسے جھٹلا دیا، تو سائے والے دن کے عذاب نے انھیں پکڑ لیا\"۔\nاس طرح قرآن ایک ایک قوم کا ذکر کرتاہے، جن کی طرف رسول مبعوث کئے گئے۔ انھوں نے رسولوں کو جھٹلایا، پھر ان کا انجام بہت برا ہوا۔\nنبی اکرم محمد صلی اللہ علیہ وسلم بھی اللہ کے سچے رسول ہیں، جو قرآن لے کر آئے۔ اس لیے ان واقعات کی تفصیل کاخلاصہ یہ ہےکہ اب اگر تم لوگوں نے ان کو اور ان کی لائی ہوئی کتاب قرآن کو جھٹلایا تو تمھارا انجام بھی ویسا ہی ہوگا جیسا پچھلی قوموں کا ہوا۔ شعیب علیہ السلام ایکہ کے عذاب کےبعد کہاں گئے اس تعلق سےقرآن اورصحیح حدیثوں میں کچھ نہیں آیا۔ لیکن جیسا کہ اس سے پہلے کہا جاچکا ہےکہ کچھ علماکی رائے ہےکہ وہ بھی دوسرے نبیوں کی طرح مکہ چلے گئے اوروہیں ان کی وفات ہوئی۔ مگراس رائے پر مکمل یقین نہیں کیا جاسکتا۔کچھ کی رائے ہے کہ وہ ایکہ کی تباہی کے بعد بھی ایکہ کے جنگلوں میں اللہ کی عبادت کرتے رہے اور وہیں آپ کی وفات ہوئی اور دفن کر دیے گئے۔\nرہی یہ بات کہ وہ کس زمانے میں نبی بنائے گئے؟ تو اس بارے میں بعض علماء کی رائے ہےکہ وہ وہی شعیب ہیں، جن کی ملاقات مدین میں موسیٰ علیہ السلام سے ہوئی تھی اور اپنی ایک بیٹی سے ان کا نکاح کیا تھا۔(جس کی تفصیل لفظ: موسیٰ میں دیکھیے)۔کچھ دوسرے علما کی رائے ہے کہ شعیب کوئی اور نبی ہیں۔ ان کا موسیٰ علیہ السلام سے کوئی تعلق نہیں ہے۔مدین کے جس عابد وزاہد سےموسیٰ کی ملاقات ہوئی تھی وہ کوئی دوسرا بھلا آدمی تھا۔جیسا کہ تورات میں آیا ہےکہ وہ مدین کا عظیم عابد تھا جس کا نام پسرون تھا۔ یہی رائے ابن عباس اور دوسرےمفسرین کی ہے۔(دیکھیے: جامع الرسائل لابن تیمیہ) رہے شعیب تو ان کی مدت رسالت اس سے پہلے کی ہے۔ اورقرآن بھی اسی کی طرف اشارہ کرتا ہے۔ سورة الاعراف میں موسیٰ علیہ السلام کا ذکر نوح، ہود،صالح، لوط اور شعیب کے تذکرہ کے بعدآیا ہے: ﴿ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ﴾ [الأعراف: ۱۰۳] \"پھر ان کے بعد ہم نے موسیٰ کو اپنی نشانیوں کے ساتھ فرعون اور اس کے سرداروں کے پاس بھی جا\"۔\nاسی طرح سورہ ہودمیں اللہ تعالیٰ نے پہلے تو نوح علیہ السلام کا ذکر کیا ہے۔(دیکھیے : آیت: ۲۵) پھر ہود کا (دیکھیے: ۵۰) پھر صالح کا (دیکھیے:۶۱)پھر ابراہیم کا (دیکھیے: آیت: ۶۹) پھر لوط کا (دیکھیے: ۷۷) پھر شعیب کا (دیکھیے: آیت: ۸۴) پھر موسیٰ کا (دیکھیے: آیت: ۹۶)۔اس مذکور بالاترتیب سے معلوم ہوتا ہے کہ شعیب،موسیٰ سے پہلے نبی ہوے جو مدین کی تباہی کےبعد ایکہ کے جنگلوں میں چلے گئے۔ وہیں ان کی وفات ہوگئی۔ پھر مدین دوبارہ آباد ہوا۔ اس کے بعد موسیٰ علیہ السلام مصر سے نکل کر وہاں چلے گئے۔ (مزید تفصیل کے لیے دیکھیے : موسیٰ)","",{}],[356,"§شفاعت عظمی(کبریٰ)\nدیکھیے: مقام محمود","",{}],[357,"§شفاعت\nشفاعت کو اردو زبان میں سفارش کہتے ہیں۔ مکہ کے بت پرست یہ یقین رکھتے تھے کہ ان کے مٹی اور پتھر کے بت اللہ تعالیٰ کے پاس سفارش کریں گے۔ قرآن کریم میں ہے: ﴿وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡ وَيَقُولُونَ هَٰٓؤُلَآءِ شُفَعَٰٓؤُنَا عِندَ ٱللَّهِۚ قُلۡ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعۡلَمُ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ﴾ [یونس: ۱۸] \"یہ لوگ اللہ کے سوا ایسی چیزوں کو پوجتے ہیں جو نہ انھیں نقصان پہنچا سکتی ہیں اور نہ کچھ فائدہ اور کہتے ہیں: یہ اللہ کے یہاں ہمارے سفارشی ہیں،کہہ دو: کیا تم اللہ کو اس بات کی خبر دے رہے ہو جسے نہ وہ آسمانوں میں جانتا ہے نہ زمین میں۔ وہ پاک اور برتر ہے ان لوگوں کے شرک سے\"۔\nقرآن میں شفاعت کے لیے یہ شرائط ہیں:\n۱- صرف وہ لوگ سفارش کرسکتے ہیں،جن کو اللہ تعالیٰ سفارش کی اجازت دے گا۔مطلب یہ ہے کہ سفارش کرنے والے بھی اللہ کے حکم سے ہی سفارش کریں گے۔\n۲- صرف ان لوگوں کی سفارش کی جائے گی،جن سے اللہ تعالیٰ خوش اورراضی ہوگااوروہ صرف ایک اللہ کی عبادت کرنےاورشرک سے دوررہنے والےہوں گے۔اس لیے نہ تو ان کی سفارش کی جائے گی جو اللہ کا انکار کرتے ہیں اور نہ ان کی جو اس کے ساتھ شرک کرتے ہیں، کیوں کہ یہ لوگ اللہ کے محبوب بندے نہیں ہیں۔\nقرآن کریم میں کہا گیا ہے: ﴿وَكَم مِّن مَّلَكࣲ فِي ٱلسَّمَٰوَٰتِ لَا تُغۡنِي شَفَٰعَتُهُمۡ شَيۡـًٔا إِلَّا مِنۢ بَعۡدِ أَن يَأۡذَنَ ٱللَّهُ لِمَن يَشَآءُ وَيَرۡضَىٰٓ﴾ [النجم: ۲۶] \"کتنے فرشتے ہیں آسمانوں میں ہیں، جن کی سفارش کچھ کام نہیں دے سکتی، اگر کام دے سکتی ہے تو اس کے بعد ہی کہ اللہ اجازت دے جسے چاہے اور پسند بھی کرے\"۔\nیہ کون لوگ ہیں جن کو اللہ سفارش کااختیار دے گا؟ ان میں سے ایک تو وہ ہیں جن کی بات (سفارش)کو اللہ پسند کرے۔ارشادباری تعالیٰ ہے: ﴿يَوۡمَئِذࣲ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَرَضِيَ لَهُۥ قَوۡلࣰ ا﴾ [طه: ۱۰۹] \"دن سفارش کام نہیں آئے گی سوائے اس کے کہ کسی کو رحمن حکم دے اور اس کی بات کو پسند کرے\"۔\nان سفارش کرنے والوں میں سب سے بڑی شفاعت (سفارش) نبی اکرم محمد صلی اللہ علیہ وسلم کی ہوگی جو آپ اپنی امت کے ليے ميدان حشر میں کریں گے۔ابوہریرہ رضی اللہ عنہ کہتے ہیں: «أُتِيَ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم يَوْمًا بِلَحْمٍ فَرُفِعَ إِلَيْهِ الذِّرَاعُ وَکَانَتْ تُعْجِبُهُ فَنَهَسَ مِنْهَا نَهْسَةً فَقَالَ: أَنَا سَيِّدُ النَّاسِ يَوْمَ الْقِيَامَةِ، وَهَلْ تَدْرُونَ بِمَ ذَاکَ؟ يَجْمَعُ اللَّهُ يَوْمَ الْقِيَامَةِ الأَوَّلِينَ وَالآخِرِينَ فِي صَعِيدٍ وَاحِدٍ فَيُسْمِعُهُمْ الدَّاعِي وَيَنْفُذُهُمْ الْبَصَرُ وَتَدْنُو الشَّمْسُ فَيَبْلُغُ النَّاسَ مِنْ الْغَمِّ وَالْکَرْبِ مَا لا يُطِيقُونَ وَمَا لا يَحْتَمِلُونَ، فَيَقُولُ بَعْضُ النَّاسِ لِبَعْضٍ: أَلا تَرَوْنَ مَا أَنْتُمْ فِيهِ؟ أَلا تَرَوْنَ مَا قَدْ بَلَغَکُمْ؟ أَلا تَنْظُرُونَ مَنْ يَشْفَعُ لَکُمْ إِلَی رَبِّکُمْ؟ فَيَقُولُ بَعْضُ النَّاسِ لِبَعْضٍ: ائْتُوا آدَمَ، فَيَأْتُونَ آدَمَ فَيَقُولُونَ: يَا آدَمُ أَنْتَ أَبُو الْبَشَرِ خَلَقَکَ اللَّهُ بِيَدِهِ وَنَفَخَ فِيکَ مِنْ رُوحِهِ، وَأَمَرَ الْمَلائِکَةَ فَسَجَدُوا لَکَ، اشْفَعْ لَنَا إِلَی رَبِّکَ أَلا تَرَی إِلَی مَا نَحْنُ فِيهِ أَلا تَرَی إِلَی مَا قَدْ بَلَغَنَا؟ فَيَقُولُ آدَمُ؟ إِنَّ رَبِّي غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ، وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ، وَإِنَّهُ نَهَانِي عَنْ الشَّجَرَةِ فَعَصَيْتُهُ، نَفْسِي نَفْسِي، اذْهَبُوا إِلَی غَيْرِي اذْهَبُوا إِلَی نُوحٍ، فَيَأْتُونَ نُوحًا فَيَقُولُونَ: يَا نُوحُ أَنْتَ أَوَّلُ الرُّسُلِ إِلَی الأَرْضِ وَسَمَّاکَ اللَّهُ عَبْدًا شَکُورًا، اشْفَعْ لَنَا إِلَی رَبِّکَ، أَلا تَرَی مَا نَحْنُ فِيهِ؟ أَلا تَرَی مَا قَدْ بَلَغَنَا؟ فَيَقُولُ لَهُمْ: إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ، وَإِنَّهُ قَدْ کَانَتْ لِي دَعْوَةٌ دَعَوْتُ بِهَا عَلَی قَوْمِي، نَفْسِي نَفْسِي اذْهَبُوا إِلَی إِبْرَاهِيمَ صَلَّی اللَّهُ عَلَيْهِ وَسَلَّمَ، فَيَأْتُونَ إِبْرَاهِيمَ فَيَقُولُونَ: أَنْتَ نَبِيُّ اللَّهِ وَخَلِيلُهُ مِنْ أَهْلِ الأَرْضِ، اشْفَعْ لَنَا إِلَی رَبِّکَ، أَلا تَرَی إِلَی مَا نَحْنُ فِيهِ؟ أَلا تَرَی إِلَی مَا قَدْ بَلَغَنَا؟ فَيَقُولُ لَهُمْ إِبْرَاهِيمُ: إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلا يَغْضَبُ بَعْدَهُ مِثْلَهُ، وَذَکَرَ کَذَبَاتِهِ، نَفْسِي نَفْسِي، اذْهَبُوا إِلَی غَيْرِي اذْهَبُوا إِلَی مُوسَی، فَيَأْتُونَ مُوسَی رضی اللہ عنہ فَيَقُولُونَ: يَا مُوسَی أَنْتَ رَسُولُ اللَّهِ فَضَّلَکَ اللَّهُ بِرِسَالاتِهِ وَبِتَکْلِيمِهِ عَلَی النَّاسِ، اشْفَعْ لَنَا إِلَی رَبِّکَ، أَلا تَرَی إِلَی مَا نَحْنُ فِيهِ؟ أَلا تَرَی مَا قَدْ بَلَغَنَا؟ فَيَقُولُ لَهُمْ مُوسَی رضی اللہ عنہ : إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ، وَإِنِّي قَتَلْتُ نَفْسًا لَمْ أُومَرْ بِقَتْلِهَا، نَفْسِي نَفْسِي، اذْهَبُوا إِلَی عِيسَی رضی اللہ عنہ، فَيَأْتُونَ عِيسَی فَيَقُولُونَ: يَا عِيسَی! أَنْتَ رَسُولُ اللَّهِ وَکَلَّمْتَ النَّاسَ فِي الْمَهْدِ وَکَلِمَةٌ مِنْهُ أَلْقَاهَا إِلَی مَرْيَمَ وَرُوحٌ مِنْهُ، فَاشْفَعْ لَنَا إِلَی رَبِّکَ، أَلا تَرَی مَا نَحْنُ فِيهِ؟ أَلا تَرَی مَا قَدْ بَلَغَنَا؟ فَيَقُولُ لَهُمْ عِيسَی رضی اللہ عنہ : إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ، وَلَمْ يَذْکُرْ لَهُ ذَنْبًا، نَفْسِي نَفْسِي اذْهَبُوا إِلَی غَيْرِي اذْهَبُوا إِلَی مُحَمَّدٍ رضی اللہ عنہ، فَيَأْتُونِّي فَيَقُولُونَ: يَا مُحَمَّدُ أَنْتَ رَسُولُ اللَّهِ وَخَاتَمُ الانبيا وَغَفَرَ اللَّهُ لَکَ مَا تَقَدَّمَ مِنْ ذَنْبِکَ وَمَا تَأَخَّرَ، اشْفَعْ لَنَا إِلَی رَبِّکَ، أَلا تَرَی مَا نَحْنُ فِيهِ؟ أَلا تَرَی مَا قَدْ بَلَغَنَا؟ فَأَنْطَلِقُ فَآتِي تَحْتَ الْعَرْشِ، فَأَقَعُ سَاجِدًا لِرَبِّي، ثُمَّ يَفْتَحُ اللَّهُ عَلَيَّ وَيُلْهِمُنِي مِنْ مَحَامِدِهِ وَحُسْنِ الثَّنَاءِ عَلَيْهِ شَيْئًا لَمْ يَفْتَحْهُ لأَحَدٍ قَبْلِي، ثُمَّ يُقَالُ: يَا مُحَمَّدُ ارْفَعْ رَأْسَکَ سَلْ تُعْطَهْ اشْفَعْ تُشَفَّعْ، فَأَرْفَعُ رَأْسِي فَأَقُولُ: يَا رَبِّ أُمَّتِي أُمَّتِي فَيُقَالُ: يَا مُحَمَّدُ! أَدْخِلْ الْجَنَّةَ مِنْ أُمَّتِکَ مَنْ لا حِسَابَ عَلَيْهِ مِنْ الْبَابِ الأَيْمَنِ مِنْ أَبْوَابِ الْجَنَّةِ، وَهُمْ شُرَکَاءُ النَّاسِ فِيمَا سِوَی ذَلِکَ مِنْ الأَبْوَابِ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ إِنَّ مَا بَيْنَ الْمِصْرَاعَيْنِ مِنْ مَصَارِيعِ الْجَنَّةِ لَکَمَا بَيْنَ مَکَّةَ وَهَجَرٍ أَوْ کَمَا بَيْنَ مَکَّةَ وَبُصْرَی». (صحیح البخاری: ۴۴ وصحیح مسلم: ۳۲۷/۱۹۴)۔\nاس لمبی حدیث کاخلاصہ یہ ہے:\nجب سورج زمین سے قریب تر ہوجائے گا اور لوگ گھبراہٹ میں ادھر ادھر بھاگ رہے ہوں گے اور ان کی خواہش ہوگی کہ کوئی سفارش کر دے تاکہ اس دشوار گزار مراحل سے نجات مل سکے۔ وہ ہر ایک نبی کے پاس جائیں گے جیسے آدم، نوح،ابراہیم، موسیٰ، عیسیٰ علیہم السلام تاہم وہ سب یہ کہہ کر کنارہ کشی اختیار کر لیں گے کہ آج ہمارا رب غصہ میں ہے۔ ہم میں اتنی ہمت نہیں کہ اس کے پاس جائیں، کیوں کہ ہم سے دنیا میں فلاں فلاں غلطی ہوگئی تھی۔ پھر لوگ نبی اکرم صلی اللہ علیہ وسلم کےپاس جائیں گے، تو آپ صلی اللہ علیہ وسلم سجدہ میں گر جائیں گے۔ آپ سے کہا جائے گا:اے محمد! سر اٹھایے، مانگیئے کیا مانگتے ہیں؟ آپ صلی اللہ علیہ وسلم کہیں گے: میری امت، میری امت، حکم ہوگا:اپنی امت میں سے ان کو جنت میں داخل کر دیجیے۔جن کا کوئی حساب نہیں،جنت کے داہنے دروازے سے داخل کیجیے، باقی دروازوں سے داخلے میں بھی وہ دیگر امتوں کے ساتھ شریک ہوں گے، اس ذات کی قسم جس کے ہاتھ میں محمد کی جان ہے جنت کےدو پٹوں کے درمیاں اتنا فاصلہ ہوگا جتنا مکہ اور مقام ہجر کے درمیان ہے، یا جتنا مکہ اور مقام بُصری کے درمیان ہے۔\nابوسعیدخدری رضی اللہ عنہ سے مروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «... فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ: شَفَعَتْ الْمَلائِکَةُ وَشَفَعَ النَّبِيُّونَ وَشَفَعَ الْمُؤْمِنُونَ وَلَمْ يَبْقَ إِلا أَرْحَمُ الرَّاحِمِينَ». (صحیح مسلم: ۳۰۲/۱۸۳)\n\"اللہ تعالی فرمائے گا:سفارش کرنے والوں میں سےفرشتے اور دوسرے رسول سب ہو چکے، اب ارحم الراحمین (اللہ) باقی ہے (پھر اللہ ہر اس شخص کو جہنم سے نکال لائے گا جس کے دل میں رائی کے دانہ کے برابر بھی ایمان ہوگا)\"۔\nابوالددراء رضی اللہ عنہ سےمروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «يُشَفَّعُ الشَّهِيدُ فِی سَبْعِينَ مِنْ أَهْلِ بَيْتِهِ». (سنن ابی داود: ۲۵۲۴) \"سفارش کرنے والوں میں شہید بھی ہوں گے جو اپنے خاندان کے ستر آدمیوں کی سفارش کریں گے\"۔\nکیوں کہ یہ وہ لوگ ہیں جن سے االلہتعالیٰ خوش ہے اور یہ لوگ صرف ان کی سفارش کریں گے جنھوں نے کسی طرح کا شرک نہیں کیا ہوگا، کیوں کہ مشرکوں کے متعلق اللہ تعالیٰ نے اپنا اٹل فیصلہ سنا دیا ہے: ﴿إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدِ ٱفۡتَرَىٰٓ إِثۡمًا عَظِيمًا﴾ [النساء: ۴۸] \"االلہ اس کو کبھی معاف نہیں کرے گا جس نے اس کا شریک ٹھہرایا اور اس کے علاوہ جس کو چاہے معاف کردے گا اور جس کسی نے اس کا شریک ٹھہرایا تو اس نے ایک بہت بڑا جھوٹ گھڑ لیا\"۔\nدوسری جگہ ارشاد ہے: ﴿إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا﴾ [النساء: ۱۱۶] \"بلاشبہ اللہ کبھی معاف نہیں کرے گا کہ اس کے ساتھ اس کا شریک ٹھہرایا جائے۔ ہاں اس کے سوا جس کو چاہے معاف کر دے گا، جس کسی نے اللہ کے ساتھ شریک ٹھہرایا تو وہ بھٹک کر بہت دور جاگرا\"۔\nاس لیے مشرکوں کے لیے سفارش کرنا اور نہ کرنا دونوں برابر ہے۔","",{}],[358,"§شکور\nدیکھیے: اسماےحسنی","",{}],[359,"§شکور(اسم باری تعالیٰ)\nدیکھیے: اسماے حسنی","",{}],[360,"§شمس\nشمس کو اردو میں سورج کہتے ہیں۔پرانے زمانے کے معبودوں میں سے یہ بھی ایک معبود تھا، آسمان کے بے شمار تاروں میں سے یہ بھی ایک تارا ہے۔ چونکہ لوگوں کی نگاہوں میں یہ سب سے بڑا اور سب سے زیادہ سودمند ہے، اس لیےاس کی عبادت کرنے والوں نے الگ الگ ناموں اور کاموں سے اس کو یادکیا۔ کبھی اس کو اگنی دیوتا (آگ کا اللہ) اور اوتار (اللہ کا انسانی جسم لے کر اترنا) کہا، تو کہیں ساری کائنات کا مالک بتایا۔ ان ساری بدعقیدگی کو منسوخ کرتے ہوے قرآن کریم نے ابراہیم علیہ السلام کے اس قول کا ذکر کیا، جس میں وہ سورج اورچاندکےڈوب جانےکودلیل بناکراس کی پوجاکرنے والوں پر نکیرکرتے ہیں۔قرآن مجیدمیں اس کی تفصیل اس طرح آئی ہے: ﴿فَلَمَّا جَنَّ عَلَيۡهِ ٱلَّيۡلُ رَءَا كَوۡكَبࣰ اۖ قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلۡأٓفِلِينَ فَلَمَّا رَءَا ٱلۡقَمَرَ بَازِغࣰ ا قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمۡ يَهۡدِنِي رَبِّي لَأَكُونَنَّ مِنَ ٱلۡقَوۡمِ ٱلضَّآلِّينَ فَلَمَّا رَءَا ٱلشَّمۡسَ بَازِغَةࣰ قَالَ هَٰذَا رَبِّي هَٰذَآ أَكۡبَرُۖ فَلَمَّآ أَفَلَتۡ قَالَ يَٰقَوۡمِ إِنِّي بَرِيٓءࣱ مِّمَّا تُشۡرِكُونَ إِنِّي وَجَّهۡتُ وَجۡهِيَ لِلَّذِي فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ حَنِيفࣰ اۖ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ﴾ [الأنعام: ۷۶-۷۹] \"جب رات اس پر چھاگئی تو اس (ابراہیم)نے ایک تارا دیکھا۔ اس نے کہا: یہ میرا رب (حقیقی معبود)ہے، جب وہ ڈوب گیا، تو بولا: ڈوب جانے والوں سے مجھے محبت نہیں۔پھر جب اس نے چاند چمکتا دیکھا تو کہا: یہ میرا رب(حقیقی معبود) ہے۔ جب وہ بھی ڈوب گیا تو کہا: اگر میرا رب مجھے راہ نہ دکھائے، تو میں بھٹکے ہوے لوگوں میں سے ہوجاؤں گا۔ پھر جب سورج کو چمکتے ہوے دیکھا، تو کہنے لگا: یہ میرا رب (حقیقی معبود)ہے! یہ سب سے بڑا ہے۔ پھر جب وہ ڈوب گیا تو کہا: اے میری قوم! میں ان سے بری ہوں جنھیں تم (اللہ کا) ہمسرٹھہراتے ہو۔ میں نے تو ہر طرف سے کٹ کر اپنا رخ اس کی طرف کر لیا ہے جس نے آسمانوں اور زمین کو پیدا کیا اور میں شرک کرنے والوں میں سے نہیں ہوں\"۔\nاللہ تعالیٰ نے درحقیقت سورج اور چاند کو اپنے وجود کی نشانیاں بنایا ہے، نہ کہ اپنا ہمسرومعبود، اس لیے ان کو سجدہ کرنے سے روکا ہے اور خود کو سجدہ کرنے کا حکم دیا ہے جس نے ان کو بنایا ہے۔ (سورہ حٰم السجدة: ۳۷)","",{}],[361,"§شوریٰ\nشوریٰ کو صلاح و مشورہ بھی کہا جاتا ہے۔ اسلام پہلا دین ہے جو دُنیوی امور کے لیے شوریٰ کا حکم دیتا ہے۔قرآن مجیدمیں ہے:﴿وَٱلَّذِينَ ٱسۡتَجَابُواْ لِرَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَمۡرُهُمۡ شُورَىٰ بَيۡنَهُمۡ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ﴾ [الشوری: ۳۸] \"جنھوں نے اپنے رب کے فرمان کو قبول کیا اور نمازقائم کی، ان کے کام صلاح ومشورے سے ہوتے ہیں اور جو کچھ ہم نے انھیں دیا ہے، اس میں سے خرچ کرتے ہیں\"۔\nخودنبی اکرم صلی اللہ علیہ وسلم کواللہ کاحکم تھا:﴿فَبِمَا رَحۡمَةࣲ مِّنَ ٱللَّهِ لِنتَ لَهُمۡۖ وَلَوۡ كُنتَ فَظًّا غَلِيظَ ٱلۡقَلۡبِ لَٱنفَضُّواْ مِنۡ حَوۡلِكَۖ فَٱعۡفُ عَنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمۡ وَشَاوِرۡهُمۡ فِي ٱلۡأَمۡرِۖ فَإِذَا عَزَمۡتَ فَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَوَكِّلِينَ﴾ [آل عمران: ۱۵۹] \"معاملات میں ان سے صلاح و مشورہ کر لیا کرو\"۔\nلیکن یہ حکم صرف دُنیوی امور و معاملات میں تھا۔ مگر جہاں اللہ اورنبی اکرم صلی اللہ علیہ وسلم کاحکم آجائے وہاں کسی طرح کے صلاح یا مشورے کی ضرورت نہیں ہوتی۔ بلکہ اللہ اور اس کے رسول کے حکم کےمطابق عمل کرنا لازم ہوجاتا ہے۔یہ جو دُنیوی امور میں صلاح اور مشورے کا حکم ہے، اس کے لیے کوئی مخصوص ضابطہ متعین نہیں کیا گیا۔ بلکہ مسلمانوں کو یہ آزادی دی گئی ہےکہ وہ جس طرح چاہیں صلاح و مشورہ کریں۔ اس میں سے ایک طریقہ تو یہ ہے کہ حکمراں ایک ایسی مجلس شوریٰ بنا لے جس میں مختلف النوع علما اور مختلف النوع میدانوں کے ماہرین شامل ہوں اور حکمراں کی جانب سے اگر کسی مسئلے (معاملے) پر مشورہ طلب کیا جائے تو (بطورِ احسن) دیں۔ اس جماعت (مجلس شوریٰ) کے فرائض کو بادشاہ یا حکمراں اپنے فرمان کے ذریعے سےمتعین کر سکتا ہے۔ لیکن اس کے لیے ضروری نہیں ہوگاکہ وہ مجلس شوریٰ کے مشورے پر عمل کرے۔ کیوں کہ اسے مملکت کے بارے میں جتنی تفصیلی اور گہری معلومات ہوتی ہیں اتنی کسی اور کو قطعی نہیں ہوتی۔ معاملات کی سنجیدگی اور اسرار و رموز کو وہ سمجھتا ہے۔اسے اس بات کا بھی علم ہوتا ہے کہ ملک اور مملکت کے عوام پر کس کام کے کیا اثرات مرتب ہوسکتے ہیں۔ وہ تو مجلس شوریٰ کے مشورے کی بنیاد پرکوئی مناسب اور حالات کے مطابق فیصلہ لے سکتا ہے۔ نبی اکرم صلی اللہ علیہ وسلم کو صلاح و مشورےکا تو حکم دیا گیا تھا لیکن اس پر عمل کرنا آپ پر ضروری نہ تھا۔ آپ لوگوں سے صلاح ومشورے کے بعد جو مناسب ہوتا، اس کو اپناتے، کیوں کہ کسی مسئلہ (معاملہ) کو حل کرنے کے لیے جیسا عقل و شعور اور سوجھ بوجھ اللہ تعالیٰ نے آپ کو عطا کیا تھا اس طرح کسی اور کو حاصل نہیں تھی۔","",{}],[362,"§شوہر\nدیکھیے: بعل","",{}],[363,"§شہر\nقرآن میں شہراورشہوردونوں لفظ استعمال ہوا ہے۔شہرواحد ہےاورشہور اس کی جمع اوراس کے معنی مہینےکے ہیں۔ایک سال میں بارہ مہینے ہوتے ہیں۔ارشادباری تعالیٰ ہے: ﴿إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثۡنَا عَشَرَ شَهۡرࣰ ا فِي كِتَٰبِ ٱللَّهِ يَوۡمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ مِنۡهَآ أَرۡبَعَةٌ حُرُمࣱۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُۚ فَلَا تَظۡلِمُواْ فِيهِنَّ أَنفُسَكُمۡۚ وَقَٰتِلُواْ ٱلۡمُشۡرِكِينَ كَآفَّةࣰ كَمَا يُقَٰتِلُونَكُمۡ كَآفَّةࣰۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ﴾ [التوبة: ۳۶] بلاشبہ مہینوں کی تعداد اللہ کے نزدیک اس کی کتاب میں بارہ مہینے ہے۔اس دن سے،جس دن آسمانوں اور زمینوں کو پیدا کیا، ان میں سے چارحرام کے مہینے ہیں۔\nیہاں کتاب سے مرادلوح محفوظ ہے،جہاں ساری کائنات کےبارے میں سب کچھ لکھ کر رکھا ہوا ہے۔ عربوں میں اور اسی طرح یہودی اور ہندستانی کلچر میں بھی چاند کی گردش کی بنیاد پر بارہ مہینوں کے نام مقرر کیے گئے ہیں۔عربی مہینوں کے نام اس طرح ہیں :\n۱ـمحرم،۲ـصفر۳ـربيع الاول۴ـربيع الآخر،۵ـجمادی الاولی،۶ـجمادی الآخرة،۷ـرجب،۸ـشعبان، ۹ـرمضان، ۰اـشوال،ااـذوالقعدہ، ۲اـذوالحجہ۔\nان میں چار مہینے حرام کہے جاتے ہیں۔ وہ یہ ہیں: ذوالقعدہ، ذوالحجہ، محرم اور رجب۔ان مہینوں میں جنگ کرنا حرام تھا۔لیکن اسلام سے پہلے زمانۂ جاہلیت میں لوگ اپنی خواہش کے مطابق ان مہینوں کو آگے پیچھے کرلیا کرتے تھے۔تاکہ جنگ کرنے میں حرام مہینے کا مسئلہ نہ رہے۔اسی کو قرآن میں نسی کہا گیا ہے۔نسی کا معنی ہے مہینوں کو آگے پیچھے کردینا۔ (التوبہ: ۳۷)\nان کے اس ردو بدل کی وجہ سے اللہ کے مقررکردہ مہینوں میں تبدیلی ہوگئی۔نبی اکرم صلی اللہ علیہ وسلم کے معجزات میں سے ایک یہ بھی ہے کہ آپ کے نبی ہونے کے کچھ سال بعد یہ مہینے پہلی حالت میں آگئے۔ وہ چار مہینے اسی طرح حرام ہوگئے جس طرح پہلے تھےاور اب یہ حالت اسی طرح قیامت تک برقراررہے گی۔\nکچھ لوگوں نے زمانہ قدیم سے ہی سال کے بارہ مہینے مقررکرنے کےلیے سورج کو بنیاد بنایا۔جو مشہور ہے کہ بارہ منازل میں دورہ کرتاہے اوریہ بارہ مہینے سریانی اور لاطینی میں اس طرح ہیں۔\nدیکھیے بائبل:نیسان (نحمياہ۲:ا)،ايلول (نحمياہ ۶:۵ا)،آذار(استر ۳:۷)، شباط (زکریاہ ا:۷)\nکچھ عرب ممالک جیسےشام(سوریا)، لبنان، عراق، یمن وغیرہ میں آج بھی سریانی ناموں کا استعمال ہوتاہے۔وہ لاطینی ناموں کو نہیں جانتے۔\nچونکہ چاند کے بارہ مہینے کل ۳۵۴ د ن کے ہوتے تھےاور سورج کے بارہ مہینے ۳۶۵دن کے ہوتے تھے۔اس لیے یہودی بھی ہر تین سال کے بعد ایک مہینا بڑھا لیا کرتے تھے۔تاکہ سورج کے مہینے کے مطابق ہوجائے۔کچھ علماءنے اس کو بھی\"نسی\"کہا ہے۔ کیونکہ اس سے اللہ کے مقرر کیے ہوے بارہ مہینوں میں تبدیلی ہوجاتی ہے جس کی وجہ سے عیدوں کا ٹھیک ٹھیک دن مقرر کرنا ناممکن ہے۔\nاس طرح اسلام کی ساری عبادتوں جیسے رمضان کے روزے،حج،عید وغیرہ کو چاند کی گردش پر ہی رکھا گیا ہے۔ سورج کے ذریعے سے صرف پانچ وقت کی نمازوں کو مقرر کیا جاتاہے۔","",{}],[364,"§شہید\nدیکھیے: اسماےحسنی","",{}],[365,"§شہید\nاللہ تعالیٰ کی صفات میں سے ایک صفت شہید ہے،جس کا مطلب ہے: گواہ (شاہد) قرآن میں ہے: ﴿قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعۡمَلُونَ﴾ [آل عمران: ۹۸] \"اے اہل کتاب! تم اللہ کی آیتوں کا کیوں انکار کرتے ہو، جب کہ جو کچھ تم کرتے ہو اللہ اس کا گواہ ہے\"۔\nاوراسی معنی میں یہ لفظ اللہ کے علاوہ، لوگوں کے لیے بھی استعمال ہوا ہے۔ جیسےنبی اکرم صلی اللہ علیہ وسلم کےمتعلق ارشادباری تعالی ہے: ﴿فَكَيۡفَ إِذَا جِئۡنَا مِن كُلِّ أُمَّةِۭ بِشَهِيدࣲ وَجِئۡنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيدࣰ ا﴾ [النساء: ۴۱] \"پھر کیا حال ہوگا جب ہم ہر ایک قوم میں سے ایک گواہ لائیں گے اور خودآپ کو ان لوگوں کے مقابلے میں گواہ بناکر پیش کریں گے\"۔\nہر نبی اپنی قوم پر گواہی دے گا کہ اے اللہ! ہم نے تیرا پیغام ان کو پہنچادیا، اب اگر انھوں نے نہیں ماناتو اس میں ہماری کیا غلطی ہے۔ اسی طرح نبی اکرم صلی اللہ علیہ وسلم مکہ کے ملحدین پر گواہ بناکر لائے جائیں گے۔آپ ان کے خلاف گواہی دیں گے کہ اے اللہ! انھوں نے تیرے پیغام کو ٹھکرا دیا تھا۔\nبعض مفسرین نے لکھا ہےکہ نبی اکرم صلی اللہ علیہ وسلم دوسرے انبیا کےبارے میں گواہی دیں گے کہ یہ جو کچھ کہہ رہے ہیں سچ ہے، انھوں نے اپنی اپنی امتوں کو اللہ کا پیغام پہنچایا۔لیکن کچھ لوگ ہی ایمان لائے۔\nنبی اکرم صلی اللہ علیہ وسلم کو اس کا علم قرآن سے ہوا جس میں انبیااور ان کی امت کے درمیان جو کچھ واقعہ پیش آیا،اس کا ذکر موجود ہے۔ وہ بڑا دشوار مرحلہ ہوگا جب نبی اکرم صلی اللہ علیہ وسلم کو گواہ بناکر لایا جائے گا۔\nاسی لیے آپ کی خواہش پر جب عبداللہ بن مسعود نے قرآن پڑھ کر سنایا اور اس آیت پر پہنچے تو آپ نے کہا: بس کرو۔\nعبد اللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے حکم دیا کہ میں ان پر قرآن پڑھوں، میں نے عرض کیا: «آقْرَأُ عَلَيْکَ وَعَلَيْکَ أُنْزِلَ؟ قَالَ: فَإِنِّي أُحِبُّ أَنْ أَسْمَعَهُ مِنْ غَيْرِي، فَقَرَأْتُ عَلَيْهِ سُورَةَ النِّسَاءِ حَتَّی بَلَغْتُ:﴿فَكَيۡفَ إِذَا جِئۡنَا مِن كُلِّ أُمَّةِۭ بِشَهِيدࣲ وَجِئۡنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيدࣰ ا﴾ [النساء: ۴۱] قَالَ: أَمْسِکْ فَإِذَا عَيْنَاهُ تَذْرِفَانِ». (صحیح البخاری: ۴۵۸۲، وصحیح مسلم: ۸۰۰/۲۴۷)۔\n\" میں آپ پر پڑھوں جب کہ قرآن خود آپ پر نازل ہوا ہے؟ آپ نے فرمایا: میں دوسروں سے بھی قرآن سننا پسند کرتا ہوں، (اس پر) میں نے سورة النساء پڑھنی شروع کی، جب آیت پر \"پھر کیا حال ہوگا جب ہم ہر ایک قوم میں سے ایک گواہ لائیں گے اور خود آپ کو ان لوگوں کے مقابلے میں گواہ بناکر پیش کریں گے\"۔پہنچا تو آپ نے فرمایا: بس رک جاؤ اور میں نے (نظر اٹھایا تو) دیکھا کہ آپ کی آنکھیں بہہ رہی ہیں\"۔\nشہیدکا ایک دوسرا مطلب ہے: اللہ کی راہ میں جان دینے والا۔ جس کی جمع شہداء ہے، جیسا کہ قرآن میں آیا ہے: ﴿وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُوْلَٰٓئِكَ مَعَ ٱلَّذِينَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِم مِّنَ ٱلنَّبِيِّـۧنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّٰلِحِينَۚ وَحَسُنَ أُوْلَٰٓئِكَ رَفِيقࣰ ا﴾ [النساء: ۶۹] \"جو لوگ اللہ اور رسول کی اطاعت کرتے ہیں، تو ایسے لوگ ان لوگوں کے ساتھ ہوں گے جن پر اللہ نے انعام کیا ہے جیسے نبی، صدیق شہید اور نیک لوگ اور یہ کیسے اچھے ساتھی ہیں \"۔\nقرآن کریم میں ایک دوسری جگہ پر آیا ہے: ﴿وَٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦٓ أُوْلَٰٓئِكَ هُمُ ٱلصِّدِّيقُونَۖ وَٱلشُّهَدَآءُ عِندَ رَبِّهِمۡ لَهُمۡ أَجۡرُهُمۡ وَنُورُهُمۡۖ وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ﴾ [الحدید: ۱۹] \"جو لوگ اللہ اور اس کے رسولوں پر ایمان لائے، وہی لوگ اپنے رب کے پاس صدیق اور شہداء (کے درجہ میں) ہوں گے۔ ان کے لیے بدلہ (خود ان کے اعمال کا) اور روشنی ہے۔ اور جن لوگوں نے انکار کیا اور ہماری آیتوں کو جھٹلایا وہی جہنم کے رہائشی ہیں\"۔\nیعنی صدیق اور شہید اپنے اعمال کی روشنی میں چلتے ہوے جنت میں داخل ہوجائیں گے۔ ان شہیدوں کی سب سے بڑی خصوصیت یہ ہے کہ یہ اپنے رب کے پاس زندہ ہیں۔\nاورفرمایا: ﴿وَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتَۢاۚ بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ﴾ [آل عمران: ۱۶۹] \"جو اللہ کی راہ میں مارے گئے ہیں تم ان لوگوں کو مردہ نہ سمجھو، بلکہ وہ تو اپنے رب کے پاس زندہ ہیں رزق پا رہے ہیں\"۔\nمزیدارشادہے: ﴿وَلَا تَقُولُواْ لِمَن يُقۡتَلُ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتُۢۚ بَلۡ أَحۡيَآءࣱ وَلَٰكِن لَّا تَشۡعُرُونَ﴾ [البقرة: ۱۵۴] \"جو لوگ اللہ کی راہ میں مارے جائیں انھیں مردہ نہ کہو۔ بلکہ وہ زندہ ہیں۔ مگر تمھیں اس کا اندازہ نہیں ہے\"۔\nنیز فرمایا: ﴿لَيُدۡخِلَنَّهُم مُّدۡخَلࣰ ا يَرۡضَوۡنَهُۥۚ وَإِنَّ ٱللَّهَ لَعَلِيمٌ حَلِيمࣱ‏﴾ [الحج: ۵۹] \"جن لوگوں نے اللہ کی راہ میں گھر بار چھوڑا پھر مارے گئے یا مرگئے۔ یقیناًااللہ انھیں اچھا رزق عطا کرے گا۔ اور بلاشبہ اللہ ہی ہے اچھا رزق عطا کرنے والا۔ وہ انھیں ایسا مقام (جگہ) عطا کرے گا جس سے وہ خوش ہو اٹھیں گے۔ اور یقیناً ہی اللہ علیم وحلیم (لامحدود علم والا اور انتہائی بردبار) ہے\"۔\nیہی وجہ ہے کہ شہیدکو نہ غسل دیا جاتا ہے، نہ کفن پہنایا جاتا ہے، نہ ان پرنماز جنازہ پڑھائی جاتی ہے۔ کیوں کہ نما زجنازہ مردے کی پڑھی جاتی ہے، زندہ کی نہیں۔\n§شہید کی عظمت:\nانس بن مالک رضی اللہ عنہ سے مروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «مَا أَحَدٌ يَدْخُلُ الْجَنَّةَ يُحِبُّ أَنْ يَرْجِعَ إِلَی الدُّنْيَا وَلَهُ مَا عَلَی الأَرْضِ مِنْ شَيْءٍ إِلا الشَّهِيدُ، يَتَمَنَّی أَنْ يَرْجِعَ إِلَی الدُّنْيَا فَيُقْتَلَ عَشْرَ مَرَّاتٍ لِمَا يَرَی مِنْ الْکَرَامَةِ». (صحیح البخاری: ۲۸۱۷، وصحیح مسلم: ۱۸۷۷/۱۰۹) \"جوشخص جنت میں داخل ہوجائے گا وہ دوبارہ دنیامیں آنے کی خواہش نہیں کرے گا۔ خواہ ساری دنیا اس کے قدموں میں ڈال دی جائے، سوائے شہید کے جو شہادت کی عظمت کو دیکھتے ہوے یہ خواہش کرے گا کہ دنیا میں واپس جائے اور دس بار اللہ کی راہ میں مارا جائے\"۔\nایک دوسری روایت میں آیا ہے: شہید کو جو وہاں اعلیٰ مقام حاصل ہوگا اس کی وجہ سے وہ ایسی خواہش کا اظہار کرے گا۔(صحیح البخاری: ۲۸۱۷، صحیح مسلم: ۱۸۷۷)\nابوہریرہ رضی اللہ عنہ سےروایت ہے نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «لَوْلا أَنْ أَشُقَّ عَلَی أُمَّتِي مَا قَعَدْتُ خَلْفَ سَرِيَّةٍ، وَلَوَدِدْتُ أَنِّي أُقْتَلُ فِي سَبِيلِ اللَّهِ ثُمَّ أُحْيَا، ثُمَّ أُقْتَلُ ثُمَّ أُحْيَا ثُمَّ أُقْتَلُ». (صحیح البخاری: ۳۶، وصحیح مسلم: ۱۸۷۶) \"اگر میری امت پر دشوار نہ ہوتا تو میں ہر اس گروہ (فوج) کے ساتھ جاتا جو جہاد کرنے جاتا ہے اور پھر میری خواہش ہوتی کہ میں اللہ کی راہ میں قتل کیا جاؤں،پھر زندہ کیا جاؤں، پھر قتل کیا جاؤں،پھر زندہ کیا جاؤں، پھر قتل کیا جاؤں\"۔\n§شہداءکے اقسام:\nشہادت کا درجہ کچھ اور وجوہ کے سبب مرنے والوں کو بھیدیا گیا ہے۔ جیسے:\n۱- طاعون (وبائی امراض) سے مرنے والے۔\n۲- پیٹ کے مرض سے مرنے والے۔\n۳- پانی میں ڈوب کر مرنے والے۔\n۴- کسی چیز کے گر جانے سے مرنے والے۔\n۵- اللہ کی راہ میں مرنے والے۔ (دیکھیے: صحیح البخاری: ۶۵۲ اور صحیح مسلم: ۹۱۴)\n۶- اپنے مال و دولت کی حفاظت کرتے ہوے مرنے والے۔ (دیکھیے : صحیح البخاری : ۲۴۸۰ اورصحیح مسلم: ۲۲۶)\n۷-اپنی اور اپنے اہل وعیال کی عزت وآبرو کی حفاظت کرتے ہوے مرنے والے۔\n۸- اپنے دین کی حفاظت کرتے ہوے مرنے والے۔ (دیکھیے : ابوداو د: ۴۷۷۲ اورسنن الترمذی: ۱۴۵۵)\n۹- آگ کی لپیٹ میں آکر مرنے والے۔\n۱۰- حمل کی حالت میں مرنے والی عورت۔\n۱۱- اندرونی پھوڑے پھنسی کے پھوٹنے اور کینسر سے مرنے والے۔ (جس کو عربی زبان میں ذات الجنب کہتے ہیں)\n۱۲- حادثےمیں مرنے والے۔\n۱۳- فرقہ وارانہ فسادات میں مرنے والے۔ (دیکھے:ابوداو د: ۳۱۱۱ اور نسائی: ۳۱۹۴ اور ابن ماجہ : ۲۸۰۳)\nان سب کو شہید کہا گیا ہے۔ تاہم سب سے اونچا درجہ ان کا ہے جو اللہ کی راہ میں اپنی جان قربان کر دیتےہیں۔اس لیےشہادت سے متعلق احکام اور قانون صرف انھی پر نافذ ہوں گے جو اللہ کی راہ میں شہید ہوں گے۔ باقی شہداء کے لیے بھی اللہ تعالیٰ کےیہاں مختلف قسم کے درجات ہیں۔","",{}],[366,"§شیر\nدیکھیے: قسورہ","",{}],[367,"§شیطان\nشیطان کا مطلب ہے بدروح، جو لوگوں کو بہکا کر غلط راہ پر چلاتا ہے۔ یہ کوئی مستقل مخلوق نہیں ہے۔ بلکہ انسانوں اورجناتوں میں جو بدروح ہیں،انھی کو شیطان کہا گیا ہے۔قرآن میں آیا ہے: ﴿وَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوࣰّ ا شَيَٰطِينَ ٱلۡإِنسِ وَٱلۡجِنِّ يُوحِي بَعۡضُهُمۡ إِلَىٰ بَعۡضࣲ زُخۡرُفَ ٱلۡقَوۡلِ غُرُورࣰ اۚ وَلَوۡ شَآءَ رَبُّكَ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ﴾ [الأنعام: ۱۱۲] \"اسی طرح ہم نےانسانوں اور جنوں میں سے شیاطین کو ہر ایک نبی کا دشمن بنایا، جو چکنی چپڑی بات ایک دوسرے کے من میں ڈال کر دھوکادیتے تھے\"۔\nشیطان اور انسان میں کیاتعلق ہے؟ اس عنوان پر قرآن اور صحیح حدیثوں میں تفصیلی ذکر آیاہے۔\n۱- شیطان انسان کا کھلا دشمن ہے، اس لیے قرآن نے ہوشیارکر دیا ہے کہ اس کے راستوں کی پیروی نہ کی جائے۔ (البقرہ: ۱۶۸ـ۲۰۸)\nاورفرمایا: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ وَمَن يَتَّبِعۡ خُطُوَٰتِ ٱلشَّيۡطَٰنِ فَإِنَّهُۥ يَأۡمُرُ بِٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۚ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدࣰ ا وَلَٰكِنَّ ٱللَّهَ يُزَكِّي مَن يَشَآءُۗ وَٱللَّهُ سَمِيعٌ عَلِيمࣱ‏﴾ [النور: ۲۱] \"تو وہ (شیطان) تو اسے بےحیائی اوربرے کاموں کا ہی حکم دے گا\"۔\n۲- شیطان جہنم کی آگ کی طرف بلاتا ہے: ﴿إِنَّ ٱلشَّيۡطَٰنَ لَكُمۡ عَدُوࣱّ فَٱتَّخِذُوهُ عَدُوًّاۚ إِنَّمَا يَدۡعُواْ حِزۡبَهُۥ لِيَكُونُواْ مِنۡ أَصۡحَٰبِ ٱلسَّعِيرِ﴾ [الفاطر: ۶] \"یقیناً شیطان تمھارا دشمن ہے۔ چنانچہ تم بھی اسے دشمن ہی سمجھو۔ وہ تواپنے گروہ (پیروکاروں) کو تو صرف اس لیے بلاتا ہےتاکہ وہ دہکتی آگ والوں (جہنمی) میں سے ہوجائیں\"۔\n۳- شیطان کے کچھ کام: ہر برے کام کو شیطانی کام کہا جاسکتا ہے۔ جیسے: شراب نوشی، جوا اورسودخوری وغیرہ۔ قرآن میں ہے: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسࣱ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ فَٱجۡتَنِبُوهُ لَعَلَّكُمۡ تُفۡلِحُونَ﴾ [المائدة: ۹۰] \"اے ایمان والو! یہ شراب، جوا، تھان اور فال نکالنے کے پانسے کے تیر، یہ سب گندی باتیں شیطانی کام ہیں تو ان سے بچو تاکہ تم فلاح یاب ہوسکو\"۔\nشیطان فقروفاقہ سے ڈراتا ہے تاکہ تم اللہ کی راہ میں صدقہ نہ کرو اور گندے کاموں کا حکم دیتا ہے۔\nاورفرمایا: ﴿ٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ وَٱللَّهُ يَعِدُكُم مَّغۡفِرَةࣰ مِّنۡهُ وَفَضۡلࣰ اۗ وَٱللَّهُ وَٰسِعٌ عَلِيمࣱ‏﴾ [البقرة: ۲۶۸] \"شیطان تمھیں غربت سے ڈراتا ہے اور بے حیائی کے کاموں پر اکساتا ہے\"۔\nشیطان کفر کرنےپرابهارتا ہے،پھراپنےاتباع سےاعلان براءت کرتا ہے۔ ارشادباری تعالیٰ ہے: ﴿كَمَثَلِ ٱلشَّيۡطَٰنِ إِذۡ قَالَ لِلۡإِنسَٰنِ ٱكۡفُرۡ فَلَمَّا كَفَرَ قَالَ إِنِّي بَرِيٓءࣱ مِّنكَ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ﴾ [الحشر: ۱۶] \"(منافقوں کی مثال) شیطان جیسی ہے، جو انسان کو کہتا ہے کہ کفر کر، جب وہ کفر کر بیٹھتا ہے تو کہتا ہے میں تجھ سے الگ ہوں۔ میں اللہ سے ڈرتا ہوں جو ساری کائنات کا رب ہے\"۔\nشیطان جس طرح مسلمانوں کو بہکاتا ہے، اسی طرح کفار کو بھی بہکاتا اوردھوکا دیتا ہے۔ غزوۂ بدر کےموقع پر ایسا ہی ہوا۔جس کا نقشہ قرآن نےان الفاظ میں کھینچاہے: ﴿وَإِذۡ زَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ وَقَالَ لَا غَالِبَ لَكُمُ ٱلۡيَوۡمَ مِنَ ٱلنَّاسِ وَإِنِّي جَارࣱ لَّكُمۡۖ فَلَمَّا تَرَآءَتِ ٱلۡفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيۡهِ وَقَالَ إِنِّي بَرِيٓءࣱ مِّنكُمۡ إِنِّيٓ أَرَىٰ مَا لَا تَرَوۡنَ إِنِّيٓ أَخَافُ ٱللَّهَۚ وَٱللَّهُ شَدِيدُ ٱلۡعِقَابِ﴾ [الأنفال: ۴۸] \"جب شیطان نے ان کے کرتوتوں (اعمال) کو ان کے لیے مزین بنادیا تھا اور کہا تھا: لوگوں میں سے کوئی بھی آج تم پر غالب نہیں آسکتا،میں خود بھی تمھارا حمایتی ہو۔ لیکن جب دونوں فوجیں آمنے سامنے ہوئیں تو وہ الٹے پاؤ ں بھاگ نکلا اور کہنے لگا:میرا تم سے کوئی (ناطہ) تعلق نہیں۔ میں جو کچھ دیکھ رہا ہوں تم نہیں دیکھ سکتے۔ میں اللہ سے ڈرتا ہوں۔ اللہ تعالیٰ سخت عذاب دینے والا ہے\"۔\nشیطان نے مکہ کے اسلام مخالفوں کو پہلے تو مسلمانوں کے خلاف لڑنے پر ابھارا لیکن جب اس نے دیکھا کہ آسمان سےفرشتے اتر رہے ہیں تاکہ مسلمانوں کی مدد کریں جس کا ذکر قرآن میں ہوا ہے تو وہ بھاگ کھڑا ہوا۔ کفارکو میدان جنگ میں تنہا چھوڑ دیا۔ ان کو یہ بھی نہیں بتایا کہ آسمان سے فرشتے اتر رہے ہیں تاکہ وہ میدان چھوڑکر چلے جائیں اور اپنی زندگیاں بچا لیں۔ بلکہ وہ تو ان کو میدان جنگ میں مرتے ہوے چھوڑ کر بھاگ نکلا۔\nعبداللہ بن عباس رضی اللہ عنہما کی ایک روایت میں آیا ہے کہ ایک مسلمان ایک کافرکا پیچھا کر رہا تھا کہ اس نے گھوڑے کی آواز سنی، پھرگھوڑے کی ٹاپ کی آواز سنی، پھر سنا کوئی حیزوم،حیزوم کہہ رہا ہے (ہوسکتا ہےیہ گھوڑے کا نام ہو) پھر مسلمان نے دیکھا کہ وہ کافر زمین پرگرا پڑا ہے۔ اس نے یہ قصہ نبی اکرم صلی اللہ علیہ وسلم کو سنایا تو آپ نےفرمایا: تم سچ کہتے ہو فرشتے تیسرے آسمان سے مدد کے لیے آئے تھے۔ (صحیح مسلم)\nشیطان کا ایک بڑا کام یہ بھی ہے کہ وہ انسان کو اللہ کےبارے میں تذبذب اورشک میں ڈال دیتا ہے۔جیسا کہ ابوہریرہ رضی اللہ عنہ کی ایک روایت میں ہے نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «يَأْتِي الشَّيْطَانُ أَحَدَکُمْ فَيَقُولُ: مَنْ خَلَقَ کَذَا مَنْ خَلَقَ کَذَا؟ حَتَّی يَقُولَ: مَنْ خَلَقَ رَبَّکَ؟ فَإِذَا بَلَغَهُ فَلْيَسْتَعِذْ بِاللَّهِ وَلْيَنْتَهِ». (صحیح البخاری: ۳۲۷۶، وصحیح مسلم: ۱۳۴/۲۱۳) \"تم میں سے کسی کے پاس شیطان آتا ہے اور کہتا ہے کہ اس کو کس نے پیدا کیا؟ اس کو کس نے پیدا کیا؟اس کو کس نے پیدا کیا؟ یہاں تک کہ یہ تک کہتا ہے کہ تمھارے رب کو کس نے پیدا کیا؟ تو جب اس طرح بہکانے لگے تو اس آدمی کو چاہیے کہ اللہ کی پناہ مانگے اور پھر بار بار پناہ مانگتارہے\"۔\nشیطان سے بچنے کےلیے ضروری ہے کہ مسلمان ہر وقت اس سے اللہ کی پناہ مانگے۔ قرآن کریم کی آخری سورہ میں اسی کی تعلیم دی گئی ہے: ﴿قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ مَلِكِ ٱلنَّاسِ إِلَٰهِ ٱلنَّاسِ مِن شَرِّ ٱلۡوَسۡوَاسِ ٱلۡخَنَّاسِ ٱلَّذِي يُوَسۡوِسُ فِي صُدُورِ ٱلنَّاسِ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ﴾ [الناس: ۱-۶] \"کہو!میں پناہ لیتا ہوں لوگوں کے رب کی، لوگوں کے بادشاہ کی، لوگوں کے معبودکی: اس کی برائی سے جو وسوسہ میں ڈالتا ہے، پیچھے ہٹ جاتا ہے، جو جنوں میں سے بھی ہوسکتا ہے اور انسانوں میں سے بھی\"۔\nاس کی تائید ایک صحیح حدیث سے بھی ہوتی ہے۔ابو امامہ رضی اللہ عنہ کہتےہیں: \"رسول اللہ صلی اللہ علیہ وسلم مسجد میں شریف فرما تھے، لوگ یہ گمان کر رہے تھے کہ آپ پر وحی نازل ہو رہی ہے، اس لیے وہ آپ سے الگ تھے، اتنے میں ابوذر رضی اللہ عنہ آئےاور گھس کر رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھ گئے، آپ ان کی طرف متوجہ ہوے، آپ صلی اللہ علیہ وسلم نےفرمایا: کیا تم نے نمازپڑھ لی؟ میں نے کہا: نہیں تو آپ نے فرمایا:جاؤ پہلے نماز پڑھو۔جب نماز پڑھ کر آیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: اے ابوذر!انسانوں اور جنوں میں جو شیطان ہیں ان سے اللہ کی پناہ مانگو۔ میں نے کہا: کیا انسانوں میں بھی شیطان ہوتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ہاں\" (مسند احمد: ۵/۲۵۸، ۲۲۳۴۲)","",{}],[368,"§قرآن انسائیکلوپیڈیا\n§جزء دوم","",{}],[369,"§ص\nدیکھیے: الف-لام-میم","",{}],[370,"§صابی، صابئين\nصابئین صابی کی جمع ہے۔یہ لفظ صبأسے بنا ہے جس کا معنیٰ ہوتا ہے: ایک طرف کا ہوجانا،اس طرح صابئین کا مطلب ہوا: ایک طرف کے ہوجانے والے لوگ۔ ایسا لگتا ہے کہ یہ لوگ کسی نبی کے ماننے والے تھے پھر دھیرےدھیرے اس نبی کا صحیح راستاچھوڑ کر الگ ہوگئے اورگمراہی کے راستے پر چل پڑے اور اسی پر ایک طرف ہو گئے۔\nبعض علماءنےانھیں نوح علیہ السلام کا پیروکار بتایا ہے۔ لیکن اس بات کی تصدیق مشکل ہے۔ اغلب یہ ہے کہ یہ موسی علیہ السلام اورعیسی علیہ السلام کے درمیان آنے والے کسی نبی کے پیروکارہیں۔ کیوں کہ قرآن میں دوجگہوں (مائدہ اور حج)پر ان کاتذکرہ یہود ونصاری کے درمیان آیاہے۔ صرف سورہ بقرہ میں ایک جگہ نصاری کے بعد ان کا تذکرہ آیا ہے۔ مگر چونکہ یہ قطعی طور سے ثابت ہے کہ عیسیٰ علیہ السلام اور محمد صلی اللہ علیہ وسلم کے درمیان کوئی نبی نہیں آیا ہے، اس لیے مذکوربالادو جگہوں پر یہود ونصاری کے درمیان تذکرہ کےحساب سے اغلب یہی ہے کہ ان کے نبی موسی وعیسیٰ علیہما السلام کے درمیان تھے۔ واللہ اعلم۔\nقرآن کریم میں صابیوں کا ذکر تین جگہ آیا ہے:\nسورہ بقرہ میں اللہ تعالیٰ فرماتا ہے: ﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلنَّصَٰرَىٰ وَٱلصَّٰبِـِٔينَ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحࣰ ا فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ﴾ [البقرة: ۶۲] \"مسلمانوں ہوں، یہودی ہوں، نصاری ہوں یا صابی ہوں، جو کوئی بھی اللہ اور قیامت کے دن پر ایمان لائے اورنیک عمل کرے ان کے اجر اُن کے رب کے پاس ہیں اور اُن پر نہ تو کوئی خوف ہے اور نہ اُداسی\"۔\nاورسورہ مائدہ میں ہے: ﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـُٔونَ وَٱلنَّصَٰرَىٰ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحࣰ ا فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ﴾ [المائدة: ۶۹] \"مسلمان، یہودی، صابی اورنصرانی، کوئی بھی ہو، جو بھی اللہ اور قیامت کے دن پر ایمان لائے اور نیک عمل کرے وہ بالکل بے خوف رہےگااور بالکل بے غم رہے گا\"۔\n§تنبیہ:\nان دونوں آیتوں کی تفسیر میں بعض سیکولر مفسرین بڑی غلط فہمی کاشکار ہوے ہیں۔ ان سے انھوں نے ’وحدت ادیان‘ کا فلسفہ کشید کرنے کی مذموم کوشش کی ہے۔ان کے نزدیک رسالت محمدیہ پر ایمان لانا ضروری نہیں ہے، بل کہ جو بھی جس دین کو مانتا اور اس کے مطابق ایمان رکھتا اور نیک عمل کرتا ہے اس کی نجات ہوجائے گی۔یہ ایک گمراہ کن فلسفہ ہے۔آیت کی صحیح تفسیر یہ ہے کہ جب اللہ تعالیٰ نے سابقہ آیات میں یہود کی بداعمالیوں اور سرکشیوں کی بنا پر ان کےمستحق عذاب ہونے کا تذکرہ کیا تواس سےذہن میں اشکال پیدا ہوسکتا تھا کہ ان یہود میں جو لوگ صحیح نبی کی ہدایات کے مطابق زندگی گزارنے والے تھے،ان کے ساتھ اللہ تعالیٰ نے کیا معاملہ کیا؟ یا کیا معاملہ کرے گا؟ تو اللہ تعالیٰ نےاس کی وضاحت کردی کہ صرف یہود ہی نہیں، بل کہ نصاری اور صابی اپنے اپنے وقت میں جنھوں نےبھی اللہ اور یوم آخرت پر ایمان رکھا اور عمل صالح کرتے رہے، وہ سب نجات اخروی سے ہمکنار ہوں گے۔اسی طرح اب رسالت محمدیہ پر ایمان لانے والے مسلمانوں نے بھی اگرصحیح طریقے سےاللہ اور یوم آخرت پر ایمان رکھا اور عمل صالح کرتے رہے تو آخرت کی ابدی نعمتوں کے مستحق ہوں گے، نجات اخروی میں کسی کے ساتھ امتیاز نہیں برتاجائے گا، چاہےمسلمان ہوں یا رسول آخر الزماں سے پہلےگزر جانے والے یہودی، عیسائی یا صابی وغیرہ۔ اس کی تائید بعض آثار سےہوتی ہے۔سلمان فارسی رضی اللہ عنہ فرماتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سے ایسے دین والوں کے بارے میں پوچھا جومجھ سےپہلے تھے، عبادت گزار اور نماز ی تھے (یعنی رسالت محمدیہ سے پہلےوہ اپنے وقت کے دینِ الٰہی کے پابند تھے) تو اس موقع پر (سورہ مائدہ کی مذکوربالا)آیت نازل ہوئی (تفسیر ابن کثیر)\nعبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ یہ آیت آل عمران کی آیت: ﴿وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينࣰ ا فَلَن يُقۡبَلَ﴾ [آل عمران: ۸۵]سے منسوخ ہے۔ ارشاد نبوی ہے: \"قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے۔میری امت میں جو شخص بھی میرے بارے سن لے وہ یہودی ہو یا نصرانی، پھر وہ مجھ پر ایمان نہ لائے تو وہ جہنم میں جائے گا۔ (صحیح مسلم: کتاب الایمان، باب وجوب الایمان برسالۃ نبینا محمد صلی اللہ علیہ وسلم )\nاللہ تعالیٰ کا ارشادہے: ﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـِٔينَ وَٱلنَّصَٰرَىٰ وَٱلۡمَجُوسَ وَٱلَّذِينَ أَشۡرَكُوٓاْ إِنَّ ٱللَّهَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ شَهِيدٌ﴾ [الحج: ۱۷] \"جو لوگ مومن ہیں اور جو یہودی ہیں اور صابی، عیسائی،مجوسی اورمشرک۔ اللہ تعالی ان سب میں قیامت کے دن فیصلہ کردے گا۔بےشک اللہ تعالیٰ ہر چیز سے باخبر ہے\"۔\nقرآن مجید کی اس آیت سے یہ بات ثابت ہوتی ہےکہ صابیوں کا وجود نبی اکرم صلی اللہ علیہ وسلم کے دور میں تھا اور آپ کی زندگی میں صابی پائے جاتے تھے۔ کچھ تاریخ نویسوں نے لکھا ہےکہ ان کی بستیاں ملک شام (سوریا) میں پائی جاتی تھیں۔ چونکہ قریش کے لوگ تجارت کے لیے ملک شام جایا کرتے تھے۔ اس لیے انھیں ان کے بارے میں پورا علم تھا۔جب اسلام ملک عرب کے ہرگھر میں داخل ہوگیا تو صابیوں میں سے بہت سارے لوگ مسلمان ہوگئے۔ وہ شام کےشہر حاران میں اکٹھا ہوگئے۔ وہاں ان کا ایک عبادت خانہ بھی تھا۔ اس میں چاند کی پوجا کی جاتی تھی۔اسی لیے صابیوں کو ستارہ پرست بھی کہاجاتاہے۔ان کا یہ عقیدہ تھا کہ روح کی قوت بہت بڑی ہے۔اس کے ذریعے سے بندہ اللہ تک پہنچ سکتا ہے۔اس لیے اپنے نفس پر قابو پانے اور اسے اپنے بس میں کرنے کے بعد ہی روح کی طاقت کو بڑھایا جاسکتا ہے۔اسلام کی کچھ تعلیمات کو بھی انھوں نے اپنے دین و مذہب میں داخل کرلیا تھا جیسے نماز۔ وہ لوگ تین اوقات میں نماز پڑھتےتھے اور اسے اللہ تک پہنچنے کا سب سے صحیح، اچھا ذریعے سمجھتے تھے۔ وہ سور، کتا وغیرہ اوراسی قسم کے دوسرےنجس جانوروں کاگوشت کھانا حرام سمجھتے اوراسےنہیں کھاتے تھے۔ اسلامی حکومت میں انھیں بڑی راحت ملی اور یہ لوگ عباسی خلیفہ کے وزیروں میں شامل ہوے۔پھر یہ لوگ اسلامی تعلیمات سے متاثر ہوے اور زیادہ تر لوگوں نے اسلام قبول کرلیا۔ اس وقت کچھ صابی ملک عراق میں پائے جاتے ہیں۔","",{}],[371,"§صاع\nصاع غلہ ناپنے کا پیمانہ ہے۔ یہ لگ بھگ ڈھائی کیلو گرام کےبرابر ہوتا ہے۔ مد بھی ایک پیمانہ ہے۔ چار مدّ کا ایک صاع ہوتا ہے اور ساٹھ صاع کا ایک وسق۔ ان پیمانوں کا ذکر حدیثوں میں بار بار آتا ہے۔\nصاع کا ذکر یوسف علیہ السلام کے قصے میں اس طرح آیا ہے: ﴿قَالُواْ نَفۡقِدُ صُوَاعَ ٱلۡمَلِكِ وَلِمَن جَآءَ بِهِۦ حِمۡلُ بَعِيرࣲ وَأَنَا۠ بِهِۦ زَعِيمࣱ‏﴾ [یوسف: ۷۲] \"انھوں (خزانے میں غلے کے ناپنےوالوں)نے کہا: شاہی پیمانہ ہمیں نہیں مل رہا ہے، جو شخص اسے لادے اسے ایک اونٹ کے بوجھ بھر غلہ انعام ملے گا\"۔\nنبی اکرم صلی اللہ علیہ وسلم کے زمانےمیں بھی صاع استعمال ہوتا تھا۔اسی پیمانے کے ذریعےسےزکاۃ الفطر (صدقہ فطر) ادا کی جاتی تھی۔اسی پیمانے کے ذریعے سے کھجوروں کا اندازہ لگا کر زکاۃ لی جاتی تھی۔اسی پیمانے کی طرف اشارہ کرتے ہوے انس بن مالک رضی اللہ عنہ سےمروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم سےیہ دعا منقول ہے: «اللَّهُمَّ بَارِکْ لَهُمْ فِي مِکْيَالِهِمْ وَبَارِکْ لَهُمْ فِي صَاعِهِمْ وَمُدِّهِمْ: يَعْنِي أَهْلَ الْمَدِينَةِ». ( صحیح البخاری: ۲۱۳۰ وصحیح مسلم: ۱۳۶۸/۴۶۵) \"اے االلہ!ان کے مکیال (وزن) ان کے صاع اور مدّ میں برکت عطا فرما\"۔","",{}],[372,"§صالح علیہ السلام\nصالح علیہ السلام نوح علیہ السلام کی اولاد میں سے تھے۔ ان کے دادا کا نام ثمود تھا۔ انہی کی اولاد بعد میں قوم ثمود کہلائی۔\nبعض علماء کی رائے ہےکہ ان کا زمانہ ابراہیم علیہ السلام سے تقریباً تین سو سال قبل ہے۔ ان کی رہایش حجرمیں تھی، جو حجازاور تبوک کے درمیان واقع ہے۔اسی کی طرف قرآن اشارہ کرتا ہے: ﴿وَلَقَدۡ كَذَّبَ أَصۡحَٰبُ ٱلۡحِجۡرِ ٱلۡمُرۡسَلِينَ﴾ [الحجر: ۸۰] \"اورحجر کے لوگوں نے بھی رسولوں کو جھٹلایا\"۔\nقوم ثمود کا ذکرارسطو اوربطلیموس کی کتابوں میں بھی آتا ہے اوریہ بھی ملتا ہے کہ یہ لوگ دومة (DOMATHA) کے قریب میں آباد تھے جس کو آج دومة الجندل کہاجاتا ہے۔\nبعض علماء کے خیال میں عبرکے بیٹے فلج کو صالح کہتے ہیں۔ کیوں کہ ثمود کا زمانہ ابراہیم سے کوئی تین سو برس قبل تھا۔ کچھ دوسرے علماءارفکسدکے بیٹے شالح کو ہی ثمود کا صالح کہتے ہیں۔ لیکن اس کو ماننے میں یہ دقت ہے کہ جس قوم (ثمود) کی طرف ان کو بھیجا گیا، وہ ارفکشدکے بیٹے کے بعد کی کوئی قوم ہے۔\nکچھ علما نے ثمود اور صالح کا نسب نامہ اس طرح بیان کیا ہے۔\nارم (آرام) کا نام تورات میں سام کے بیٹوں میں ملتا ہے اور ارم کے بیٹے جاسر کا نام بھی آتا ہے۔ لیکن جس نسب نامہ کا ذکراوپر ہوا ہےوہ عبرانی مذہبی کتابوں اور مستند اسلامی تاریخ میں نہیں ملتا۔ اس لیےاس کے متعلق کوئی متعین بات نہیں کہی جاسکتی۔قوم ثمود جس کی طرف صالح علیہ السلام بھیجے گئے تھے۔عاد کے بعد کی کوئی قوم ہے جو پہاڑوں کو کاٹ چھانٹ کر گھر بناتی تھی۔اس کی تفصیل قرآن مجید میں آئی ہے: ﴿وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ عَادࣲ وَبَوَّأَكُمۡ فِي ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورࣰ ا وَتَنۡحِتُونَ ٱلۡجِبَالَ بُيُوتࣰ اۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ﴾ [الأعراف: ۷۴] \"وہ وقت یاد کرو جب اللہ نے عاد کے بعد تمھیں (اس کا) جانشین بنایا اور تمھیں زمین پر رہنے کا ٹھکانا دیا۔ تم اس کی نرم زمین پرمحل بناتے ہو اور پہاڑوں کو کاٹ چھانٹ کر ان کو گھر کی شکل دیتے ہو۔ پس اللہ کی نعمتوں کو یاد کرو اور زمین میں فساد مت پھیلاؤ\"۔\nثمود کےمتعلق جو بعض علما نے لکھا ہے ہم اس کی تائیدنہیں کرسکتے کیوں کہ ان کی باتوں کا کوئی ثبوت نہیں ملتا۔ اس لیے ہم یقین کے ساتھ یہ کہہ سکتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے زمانے میں قومِ ثمود کا کوئی قبیلہ بچا نہیں تھا۔\nقرآن مجیدسے یہ بھی پتا چلتا ہے کہ یہ قوم موسیٰ علیہ السلام سے پہلے تھی۔کیونکہ فرعون کے دربار میں ایمان والا ایک شخص فرعون کو ان الفاظ میں تنبیہ کرتے ہوے کہتا ہے: ﴿وَقَالَ ٱلَّذِيٓ ءَامَنَ يَٰقَوۡمِ إِنِّيٓ أَخَافُ عَلَيۡكُم مِّثۡلَ يَوۡمِ ٱلۡأَحۡزَابِ مِثۡلَ دَأۡبِ قَوۡمِ نُوحࣲ وَعَادࣲ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعۡدِهِمۡۚ وَمَا ٱللَّهُ يُرِيدُ ظُلۡمࣰ ا لِّلۡعِبَادِ﴾ [المؤمن: ۳۰-۳۱] \"اے میری قوم!مجھے ڈر ہے کہ کہیں تم پر وہ دن نہ آجائے جو دوسری قوموں پر آچکا ہے۔ کہیں وہی حال نہ ہو جو نوح کی قوم،عاد اور ثمود اور ان کے بعد والوں کا ہوا۔ اللہ بندوں پر ظلم کرنا نہیں چاہتا\"۔\nبلاشبہ یہ ایک بڑی قوم تھی،جو پہاڑوں کو کاٹ کر گھر بنایا کرتی تھی۔مؤلف کو ان کے گھروں کو دیکھنے کا موقع ملاہے۔ ان کو دیکھ کر ایسا لگتا ہے کہ ایک خاندان کے لیے ایک پہاڑ تھا۔ اس نے انھیں تراش کر کمرے بنا لیے ہیں۔ اس میں قصرالبنت اور دیوان بہت مشہور ہیں۔ ان کے دروازوں پر الگ الگ قسم کے جانوروں، چوپائے اور پرندوں کی تصویریں بنائی گئی ہیں۔ ایسا لگتا ہےکہ وہ لوگ ان کی عبادت کیا کرتے تھے اور اپنی طاقت پر ان کو بڑا فخر تھا۔ اللہ تعالیٰ نے توحید کی تبلیغ اور اپنی عبادت کے لیے صالح علیہ السلام کو اپنانبی بناکر ان کے پاس بھیجا: ﴿وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحࣰ اۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةࣱ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةࣰۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءࣲ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمࣱ‏﴾ [الأعراف: ۷۳] \"ثمود کی طرف اس کے بھائی صالح کو بھیجا۔ اس نے کہا:میری قوم کے لوگو! اللہ کی عبادت کرو اس کے سوا تمھارا کوئی معبود( الہ) نہیں \"۔\nلیکن قوم ثمود نے ان کی بات نہیں مانی۔ بلکہ یہ کہا کہ اگر تم سچے ہوتو کوئی نشانی دکھاؤ۔( الشعراء: ۱۵۴)\nمعجزہ کے طورپر اللہ تعالیٰ نے صالح کو ایک اونٹنی دی۔اس کی تفصیل قرآن مجیدمیں یوں آئی ہے:\n۱-﴿إِنَّا مُرۡسِلُواْ ٱلنَّاقَةِ فِتۡنَةࣰ لَّهُمۡ فَٱرۡتَقِبۡهُمۡ وَٱصۡطَبِرۡ﴾ [القمر: ۲۷] \"ہم ان کے امتحان کے لیے ایک اونٹنی بھیجنےوالے ہیں۔ تو تم انھیں دیکھتے رہواور صبر سے کام لو\"۔\n۲- ﴿قَالَ هَٰذِهِۦ نَاقَةࣱ لَّهَا شِرۡبࣱ وَلَكُمۡ شِرۡبُ يَوۡمࣲ مَّعۡلُومࣲ‏﴾ [الشعراء: ۱۵۵] \"صالح علیہ السلام نے کہا: یہ ایک اونٹنی ہے، ایک دن پانی پینے کی اس کی باری ہوگی۔ اور ایک دن تم لوگوں کی باری ہوگی\"۔\n۳- ﴿وَيَٰقَوۡمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةࣰۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءࣲ فَيَأۡخُذَكُمۡ عَذَابࣱ قَرِيبࣱ‏﴾ [ہود: ۶۴] \"اے میری قوم کے لوگو! یہ اللہ کی اونٹنی تمھارے لیے ایک نشانی ہے۔ اسے چھوڑ دو کہ اللہ کی زمین پر جہاں چاہے جائے اور کھائے پیئے\"۔\nیہ بھی کہا کہ اس کو کسی طرح کا نقصان نہیں پہنچانا،نہیں تو تم لوگوں کو عذاب گھیر لے گا۔(دیکھیے: ہود: ۶۴)\nلیکن ان لوگوں نے ظلم و زیادتی کی اور ایک جگہ پر جمع ہوکر اونٹنی کو مارنے کی کوشش کرنے لگے۔ اس واقعے کے بارے میں ارشادباری تعالیٰ ہے:\n۱- ﴿فَعَقَرُواْ ٱلنَّاقَةَ وَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ وَقَالُواْ يَٰصَٰلِحُ ٱئۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلۡمُرۡسَلِينَ﴾ [الأعراف: ۷۷] \"پھرانھوں (قوم ثمود)نے اس اونٹنی کی کونچوں (پاؤں ) کو کاٹ کر اسے مار ڈالا اور پوری ڈھٹائی کے ساتھ اپنے رب کے حکم کی نافرمانی کی اور کہنے لگے: اے صالح! تو ہمیں جس عذاب کی دھمکی دیتا ہے، اگر تو رسولوں میں سے ہے تو اسے ہم پر لے آ\"۔\n۲- ﴿كَذَّبَتۡ ثَمُودُ بِطَغۡوَىٰهَآ إِذِ ٱنۢبَعَثَ أَشۡقَىٰهَا فَقَالَ لَهُمۡ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقۡيَٰهَا فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمۡدَمَ عَلَيۡهِمۡ رَبُّهُم بِذَنۢبِهِمۡ فَسَوَّىٰهَا وَلَا يَخَافُ عُقۡبَٰهَا﴾ [الشمس: ۱۱-۱۵] \"ثمود نے اپنی سرکشی کی وجہ سے جھٹلایا، جب ان میں ایک بدنصیب اٹھ کھڑا ہوا،تو اللہ کے رسول نے کہا: خبردار! اللہ کی اونٹنی اور اس کے پانی پینے کی باری (کے درمیان) مت آنا۔ لیکن انھوں نے اس کو جھٹلایا اور اس اونٹنی کو اس کی کونچیں (پاؤں) کاٹ کر مار ڈالا، تو ان کے رب نے ان کے گناہ کی وجہ سے ان پر تباہی ڈالی اور ان کی (بستی) کو برابر کر دیا اوروہ ان کے انجام سے ڈرتا نہیں\"۔\nآخری آیت نے اس بات کی وضاحت کردی ہے کہ اللہ تعالیٰ اپنے کاموں پر نہ تو ندامت کرتا ہے اورنہ ڈرتا ہے۔ بلکہ وہ تو انتہائی طاقتور ہے۔ وہ یہودیوں کے اس اللہ کی طرح نہیں جو بسا اوقات اپنے کیے پر شرمندہ ہوتا ہے۔ جیسا کہ (تورات کی کتاب پیدایش: ۷ـ۶:۶اور۲۱:۸) میں آیا ہے۔\nآگے کا قصہ قرآن مجیدمیں اس طرح بیان ہوا ہے:﴿فَعَقَرُوهَا فَقَالَ تَمَتَّعُواْ فِي دَارِكُمۡ ثَلَٰثَةَ أَيَّامࣲۖ ذَٰلِكَ وَعۡدٌ غَيۡرُ مَكۡذُوبࣲ فَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا صَٰلِحࣰ ا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةࣲ مِّنَّا وَمِنۡ خِزۡيِ يَوۡمِئِذٍۚ إِنَّ رَبَّكَ هُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ وَأَخَذَ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَآ إِنَّ ثَمُودَاْ كَفَرُواْ رَبَّهُمۡۗ أَلَا بُعۡدࣰ ا لِّثَمُودَ﴾ [ہود: ۶۵-۶۸] \"تاہم انھوں نے اس کی کونچیں (پاؤں) کاٹ کر اسے مار ڈالا، تو اس نے کہا: اپنے گھروں میں تین دن اور مزے لے لو۔ یہ ایک ایسا وعدہ ہے جو کسی طرح جھوٹا نہیں ہوگا۔ پھر جب ہمارا حکم آگیا تو ہم نے اپنی رحم دلی سے صالح اور ان لوگوں کو، جو ان پر ایمان لائے تھے۔ بچالیا اور اس دن کی رسوائی سے انھیں بچا رکھا (یعنی آخرت کی رسوائی سے) بے شک تمھارا رب بڑا طاقت ور اور غالب ہے۔ اور ان لوگوں کو جنھوں نےظلم و زیادتی کی، ایک خوفناک چیخ نے آدبوچا۔ پھر وہ اپنے گھروں میں اوندھے پڑے رہ گئے۔ (اور وہ ایسے مٹے) مانو وہاں کبھی بسے ہی نہ تھے۔ سن رکھو کہ قوم ثمود نے اپنے رب سے کفر کیا۔ سن لو! کہ ثمود کو اللہ نے اپنی رحمت سے دور کر دیا۔ (یعنی اب وہ جہنمی ہوگئے)\"۔\nدوسری جگہ پر آیا ہے: ﴿فَأَمَّا ثَمُودُ فَأُهۡلِكُواْ بِٱلطَّاغِيَةِ﴾ [الحاقة: ۵] \"رہے ثمود تو وہ کڑک سے ہلاک کر دیے گئے\"۔\nایک دوسری جگہ پر ارشادباری تعالیٰ ہے: ﴿وَأَنَّهُۥٓ أَهۡلَكَ عَادًا ٱلۡأُولَىٰ وَثَمُودَاْ فَمَآ أَبۡقَىٰ﴾ [النجم: ۵۰-۵۱] \"یہ کہ اس (اللہ)نے پہلے عاد کو ہلاک کر دیا اور ثمود کو بھی باقی نہ چھوڑا\"۔\nیہ اس قوم کا انجام ہے، جس نے صالح علیہ السلام کو جھٹلایا، ان کی دعوت کا انکارکیا، ان کی لائی ہوئی نشانیوں کو بھی دیکھ کر ایمان نہیں لائے۔ اس لیے وہ اس زمین سے مٹا دیے گئے، کیونکہ انھوں نے خالق کائنات کی بات نہیں مانی، بلکہ اس کا انکار کیا۔ پھر ان کو اس زمین پر رہنے کا حق نہیں رہا اور وہ عذاب الٰہی کے ذریعے نیست و نابود کر دیے گئے۔ صحیح حدیث میں آیا ہے:\n۱-عبداللہ بن عمر رضی اللہ عنہما کہتےہیں کہ نبی اکرم صلی اللہ علیہ وسلم تبوک جاتے ہوے صالح علیہ السلام کے علاقے سے گزرے تو کچھ لوگ ثمود کے بنائے ہوےگھروں میں گھس گئے، تب آپ نے فرمایا:«لا تَدْخُلُوا مَسَاکِنَ الَّذِينَ ظَلَمُوا أَنْفُسَهُمْ إِلا أَنْ تَکُونُوا بَاکِينَ، أَنْ يُصِيبَکُمْ مَا أَصَابَهُمْ ثُمَّ تَقَنَّعَ بِرِدَائِهِ وَهُوَ عَلَی الرَّحْلِ». (صحیح البخاری: ۴۳۳ وصحیح مسلم: ۲۹۸۰/۳۸).\"یہ وہ لوگ ہیں جن پر اللہ کا عذاب آیا، اس لیے ان کے گھروں میں روتے ہوے داخل ہو۔(عبرت کے لیے) کہیں تم بھی اللہ کے عذاب میں نہ گھر جاؤ\"۔\n۲- عبداللہ بن عمر رضی اللہ عنہما کہتےہیں : «إِنَّ النَّاسَ نَزَلُوا مَعَ رَسُولِ اللَّهِ صلی اللہ علیہ وسلم أَرْضَ ثَمُودَ الْحِجْرَ، فَاسْتَقَوْا مِنْ بِئْرِهَا وَاعْتَجَنُوا بِهِ، فَأَمَرَهُمْ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم أَنْ يُهَرِيقُوا مَا اسْتَقَوْا مِنْ بِئْرِهَا وَأَنْ يَعْلِفُوا الإِبِلَ الْعَجِينَ، وَأَمَرَهُمْ أَنْ يَسْتَقُوا مِنْ الْبِئْرِ الَّتِي کَانَتْ تَرِدُهَا النَّاقَةُ». (صحیح البخاری: ۴۳۳ وصحیح مسلم: ۲۹۸۱/۴۰). \"لوگ رسول اللہ صلی اللہ علیہ وسلم کےساتھ ارض ثمود میں اترے تو اس کنویں کے پاس اتر گئے،جس سے قوم ثمود کے لوگ پانی پیتے تھے۔ اور لوگوں نے اس کنویں سے پانی نکالا، آٹا گوندھا اور آگ جلاکر کھانا پکانا شروع کر دیا۔ جب آپ کو اس کی خبر ملی تو آپ نے فرمایا: یہ پانی بہادو۔ دیگچیاں الٹ دو۔ جو آٹا تم نے گوندھ رکھا ہے اسے اونٹوں کو کھلا دو۔ پھر آپ نے وہاں سے چلنے کا حکم دیا اور اس کنویں پر پڑاؤ ڈالنے کا حکم دیا جس سے صالح علیہ السلام کی اونٹنی پانی پیتی تھی\"۔\nدوسری حدیث میں ہےکہ اسی وقت آپ نے فرمایا:«لا تَدْخُلُوا مَسَاکِنَ الَّذِينَ ظَلَمُوا أَنْفُسَهُمْ إِلا أَنْ تَکُونُوا بَاکِينَ أَنْ يُصِيبَکُمْ مَا أَصَابَهُمْ ثُمَّ تَقَنَّعَ بِرِدَائِهِ وَهُوَ عَلَی الرَّحْلِ». (صحیح البخاری: ۴۳۳، وصحیح مسلم: ۲۹۸۰/۳۸) \"ان لوگوں کے گھروں کی طرف مت جاؤجن پر اللہ کا عذاب آچکا ہے، کیونکہ مجھے ڈر ہے کہ تمھیں بھی ویسا ہی عذاب نہ گھیر لے۔ پھر آپ نے اپنا چہرہ ڈھانپ لیا\"۔\nیعنی ایسی جگہ کو تفریح کی جگہ نہیں بنانا چاہیے کیونکہ ایسے مقامات تو عبرت وموعظت کے لیے ہوتے ہیں کہ اگر ہم بھی اللہ کا انکار اور اس کی حکم عدولی کرتے رہے، اس کے بتائے ہوے راستے کو نہیں اپنایا اور اس کے بھیجے ہوے رسول کو جھٹلایا تو ہم بھی کہیں عذاب میں نہ گھرجائیں۔\nصالح علیہ السلام اور ان پر ایمان لانے والے موحدین عذاب کے بعد کہاں گئے؟ اس کےمتعلق قرآن اور صحیح حدیثوں میں کچھ نہیں آیا ہے۔اس لیے تاریخ نویسوں نے الگ الگ باتیں لکھی ہیں۔ کسی نے کہا کہ وہ فلسطین کی طرف چلے گئے۔کیوں کہ وہ ان کے چوپایوں کے لیے سب سے اچھی جگہ تھی۔ کچھ کی رائے ہے کہ وہ حضرموت (یمن)چلے گئے تھے، کیونکہ وہی ان کا اصل وطن تھا۔حضرموت میں ایک قبر آج بھی پائی جاتی ہے، جس کے بارے میں مشہور ہے کہ وہ صالح علیہ السلام کی ہے۔ بعض کی رائے کے مطابق عذاب کے بعد سارے انبیا مکہ چلےآتے تھے، تاکہ اللہ کی عبادت کر سکیں اور وہیں ان کی وفات ہوجاتی تھی۔ ان کی رائے ہے کہ اس وقت مکہ میں ایک سو بیس نبیوں کی قبریں ہیں۔ تاہم اس بات کو ماننے میں اشکال ہے۔ اگر ایسا ہوتا تو نبی اکرم صلی اللہ علیہ وسلم یقیناً ان قبروں کا تذکرہ کرتے، مگر ہمیں کسی صحیح حدیث میں اس کے متعلق کچھ نہیں ملتا۔\nسام کی اولاد مغربی ایشیا سے لے کر بحر ابیض متوسط تک پھیل گئی۔ اس نسل سے عربی، یہودی، آرامی اور آشوری قومیں پیدا ہوئیں۔ سامی زبان سے دو مشہور زبانیں نکلیں: ایک عربی اور دوسری عبرانی۔\nحام کی اولاد جزیرۃ العرب سےنکل کر مصر اور افریقہ تک پھیل گئی۔ کنعان حام کی اولاد تھے جو فلسطین میں یہودیوں سے پہلے آباد تھے۔ انہی کے ساتھ یہودیوں کی جنگ ہوئی اور یہود فلسطین پر قابض ہو گئے جو اصل میں مصر سے آئے تھے۔\nیافث کی اولاد جزائر بحر متوسط سے لےکر ہندستان اوریورپ تک پھیل گئی۔ بقیہ زمین پر ان کی مختلف نسلیں آباد ہوئیں جیسے امریکا،کینیڈا، اسٹریلیا وغیرہ۔ (مزید معلومات کے لئے دیکھیے: بائبل-سفر پیدائش إصحاح: ۹-۱۱، یا مختلف عناوین کے تحت قاموس الکتب المقدس )","",{}],[373,"§صبر\nانسانی زندگی کچھ ایسے مراحل سے گذرتی ہے جن میں صبر کرنے کے علاوہ کوئی چارا نہیں , اسی لئے قرآن کریم صبر کرنے پر ابھارتا ہے۔\n§صبر کی قسمیں:\nصبر کی تین قسمیں ہیں۔\n۱- صبر علی طاعۃ: یعنی اللہ تعالی کے فرمان پر عمل پیرا ہونے پر صبر کرنا۔\nبسااوقات فرمان الہی پر عمل کرنے میں دشواریوں کا سامنا کرنا پڑتا ہے, سچے مومن کی علامت یہ ہے کہ وہ رکاوٹوں کی پرواہ کئے بغیر فرمان الہی پر قائم رہتا ہے۔ اسی کو \"صبر علی طاعۃ\" کہتے ہیں۔ قرآن مجید میں ایسے لوگوں کی مدح سرائی کی گئی ہے جو اللہ تعالی کی خوشنودی حاصل کرنے کی غرض سے اس کے فرامین کو بجالاتے ہیں اور اس راہ میں آنے والی مصیبتوں پر صبر کرتے ہیں۔ اللہ تعالی کا ارشاد ہے: ﴿ٱلَّذِينَ صَبَرُواْ ٱبۡتِغَآءَ وَجۡهِ رَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ وَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ أُوْلَـٰٓئِكَ لَهُمۡ عُقۡبَى ٱلدَّارِ جَنَّـٰتُ عَدۡنٖ يَدۡخُلُونَهَا وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّـٰتِهِمۡۖ وَٱلۡمَلَـٰٓئِكَةُ يَدۡخُلُونَ عَلَيۡهِم مِّن كُلِّ بَابٖ سَلَٰمٌ عَلَيۡكُم بِمَا صَبَرۡتُمۡۚ فَنِعۡمَ عُقۡبَى ٱلدَّارِ﴾ [الرعد: ۲۲-۲۴]\nترجمہ: اور جنہوں نے اپنے رب کی رضا چاہتے ہوئے صبر کیا, صلوۃ قائم کی اور اللہ نے جو کچھ انہیں دے رکھا ہے اس میں سے خفیہ اور علانیہ خرچ کیا اور برائی کا بھلائی سے جواب دیا , یہی لوگ ہے جن کے لئے دار آخرت ہے۔ جو ہمیشہ قائم رہنے والے باغ ہیں جن میں وہ اور ان کے آباء واجداد, ان کی بیویوں اور ان کی اولاد میں سے نیکو کار داخل ہوں گے , اور فرشتے (جنت کے) ہر دروازے سے ان کے استقبال کو آئیں گے (کہیں گے) تم پر سلامتی ہو کیونکہ تم صبر کرتے رہے سو یہ دار آخرت کیا ہی اچھا ہے۔\nاسی طرح اولو العزم رسول یعنی نوح, ابراہیم, موسی اور عیسی علیہم السلام کے صبر کی تعریف کرتے ہوئے اللہ تعالی نے اپنے پیغمبر محمد صلی اللہ علیہ وسلم کو بھی صبر کرنے کا حکم دیا۔ فرمایا: ﴿فَٱصۡبِرۡ كَمَا صَبَرَ أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ وَلَا تَسۡتَعۡجِل لَّهُمۡ﴾ [الأحقاف: ۳۶]\nترجمہ: صبر کیجئے جیسے اولو العزم رسولوں نے صبرکیا اور ان کے بارے میں جلدی نہ کیجئے۔\nنیز فرمایا: ﴿ٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَيۡدِۖ إِنَّهُۥٓ أَوَّابٌ﴾ [ص: ۱۷]\nترجمہ: آپ ان کی باتوں پر صبر کرو اور ہمارے بندے داؤد کو بھی یاد کرو بلاشبہ وہ صاحب قوت اوراللہ کی طرف رجوع کرنے والا تھا۔\nاس آیت کریمہ اللہ تعالی نے نبی اکرم صلی اللہ علیہ وسلم کو حکم دیا ہے کہ وہ مشرکوں کی ایذاء رسانی پر صبر کریں اور داؤد علیہ السلام کے صبر وتحمل کو یاد کریں۔\n۲- صبر عن معصیۃ: یعنی اللہ تعالی کی نا فرمانی نہ کرنے پر صبر کرنا۔\nاللہ تعالی کا ارشاد ہے: ﴿إِن تَجۡتَنِبُواْ كَبَآئِرَ مَا تُنۡهَوۡنَ عَنۡهُ نُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَنُدۡخِلۡكُم مُّدۡخَلٗا كَرِيمٗا﴾ [النساء: ۳۱] ترجمہ: تم اگر بڑے بڑے گناہوں سے بچتے رہے تو ہم تمہاری چھوٹی برائیوں کو نظر انداز کردیں گے اور تمہیں عزت کے مقام میں داخل کریں گے۔\nاسی طرح فرمایا: ﴿وَجَزَىٰهُم بِمَا صَبَرُواْ جَنَّةٗ وَحَرِيرٗا﴾ [الإنسان: ۱۲]\nترجمہ: اور (اللہ تعالی) انہیں صبر کے بدلے جنت اور ریشمی لباس دے گا۔\nاور جو برائی کا جواب بھلائی سے دیتے ہیں, دین پر ثابت قدم رہتے ہوئے اللہ تعالی کے راستے میں خرچ کرتے ہیں , ان کے متعلق فرمایا: ﴿أُوْلَـٰٓئِكَ يُؤۡتَوۡنَ أَجۡرَهُم مَّرَّتَيۡنِ بِمَا صَبَرُواْ وَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ﴾ [القصص: ۵۴]\nترجمہ: یہی ہیں جنہیں ان کا اجر دوبارہ دیا جائے گا اس ثابت قدمی کے بدلے میں کہ برائی کا جواب بھلائی سے دیتے ہیں اور جو ہم نے انہیں دے رکھا ہے اس میں سے خرچ کرتے ہیں۔\n۳- صبر علی اقدار اللہ: یعنی اچھی بری تقدیر پر رضامندی کا اظہار کرنا۔\nمؤمن تقدیر کے اچھے اور برے ہونے پر ایمان رکھتا ہے۔ جب اس پر کوئی مصیبت آتی ہےتو وہ یہ سوچ کر اس پر صبر کرتا ہے کہ یہ اللہ کی طرف سے اس کے لئے آزمائش ہے, جبکہ کافر مصیبت وپریشانی کے عالم میں حد درجہ اضطراب وبے چینی کا شکار ہوجاتا ہے , کیونکہ وہ تقدیر پر ایمان نہیں رکھتا۔\nاللہ تعالی فرماتا ہے: ﴿وَإِن تُصِبۡهُمۡ حَسَنَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِ ٱللَّهِۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِكَۚ قُلۡ كُلّٞ مِّنۡ عِندِ ٱللَّهِۖ فَمَالِ هَـٰٓؤُلَآءِ ٱلۡقَوۡمِ لَا يَكَادُونَ يَفۡقَهُونَ حَدِيثٗا﴾ [النساء: ۷۸]\nترجمہ: اگر انہیں کوئی فائدہ پہنچے تو کہتے ہیں کہ \" یہ اللہ کی طرف سے پہنچا ہے\" اور اگر کوئی مصیبت پڑجائے تو کہتے ہیں کہ: یہ تمہاری وجہ سے پہنچی ہے\"؟! آپ (ان سے) کہئے کہ \" سب کچھ ہی اللہ کی طرف سے ہوتا ہے\"۔\nنبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «وَاعْلَمْ أَنَّ الأُمَّةَ لَوْ اجْتَمَعَتْ عَلَی أَنْ يَنْفَعُوکَ بِشَيْءٍ لَمْ يَنْفَعُوکَ إِلاَّ بِشَيْءٍ قَدْ کَتَبَهُ اللَّهُ لَکَ، وَلَوْ اجْتَمَعُوا عَلَی أَنْ يَضُرُّوکَ بِشَيْءٍ لَمْ يَضُرُّوکَ إِلاَّ بِشَيْءٍ قَدْ کَتَبَهُ اللَّهُ عَلَيْکَ، رُفِعَتِ الأَقْلاَمُ وَجَفَّتْ الصُّحُفُ» (سنن ترمذی: ۲۵۱۶)\nترجمہ: جان لو! اگر سارے لوگ متحد ہوکر تمہیں نفع پہنچانا چا ہیں تو وہ تمہیں بس اتنا ہی فائدہ پہنچاسکیں گے جتنا کہ اللہ تعالی نے (تمہاری تقدیر میں) لکھا ہے, اسی طرح اگر وہ تمہیں نقصان پہنچا نا چاہیں تو اتنا ہی نقصان پہنچاسکتے ہیں جتنا تقدیر میں لکھا ہے, قلم کو اٹھا لیا گیا ہے اور دفتر بھی سوکھ چکے ہیں۔\nقلم کے اٹھالینے کا مفہوم یہ ہے کہ ہر چیز لوح محفوظ میں لکھی جاچکی ہے اور کاتب, کتابت سے فارغ ہوچکا ہے, اسی طرح دفتر بھی سوکھ چکے ہیں لہٰذا دفتروں میں لکھی ہوئی باتوں کو مٹایا نہیں جاسکتا۔\nصبر کرنے والوں کو صبر کا پھل کبھی دنیا میں حاصل ہوتا ہے تو کبھی اجرو ثواب اور رفع درجات کی صورت میں جنت میں نصیب ہوگا۔\nجب موسی علیہ السلام اور ان کے ساتھیوں نے مشکل حالات میں وقت کے جابر وظالم بادشاہ \"فرعون\" کے ظلم وستم پر صبر کرتے ہوئے دین پر استقامت برتنے کا ثبوت پیش کیا تو اللہ تعالی نے فرعون اور اس کی قوم کو ہلاک کرکے انہیں دنیا ہی میں \"صبر\" کا بدلہ عطا کیا۔\nاللہ تعالی کا ارشاد ہے: ﴿لَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَآ أَنۡ أَخۡرِجۡ قَوۡمَكَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَذَكِّرۡهُم بِأَيَّىٰمِ ٱللَّهِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ إِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ أَنجَىٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ وَيُذَبِّحُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ عَظِيمٞ﴾ [إبراهيم: ۶]\nترجمہ: اور ہم نے موسی علیہ السلام کو اپنے معجزے دے کر بھیجا (اور حکم دیا کہ اپنی قوم کو اندھیروں سے نکال کر روشنی میں لاؤ اور انہیں \"ایام اللہ\" سے عبرت دلاؤ, ان واقعات میں صبر اور شکر کرنے والوں کے لئے بہت نشانیاں ہیں۔ اور (یاد کرو) جب موسی علیہ السلام نے اپنی قوم سے کہا: اللہ کے اس احسان کو یاد کرو جو اس نے تم پر کیا تھا, جب اس نے تمہیں فرعونیوں سے نجات دی وہ تمہیں بہت بری سزا دیتے تھے, تمہارے بیٹوں کو تو مار ڈالتے تھے اور تمہاری عورتوں کو زندہ رکھتے تھے, اور اس میں تمہارے رب کی طرف سے بہت بڑی آزمائش تھی۔\nجو لوگ مشکل حالات میں صبر کرتے ہوئے کار خیر کو انجام دیتے ہیں آخرت میں ان کے لئے اجر عظیم کا وعدہ ہے۔\nاللہ تعالی کا ارشاد ہے: ﴿إِلَّا ٱلَّذِينَ صَبَرُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ أُوْلَـٰٓئِكَ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٞ﴾ [ہود: ۱۱]\nترجمہ: مگر جنہوں نے صبر کیا اور اچھے عمل کئے ایسے ہی لوگوں کے لئے مغفرت اور بہت بڑا اجر ہے۔","",{}],[374,"§صحابہ کرام رضی اللہ عنہم\nصحابہ وہ لوگ ہیں جونبی اکرم محمد صلی اللہ علیہ وسلم پر ایمان لائے اور ہر طرح کی تکلیفوں کو جھیلتے ہوےبھی آپ کا ساتھ نہ چھوڑا۔اسلام کی نظر میں ان کو بڑا عظیم مقام ومرتبہ حاصل ہے۔ کیونکہ انھیں کے ذریعےسے ہم تک اسلام پہنچا۔ اس لیےقرآن مجید میں مختلف انداز سے ان کاتذکرہ آیا ہے۔ کہیں یہ بتایا گیا ہے کہ محمد صلی اللہ علیہ وسلم اللہ کےرسول ہیں اور جو لوگ ان کے ساتھ ہیں وہ کفار کے لیے تو سخت ہیں،لیکن آپس میں رحم دل۔ (سورہ الفتح:۲۹) اسلام پر ان کا کامل یقین ہے۔کہیں ان کو خیرامت کہہ کر خطاب کیا گیا ہے: ﴿كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَتُؤۡمِنُونَ بِٱللَّهِۗ وَلَوۡ ءَامَنَ أَهۡلُ ٱلۡكِتَٰبِ لَكَانَ خَيۡرࣰ ا لَّهُمۚ مِّنۡهُمُ ٱلۡمُؤۡمِنُونَ وَأَكۡثَرُهُمُ ٱلۡفَٰسِقُونَ﴾ [آل عمران: ۱۱۰] \"تم بہترین امت ہو جو لوگوں کے لیے پیدا کی گئی ہے تم نیک باتوں کا حکم کرتے ہو اور بری باتوں سے روکتے ہو اور اللہ تعالیٰ پر ایمان رکھتے ہو اگر اہل کتاب بھی ایمان لاتے تو ان کے لئے بہتر تھا۔ان میں ایمان لانے والے بھی ہیں، لیکن اکثر تو فاسق ہیں\"۔\nاگرچہ اس آیت میں سارے مسلمانوں کو خطاب کیا گیا، تاہم ابتداً جن لوگوں کو خطاب کیا گیا وہ صحابہ کرام ہی تھےاوروہی اس لقب کےسب سے زیادہ مستحق ہیں۔\nکہیں اللہ نے صرف صحابہ کو ہی خطاب کرتے ہوے کہا: ﴿لَّقَدۡ رَضِيَ ٱللَّهُ عَنِ ٱلۡمُؤۡمِنِينَ إِذۡ يُبَايِعُونَكَ تَحۡتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِي قُلُوبِهِمۡ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيۡهِمۡ وَأَثَٰبَهُمۡ فَتۡحࣰ ا قَرِيبࣰ ا﴾ [الفتح: ۱۸] \"یقیناً اللہ تعالیٰ مومنوں سے خوش ہوگیا جبکہ وہ درخت تلے تجھ سے بیعت کر رہے تھے ان کے دلوں میں جو تھا اسے اس نے معلوم کرلیااور ان پر اطمینان نازل فرمایا اور انھیں قریب کی فتح عنایت فرمائی\"۔\nاس آیت میں اللہ تعالی نے واضح طور پر بتادیا کہ وہ صحابہ سے راضی (خوش) ہے۔\nجب ہم صحابہ کرام کی سیرت کا مطالعہ کرتے ہیں تو پتا چلتا ہے کہ انھوں نے دین اسلام قبول کرنے کے بعد بہت تکلیفیں جھیلیں۔ پھر بھی نبی اکرم صلی اللہ علیہ وسلم کا ساتھ نہ چھوڑا۔ گھروں سے نکالے گئے،ریگستان کی تپتی زمین پرگھسیٹا گیا۔ان کے جسم پرکوڑے برسائے گئے، گھربار چھوڑنے کے بعد بھی ان کا پیچھاکیا گیا۔اس پر بھی ان لوگوں نے اسلام نہیں چھوڑا (دیکھیے:ہجرت) یہ سب اس لیے کہ وہ ایک اللہ پر ایمان لائےہوے تھے،جس کی وجہ سے بتوں کی پرستش کرنے والے کافروں اورمشرکوں کویہ بات پسند نہیں آئی اور انھوں نے مختلف طریقوں سے ان کو تکلیف پہنچائی۔ ان ایمان لانے والوں نے صبر سےکام لیا۔ جو اللہ کو پسندآگیا اوراس نے قیامت تک لیے اور ہمیشہ کے لیے انھیں زندہ جاوید بنا دیا۔اس لیے کسی مسلمان کے لیے مناسب نہیں کہ ان کو برا کہے۔ اسی کی طرف اشارہ کرتے ہوےابوسعید خدری رضی اللہ عنہ سےمروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:«لا تَسُبُّوا أَصْحَابي فَلَوْ أَنَّ أَحَدَکُمْ أَنْفَقَ مِثْلَ أُحُدٍ ذَهَبًا مَا بَلَغَ مُدَّ أَحَدِهِمْ وَلا نَصِيفَهُ». (صحیح البخاری: ۳۶۷۳،صحیح مسلم: (۲۵۴۱/۲۲۲) \"میرے ساتھیوں (صحابہ) کو برا مت کہو، میں اس کی قسم کھا کرکہتا ہوں جس کے ہاتھوں میں میری جان ہے،اگر تم میں سے کوئی اُحدپہاڑ کے برابر بھی سونا خرچ کردے تو بھی ان کےمقام کےایک مد، بلکہ آدھےمدکےبرابر بھی نہیں پہنچ سکتا\"۔\n§صحابہ کرام کی تعداد:\nنبی اکرم صلی اللہ علیہ وسلم کے ہاتھ پر اسلام قبول کرنےوالوں کے ناموں کی کوئی فہرست نہیں ملتی، لیکن علماء کا خیال ہےکہ آپ کی وفات کے وقت ان کی تعداد ایک لاکھ بیس ہزار سے زیادہ تھی۔ کیوں کہ ایک لاکھ صحابہ تو آپ کے ساتھ حجۃ الوداع میں شریک ہوے تھے،جب کہ بہت سارے لوگ مدینہ اور اس کے گردو نواح میں تھے جو حج میں نہیں جاسکے تھے۔\n§اسلام قبول کرنے والے پہلے صحابہ:\n(۱)بچوں میں سب سے پہلے اسلام قبول کرنے والے، علی بن ابی طالب رضی اللہ عنہ آپ کے چچا کے لڑکے اور دامادتھے۔\n(۲)عورتوں میں سب سے پہلے اسلام قبول کرنے والی خدیجہ بنت خویلدڤنبی اکرم صلی اللہ علیہ وسلم کی بیوی تھیں۔\n(۳)بڑے مردوں میں سب سے پہلے اسلام قبول کرنےوالےابوبکر رضی اللہ عنہ مسلمانوں کے پہلے خلیفہ، آپ کے جگری دوست اور خسرتھے۔\n(۴)آزادکردہ غلاموں میں سب سے پہلے اسلام قبول کرنے والے زید بن حارثہ رضی اللہ عنہ جن کو ام المومنین خدیجہ ڤنےآپ کی خدمت کے لیے ہدیہ کیا تھا۔پھر آپ نے انھیں آزاد کردیا، لیکن وہ آپ کے پاس ہی رہے، کہیں اور جانے سے انکار کردیا۔\n§مشہور صحابہ کرام :\nمشہورصحابہ کرام میں سب سے پہلے چار خلفائے راشدین آتے ہیں، جو یہ ہیں :\nابوبکرصدیق، عمرفاروق، عثمان ذوالنورین، علی رضی اللہ عنہم :\n(۱)ابوبکر صدیق رضی اللہ عنہ :\nمسلمان اس بات پرمتفق ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے بعد ابوبکر رضی اللہ عنہ سب سے افضل ہیں۔ اس لیے جس دن آپ کی وفات ہوئی، اسی دن اہل مدینہ نے ان کے ہاتھ پرخلیفہ رسول ہونے کی بیعت کرلی۔ اگر کوئی پہلے دن بیعت نہ کرسکا تو اس نے بعد میں کرلی۔ابوبکر رضی اللہ عنہ کی خلافت کی کل مدت دوسال تین ماہ آٹھ دن ہے۔ وفات سنہ۳ا ہجری میں ہوئی۔ اس وقت ان کی عمر ترسٹھ سال تھی۔ ان کو صحابہ میں سب سے افضل مانا جاتا ہے۔انھوں نےنبی اکرم صلی اللہ علیہ وسلم کا ساتھ اس وقت بھی دیا، جب آپنے مکہ سے ہجرت کی۔ ابوبکر رضی اللہ عنہ کو یقین تھا کہ کفار مکہ ضرورپیچھا کریں گے۔اس لیے شمال کا راستہ چھوڑ کر،جو مدینہ جاتا تھا، جنوب کا راستا اختیار کیا اور ایک غار میں تین دن تک روپوش رہے۔ دشمن آپ کو تلاش کرتے ہوےغار کے دہانے پر پہنچ گئے، جس کی وجہ سےابوبکر رضی اللہ عنہ پریشان ہوگئےکہ اگر انھوں نے جھانک کر دیکھا تو وہ ہمیں دیکھ لیں گے، مگرنبی اکرم صلی اللہ علیہ وسلم ذرابرابر بھی نہیں ڈرے، بلکہ ان کو تسلی دی کہ فکر نہ کرو، اللہ ہمارے ساتھ ہے۔ قرآن کریم میں اسی کی طرف اشارہ ہے:﴿إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِينَ كَفَرُواْ ثَانِيَ ٱثۡنَيۡنِ إِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيۡهِ وَأَيَّدَهُۥ بِجُنُودࣲ لَّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُواْ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِيَ ٱلۡعُلۡيَاۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ﴾ [التوبة: ۴۰] \"اگر تم نبی کی مدد نہ کرو تو (کیا ہوجائے گا) اللہ نے ان کی مدد اس وقت کی جب کہ انھیں کافروں نے (مکہ سے) نکال دیا تھا۔ وہ دو میں سے دوسرےتھے جب وہ دونوں غار میں تھے۔ جب یہ اپنے ساتھی سے کہہ رہے تھے کہ غم نہ کر، اللہ ہمارے ساتھ ہے۔ چنانچہ جناب باری نے اپنی طرف سے اس پر تسکین نازل فرما کران لشکروں سے اس کی مدد کی جنھیں تم نے دیکھا ہی نہیں، اس نے کافروں کی بات پست کردی اور بلندو عزیز تو اللہ کا کلمہ ہی ہے۔ اللہ غالب ہے، حکمت والا ہے\"۔\nنبی اکرم صلی اللہ علیہ وسلم کو یقین کامل تھا کہ جب اللہ نے آپ کوآخری نبی بنا کر بھیجا ہے تو وہ خود آپ کی حفاظت کرے گا۔سورہ المائدہ یوں تو مدینہ میں اتری، پھربھی اس کی یہ آیت مکی ہے: ﴿يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغۡ مَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَۖ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ وَٱللَّهُ يَعۡصِمُكَ مِنَ ٱلنَّاسِۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ﴾ [المائدة: ۶۷] \"اللہ لوگوں (دشمن) سے آپ کی حفاظت کرے گا\"۔\nیہ ایک ایسا معجزہ ہے جو ہجرت سے پہلے سچا ثابت ہوا اور ہجرت کے بعد بھی۔\nصحیح حدیثوں میں ابوبکر صدیق رضی اللہ عنہ کی بڑی فضیلت بیان کی گئی ہے۔ ابوسعیدخدری رضی اللہ عنہ سے روایت ہے کہ ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم نے خطبہ میں فرمایا:«لَوْ کُنْتُ مُتَّخِذًا خَلِيلا مِنْ أُمَّتِي لاتَّخَذْتُ أَبَا بَکْرٍ وَلَکِنْ أُخُوَّةُ الإِسْلامِ وَمَوَدَّتُهُ، لا يَبْقَيَنَّ فِي الْمَسْجِدِ بَابٌ إِلا سُدَّ إِلا بَابُ أبی بَکْرٍ». (صحیح البخاری: ۴۶۶، وصحیح مسلم: ۲۳۸۳/۲) \"اگر میں کسی کو خلیل(جگری دوست) بناتا تو ابو بکر کو بناتا،لیکن اس کے بدلےمیں اسلام کی اخوت اور دوستی کافی ہے، مسجد میں ابو بکر کی طرف کے دروازے کے سوا تمام دروازے بند کر دیئے جائیں \"۔\n(۲)عمر بن خطاب رضی اللہ عنہ :\nسن۳ا ہجری میں ابوبکر رضی اللہ عنہ نےعمر رضی اللہ عنہ کوخلیفہ نامزدکیااورامت نےآپ کی خلافت پراتفاق کیا۔سن ۲۳ ہجری میں شہید کردیے گئے۔قاتل ابولؤ لؤ فیروزنامی ایک مجوسی غلام تھا۔ اس طرح ان کا دور خلافت دس سال ساڑھے چھ ماہ رہا۔ یہ پہلے خلیفہ ہیں جن کو امیرالمومنین کالقب دیاگیا۔شہادت کے وقت آپ کی عمر ترسٹھ سال تھی۔ ان کے دور خلافت میں جوجنگیں ہوئیں ان میں: یرموک، قادسیہ اور نہاوندکی جنگیں مشہور ہیں، جن میں مسلمانوں کو فتح حاصل ہوئی اور اسلامی حکومت جزیرۂ عرب سےلےکرمصر، شام (سوریا)،عراق اور ایران تک پهیل گئی۔صحیح حدیثوں میں عمر رضی اللہ عنہ کی بڑی فضیلت بتائی گئی ہے۔ وہ اپنے ایمان میں اتنے پکےاورہیبت والے تھے کہ ایک موقع پرنبی اکرم صلی اللہ علیہ وسلم نے ان سے فرمایا: «وَالَّذِي نَفْسِي بِيَدِهِ مَا لَقِيَکَ الشَّيْطَانُ قَطُّ سَالِکًا فَجًّا إِلا سَلَکَ فَجًّا غَيْرَ فَجِّکَ». (صحیح البخاری: ۳۲۹۴، وصحیح مسلم: ۲۳۹۶/۲۲ بروایت سعد بن ابی وقاص رضی اللہ عنہ ) \"اس اللہ کی قسم جس کے ہاتھ میری جان ہے! تم جس راہ سے گزرتے ہو شیطان اس راہ کو چھوڑ کر کوئی اور راستا اختیار کرلیتا ہے\"۔\nابوہریرہ رضی اللہ عنہ سےمروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «لَقَدْ کَانَ فِيمَنْ کَانَ قَبْلَکُمْ مِنْ بَنِي إِسْرَائِيلَ رِجَالٌ يُکَلَّمُونَ مِنْ غَيْرِ أَنْ يَکُونُوا انبیا، فَإِنْ يَکُنْ مِنْ أُمَّتِي مِنْهُمْ أَحَدٌ فَعُمَرُ». (صحیح البخاری: ۳۴۶۹) \" بنی اسرائیل میں کچھ لوگ تھے، جو نبی تونہیں تھے تاہم ان کو الہام ہوا کرتا تھا۔ اگر میری امت میں کوئی ایسا ہوسکتا ہے تو وہ عمر ہے\"۔\nعمر بن خطاب رضی اللہ عنہ کی رائے ایسی ہوتی تھی جیسے ان کو اللہ کی جانب سے الہام کیا گیا ہے۔ اس لیے خود عمر کا قول ہے: «وَافَقْتُ رَبِّي فِي ثَلاثٍ فِي مَقَامِ إِبْرَاهِيمَ وَفِي الْحِجَابِ وَفِي أُسَارَی بَدْرٍ». (صحیح مسلم: ۲۴/۲۳۹۹ بروایت عبداللہ بن عمر رضی اللہ عنہما ) \"تین باتوں میں میرے رب نے میری رائے کی تائید کی ہے: مقام ابرہیم،پردہ اور بدر کے قیدی۔ یعنی ان تینوں کے بارے میں میری رائے کی تائید میں آیتیں اتریں۔ بل کہ یہ مقامات بقول ابن حجر پندرہ تک پہنچتے ہیں\"۔(فتح الباری)\n(۳)عثمان بن عفان رضی اللہ عنہ :\nیہ مسلمانوں کے تیسرے خلیفۂ راشدہیں۔عمر بن خطاب رضی اللہ عنہ نے اپنے بعدخلافت کے لیے چھے بزرگ صحابہ کی ایک کمیٹی بنادی تھی، جس کے ممبران یہ تھے:۱- عثمان بن عفان، ۲- علی بن ابی طالب، ۳-طلحہ بن عبید اللہ، ۴- سعد بن ابی وقاص، ۵-عبد الرحمن بن عوف، ۶- زبیر بن عوام اورکہا: آپ لوگ آپس میں کسی ایک کوخلیفہ منتخب کر لیں۔ متفقہ طورسےسب نےعثمان بن عفان رضی اللہ عنہ کو اپناخلیفہ منتخب کر لیا۔\nاس طرح عمر رضی اللہ عنہ کی شہادت کے بعد سنہ ۲۴ ہجری میں عثمان رضی اللہ عنہ مسلمانوں کےخلیفہ بنائے گئے اورسن ۳۵ ہجری کو وہ بھی شہید کردیے گئے۔ ان کی مدت خلافت دس دن کم بارہ سال رہی۔ ان کو شہیدکرنے والوں میں کنانہ بن بشر، قطیرہ سکونی اور عبدالرحمن بن عدیس تھے۔ جو سب کے سب مصری تھے اورعبدااللہ بن سبایہودی کے ساتھی تھے۔ ان کے دور خلافت میں اسلامی سلطنت شمالی افریقہ تک پهیل گئی تھی۔\nصحیح حدیثوں میں ان کی بھی بڑی فضیلت بیان کی گئی ہے۔ اس سے بڑھ کر فضیلت اور کیا ہوسکتی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نےاپنی ایک بیٹی کی وفات کےبعد دوسری بیٹی کا بھی عثمان رضی اللہ عنہ سے نکاح کردیا۔\nعثمان رضی اللہ عنہ اتنے شرمیلے تھےکہ ایک بارنبی اکرم صلی اللہ علیہ وسلم ام المومنین عائشہ ڤکے گھر میں اس طرح لیٹے ہوے تھے کہ آپ کی پنڈلی کا کچھ حصہ کھلا ہوا تھا۔ اتنے میں ابوبکر رضی اللہ عنہ نے دروازے پر دستک دی اور اندر آنے کی اجازت مانگی۔ ان کو اجازت مل گئی، تھوڑی دیر کے بعد عمر رضی اللہ عنہ کو اجازت مل گئی اورآپ اسی حالت میں لیٹے رہے۔ تھوڑی دیر بعدعثمان رضی اللہ عنہ نے اندر آنے کی اجازت مانگی تو آپ اٹھ کربیٹھ گئے اور اپنے کپڑے برابر کر لیے\"۔ عائشہ ڤنے بالآخر آپ سے کہا: ابوبکر رضی اللہ عنہ آئے تو آپ ویسے ہی لیٹے رہے، عمر رضی اللہ عنہ آئے تب بھی آپ ویسے ہی لیٹے رہے اور جب عثمان رضی اللہ عنہ آئے تو آپ سنبھل کر بیٹھ گئے اور اپنا کپڑا بھی ٹھیک کرلیا؟! آپ نے فرمایا: «أَلا أَسْتَحِي مِنْ رَجُلٍ تَسْتَحِي مِنْهُ الْمَلائِکَةُ». ( صحیح مسلم: ۲۶/۲۴۰۱) \"کیا میں اس شخص سے نہ شرماؤں جس سے فرشتے بھی شرماتے ہیں\"۔\n(۴)علی بن ابی طالب رضی اللہ عنہ :\nیہ نبی اکرم صلی اللہ علیہ وسلم کے چچا ابوطالب کے بیٹے اور آپ کی چہیتی بیٹی فاطمہڤکے شوہر تھے۔ جس دن عثمان رضی اللہ عنہ کی شہادت ہوئی، اسی دن سن ۵۵ ہجری میں خلیفہ بنائےگئے۔ پھر وہ مدینہ سے کوفہ چلے گئے اور وہیں سنہ ۴۰ ہجری میں عبدالرحمن بن ملجم نامی خارجی نے ان کو شہید کردیا۔ اس وقت ان کی عمر ترسٹھ سال تھی۔ اس طرح ان کا دور خلافت چار سال نوماہ دس دن بنتا ہے۔ ان کی فضیلت کے بیان میں بہت ساری صحیح حدیثیں آئی ہیں۔ ان میں سے ایک یہ ہے: سعدبن ابی وقاص رضی اللہ عنہ کہتے ہیں : «إِنَّ رَسُولَ اللَّهِ صلی اللہ علیہ وسلم خَرَجَ إِلَی تَبُوکَ وَاسْتَخْلَفَ علیا، فَقَالَ: أَتُخَلِّفُنِي فِي الصِّبْيَانِ وَالنِّسَاءِ؟قَالَ: أَلا تَرْضَی أَنْ تَکُونَ مِنِّي بِمَنْزِلَةِ هَارُونَ مِنْ مُوسَی إِلا أَنَّهُ لَيْسَ نَبِيٌّ بَعْدِي». (صحیح البخاری: ۴۴۱۶، وصحیح مسلم: ۲۴۰۴/۳۱) \"جب رسول اللہ صلی اللہ علیہ وسلم اپنے صحابہ کے ساتھ جنگ تبوک کے لیے نکلے تو علی رضی اللہ عنہ کو گھر پر چھوڑ دیا، تاکہ وہ عورتوں اور بچوں کی دیکھ بھال کر سکیں، تو علی رضی اللہ عنہ نےکہا:اے اللہ کے رسول! آپ مجھے بچوں اورعورتوں کے پاس چھوڑ رہے ہیں؟ (مجھے جہاد پر نہیں لے جارہے ہیں؟) اس پرآپ نے فرمایا: اے علی! کیا تم اس بات سے خوش نہیں کہ تمھارا درجہ میرے نزدیک وہی ہو جو ہارون علیہ السلام کا درجہ موسیٰ علیہ السلام کے نزدیک تھا۔ لیکن میرے بعد اب کوئی نبی نہیں آئے گا\"۔\n§رواۃحدیث صحابہ کرام رضی اللہ عنہم کی تعداد:\nاس سے پہلے یہ بات بتائی جا چکی ہے کہ نبی اکرم صلی اللہ علیہ وسلم کی وفات کے وقت صحابہ کی تعداد تقریباً ایک لاکھ بیس ہزار تھی۔تیرہ ہزار سے زائد صحابہ کی سوانح حیات آج بھی کتابوں میں پائی جاتی ہیں، جن میں ایک ہزار سے زائد وہ صحابہ ہیں،جنھوں نےرسول اللہ صلی اللہ علیہ وسلم سےاحادیث نقل کی ہیں۔ امام بقی بن مخلد (۲۷۶ھ) کی مسندمیں ایک ہزار سے زائد صحابہ کی احادیث پائی جاتی ہیں۔ جن کےناموں کااوران کی روایت کردہ احادیث کی تعداد تذکرہ امام ابن حزم نے ایک رسالے میں کیاہے۔یہاں پرحدیث روایت کرنے والے صرف دس صحابہ کرام کا ذکر کیا جارہاہے:\n(۱)ابوہریرہ رضی اللہ عنہ :ان کی حدیثوں کی تعداد سب سے زیادہ ہے۔ جو (۵۳۷۴) بنتی ہیں۔ یہ اسلام قبول کرنے کے بعد یمن سے مدینہ آئےاورنبی اکرم صلی اللہ علیہ وسلم کی خدمت میں لگ گئے۔ان کا اصول تھا کہ وہ آپ کے دروازے پر بیٹھے رہتے تھے۔ جب آپ کہیں جاتے تو ساتھ ہو لیتے۔جو کچھ آپ فرماتے اسےیاد کرلیتے۔ایک بار انھوں نے آپ سے اپنی یاد داشت کی کمزوری کی شکایت کی، جس پرآپ نے ان کے لیے دعا کی۔ ابوہریرہ رضی اللہ عنہ کا کہنا ہے کہ پھر تو میں کبھی نہ بھولا۔\n(۲)عبداللہ بن عمربن خطاب رضی اللہ عنہما : ان کی حدیثوں کی تعداد (۲۶۳۰) ہے۔\n(۳) خادم رسول انس بن مالک رضی اللہ عنہ :ان کی حدیثوں کی تعداد (۲۲۳۶) ہے۔\n(۴)ام المومنین عائشہ بنت ابی بکر رضی اللہ عنہما : ان کی حدیثوں کی تعداد (۲۲۱۰) ہے۔\n(۵)عبد اللہ بن عباس رضی اللہ عنہما : ان کی حدیثوں کی تعداد (۱۶۶۰) ہے۔\n(۶)جابر بن عبد اللہ رضی اللہ عنہما : ان کی حدیثوں کی تعداد (۱۵۴۰) ہے۔\n(۷)ابو سعید خدری رضی اللہ عنہ : ان کی حدیثوں کی تعداد (۱۱۷۰) ہے۔\n(۸)عبد اللہ بن مسعود رضی اللہ عنہ : ان کی حدیثوں کی تعداد (۸۴۸) ہے۔\n(۹)عبد اللہ بن عمرو بن عاص رضی اللہ عنہما :ان کی حدیثوں کی تعداد (۷۰۰) ہے۔\n(۱۰)عمر بن خطاب رضی اللہ عنہ :ان کی حدیثوں کی تعداد ۵۳۷ہے۔\nاوپر جو تعداد بتائی گئی ہے یہ حافظ ابن حزم کی کتاب \"جوامع السیرة\"میں بقی بن مخلد کی مسند کی بنیاد پر بتائی گئی ہے۔انھوں نے خود یہ بھی کہہ دیا ہے کہ اگر کسی کو کچھ اور حدیثیں مل جائیں تو اس کو چاہیے کہ اس تعداد میں اضافہ کرلے۔اس لیے کہ یہ بھی ممکن ہے کہ اس تعداد میں کچھ اضافہ بھی ہوجائے۔ (دیکھیے: صفحہ۳۱۵)\nحدیثوں کی تعداد کےمتعلق یہاں یہ بات بھی سامنے رہے کہ اس وقت ہمارے پاس حدیث کی سیکڑوں کتابیں پائی جاتی ہیں، ان میں حدیثوں کی تعداد ساٹھ ہزار تک ہے۔ جو لگ بھگ تین لاکھ سندوں سے بیان کی گئی ہیں، بلکہ جرمنی کے ایک عالم، جس نے \"الاصابۃ\" کتاب کو مرتب کر کے کلکتہ سے شائع کیا تھا، وہ اس کے دیباچےمیں لکھتا ہے کہ حدیث بیان کرنے والےراویوں کی تعداد پانچ لاکھ تک ہے۔ جن کی سوانح حیات کو اسماء الرجال کی کتابوں میں محفوظ کر لیا گیا ہے۔ تاہم یہ ساٹھ سے سترّ ہزار حدیثیں سب صحیح نہیں ہیں۔اس عنوان پر تحقیق کرنے سے پتا چلتاہےکہ صحیح حدیثوں کی تعداد لگ بھگ پندرہ ہزار ہے،جو حدیث کی سیکڑوں کتابوں میں پھیلی ہوئی ہیں۔ اب ضرورت اس بات کی ہے ان صحیح حدیثوں کو ضعیف حدیثوں سے الگ کردیاجائے،کیونکہ ضعیف حدیثیں مذہب اسلام کا ستون نہیں بن سکتیں۔\nمیری کتاب ’’الجامع الکامل فی الحدیث الصحیح الشامل‘‘ اسی کی تکمیل ہے۔ یہاں ایک اہم بات کی طرف میں اشارہ کرنا چاہتاہوں: وہ یہ کہ سیدنا ابوہریرہ رضی اللہ عنہ کی طرف جو حدیثوں کی تعداد نسبت کی گئی (۵۳۷۴) وہ سندوں کے اعتبار سے ہے۔جیساکہ میں نے (۱۹۷۳م ) میں اپنے ایم اےکےمقالہ \"ابو ہریرہ فی ضوء مرویاتہ\" میں ثابت کیا اور یہ نتیجہ نکالاہے کہ ان کی تعداد دوہزار سے زیادہ نہیں ہے۔ جس کو اگر نبی اکرم صلی اللہ علیہ وسلم کے ساتھ رہنے والےایام میں تقسیم کردیں تو یومیہ دو حدیثیں بنتی ہیں۔ کیوں کہ سن ۷ میں واقع جنگ خیبر کے وقت ابوہریرہ رضی اللہ عنہ یمن سے مدینہ آئے اور نبی اکرم صلی اللہ علیہ وسلم کی وفات تک یہاں رہےجو ۱۱ھ؁ کو ہوئی۔ اس طرح تین سال جس کے کل تقریباً ایک ہزار دن بنتے ہیں۔\nاور پھر یہ کہ ان حدیثوں کے بہت سارے شواہد بھی پائے جاتے ہیں، جن سے ابوہریرہ کی سچائی ثابت ہوتی ہے۔ اورمستشرقین اور ان کے تلامذہ کا یہ دعویٰ غلط ثابت ہوتا ہےکہ ابوہریرہ رضی اللہ عنہ خود حدیثیں گھڑ لیاکرتے تھے۔ الحمد للہ جب سے میں نے اس نتیجے کا اعلان کیا اب تک علماء ومفکرین اپنی کتابوں اور دروس میں اس کوبیان کر رہے ہیں۔ سعودی عرب کے مشہور اسکالر ڈاکٹر محمد عبدہ کی کتاب ’’ابوہریرہ‘‘دیکھیں جس میں انھوں نے میرے اخذ کردہ نتیجے کو مکمل نقل کردیا ہے، البتہ اس میں کچھ غلطیاں ہوگئی ہیں اور مقالہ نگار اب تک اس نتیجے کو نقل کرتے جارہے ہیں۔ والحمدللہ علی توفیقہ۔\n§صحابی رسول زیدبن حارثہ کاتذکرہ:\nقرآن مجید میں صرف زید رضی اللہ عنہ کےنام کا تذکرہ آیاہے۔ وہ حقیقت میں عربی النسل تھے۔ ان کا پورا نام زید بن حارثہ بن شراحیل الکلبی تھا، مگر کم عمری میں ہی کسی نے انھیں اغوا کیااورغلام بناکر فروخت کردیا۔نبی اکرم صلی اللہ علیہ وسلم کی پہلی بیوی خدیجہڤنے انھیں خرید کر آپ کی خدمت میں حاضر کردیا۔ آپ نے انھیں آزاد کردیا اور اپنا منہ بولا بیٹا بنا لیا۔ جسے متبنی اور لے پالک کہتے ہیں۔ پھر آپ نے اپنی پھوپھی امامۃ بنت عبدالمطلب کی بیٹی زینب بنت جحش سے ان کا نکاح کردیا۔لیکن دونوں ایک ساتھ نباہ نہ سکے۔آپس میں اختلاف پیدا ہوگیا،حتی کہ دونوں میں طلاق کی نوبت آگئی، تو وحی کے ذریعےسے اللہ تعالی نے آپ کو متنبہ کردیا کہ یہ طلاق ہوکر رہے گی۔ پھر زینب سے آپ کا نکاح کردیاجائے گا،تاکہ دور جاہلیت کے اس رسم ورواج کا خاتمہ کیا جاسکے، جس میں منہ بولے بیٹے کی بیوی سے شادی کرنا ویسے ہی ممنوع تھا، جس طرح اپنے بیٹے کی بیوی سے۔ اگرچہ اللہ تعالیٰ نے آپ کو سب کچھ بتادیا تھا، پھر بھی آپ زید سے یہی کہتےرہےکہ اللہ تعالیٰ سے ڈرو اورطلاق مت دو۔ اس صورت حال کی وضاحت میں سورہ الاحزاب کی یہ آیتیں نازل ہوئیں : ﴿وَإِذۡ تَقُولُ لِلَّذِيٓ أَنۡعَمَ ٱللَّهُ عَلَيۡهِ وَأَنۡعَمۡتَ عَلَيۡهِ أَمۡسِكۡ عَلَيۡكَ زَوۡجَكَ وَٱتَّقِ ٱللَّهَ وَتُخۡفِي فِي نَفۡسِكَ مَا ٱللَّهُ مُبۡدِيهِ وَتَخۡشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخۡشَىٰهُۖ فَلَمَّا قَضَىٰ زَيۡدࣱ مِّنۡهَا وَطَرࣰ ا زَوَّجۡنَٰكَهَا لِكَيۡ لَا يَكُونَ عَلَى ٱلۡمُؤۡمِنِينَ حَرَجࣱ فِيٓ أَزۡوَٰجِ أَدۡعِيَآئِهِمۡ إِذَا قَضَوۡاْ مِنۡهُنَّ وَطَرࣰ اۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولࣰ ا﴾ [الأحزاب: ۳۷] \"(یاد کرو) جب کہ تم اس شخص سے کہہ رہے تھے جس پر اللہ نے بھی احسان کیا اور تم نے بھی کہ تم اپنی بیوی کو اپنے پاس روکے رکھو اور اللہ سے ڈرو اور اپنے دل میں وہ بات پوشیدہ رکھے تھے جسے اللہ افشا کرنے والا تھا اور تم لوگ (رسم) سے خوف کہا رہے تھے۔ حالانکہ اللہ اس کا زیادہ حقدار تھا کہ تم اس سے ڈرتے۔ پھرجب زید نے اس عورت سے اپنا رشتہ توڑ لیا تو ہم اسے تیرے نکاح میں دے دیا، تاکہ مسلمانوں پر اپنے منہ بولے بیٹے کی بیویوں کے متعلق کسی طرح کا حرج نہ رہے، جب کہ وہ ان سے اپنا رشتہ توڑلیں اوراللہ کا (یہ) حکم ہوکر ہی رہنے والا تھا\"۔\nام المومنین زینبڤبعد میں فخر کیا کرتی تھیں کہ میری شادی نبی اکرم صلی اللہ علیہ وسلم سے خود اللہ تعالیٰ نے کرائی ہے۔\n§عشرہ مبشرہ:\nوہ دس صحابہ کرام جن کو اللہ تعالیٰ نے دنیا میں ہی جنت کی بشارت دی انھیں عشرہ مبشرہ کہاجاتاہے، ان کے نام درج ذیل ہیں:\n(۱)ابوبکر صدیق رضی اللہ عنہ ( ۳اھ)\n(۲)عمر بن خطاب رضی اللہ عنہ (۲۳ھ )\n(۳)عثمان بن عفان رضی اللہ عنہ ( ۳۵ھ )\n(۴)علی بن ابی طالب رضی اللہ عنہ (۴۰ھ)\n(۵)زبير بن عوام رضی اللہ عنہ (۳۶ھ)\n(۶)طلحہ بن عبیداللہ رضی اللہ عنہ (۳۶ھ)\n(۷)عبدالرحمن بن عوف رضی اللہ عنہ (۳۲ھ)\n(۸)ابو عبیدہ بن جراح رضی اللہ عنہ (۸ا ھ)\n(۹)سعيد بن زیدعدوی رضی اللہ عنہ (۵۰ھ)\n(۱۰)سعد بن ابی وقاص رضی اللہ عنہ (۵۵ھ)\nیہ دس صحابی وہ ہیں جن کو نبی اکرم صلی اللہ علیہ وسلم نے ایک ہی حدیث میں جنت کی بشارت دے دی تھی۔ ان کے علاوہ اوربھی صحابی ہیں جن کو مختلف اوقات میں جنت کی بشارتیں دی گئیں۔\nصحابہ کی سوانح عمری (سیرواخلاق)پر لکھی گئی مشہور عربی کتابیں:\nیوں تو صحابہ کرام کی زندگی پر سیکڑوں کتابیں لکھی گئیں، تاہم یہاں صرف کچھ ہی کتابوں کا ذکر کیا جارہا ہے۔\n۱- معجم الصحابۃ:تالیف عبد الباقی بن قانع(۳۵۱ھ)\n۲- معرفہ الصحابۃ:تالیف ابونعيم اصفہانی (۴۳۰ھ)\n۳- الاستیعاب فی معرفۃ الأصحاب:تالیف ابن عبدالبر(۴۶۳ھ)\n۴- اسد الغابۃ فی معرفۃ الصحابۃ:تالیف عزالدین ابن الاثير (۶۲۰ھ)\n۵- تجرید اسماء الصحابۃ:تالیف شمس الدین ذہبی( ۷۴۸ھ)\n۶- الاصابۃ فی تمیيز الصحابۃ:تالیف ابن حجر عسقلانی(۸۵۲ھ)\nاس وقت کرۂ ارض پرصرف اسلام ہی ایسا دین ہے جس میں نبی اکرم صلی اللہ علیہ وسلم اور آپ کےصحابہ اور صحابہ کے شاگردوں (تابعین) اور تبع تابعین یعنی پانچویں صدی تک کے ان لوگوں کی سوانح عمریاں محفوظ کر لی گئی ہیں،جن کو رواة حدیث کہتے ہیں (یعنی حدیث بیان کرنے والے)،تاکہ حدیثوں کی جانچ پڑتال میں ان حدیثوں کے راویوں کی حیات واخلاقیات کا مطالعہ کیا جاسکے، کیونکہ حدیث کے صحیح یا ضعیف ہونے کی بنیاد انھیں راویوں پر ہے۔ اگر راوی سچا ہے،جس کو مصطلح الحدیث کی تعریف میں عادل اور ثقہ کہتے ہیں، تو حدیث صحیح ہوجائے گی اور اگر راوی سچا نہیں ہے، جس کو ضعیف کہتے ہیں تو حدیث ضعیف ہوجائے گی۔ لیکن حدیث کی تصحیح اور تضعیف میں اس کے علاوہ اور بھی کئی شرطوں کا اعتبار ہوتا ہے، جن کے تذکرہ کا یہ موقع نہیں ہے۔ تاہم صحیح حدیث کے لیے راوی کے سچا ہونے کی بڑی اہمیت ہے۔ راویوں کے ثقہ اور ضعیف ہونے کے بہت سارے اصول وضوابط ہیں۔ان میں اہم ترین اصول یہ ہے کہ ہر راوی کے متعلق دو باتوں کا زیادہ خیال رکھا جائے گا۔\n۱- ایک یہ کہ راوی اپنےعقیدےاوراخلاق و عمل میں نیک اور سچا مسلمان ہو، جو واجبات پرعمل کرتا ہو اور حرام سے بچتا ہویعنی اس کی زندگی اسلامی تعلیمات کے مطابق ہو۔\n۲- دوسری بات یہ کہ اس کا حافظہ مضبوط ہو، جویاد کرلےتو جب اس سے پوچھا جائے تو ویسے ہی بتائے جیسے اس نےاپنے استاد سے سنا ہے اور ان کو لکھ لیتا ہے تو یہ مزید بہتر ہے۔\nجب کسی راوی میں یہ دونوں خوبیاں پائی جائیں گی تو اس کو ثقہ راوی کہا جائے گا اور اس کی حدیث صحیح مانی جائے گی۔ جس میں یہ دونوں خوبیاں یا ان میں سے ایک نہ پائی جائے تو وہ راوی ضعیف کہلائےگااور اس کی حدیث ضعیف کہلائےگی۔حدیثوں کو پرکھنے کایہ ایک ایسا اصول ہے جو ہم ہر حدیث کی جانچ پڑتال میں استعمال کرتے ہیں۔ یہ اصول مسلمانوں کی تحقیق اور تلاش ہے۔ اس کااستعمال کسی اور مذہب میں کرنا ناممکن ہے۔واضح رہے کہ حدیث کی صحت کے لیےاس کے علاوہ کئی شرائط کاہونا بھی ضروری ہے۔مزیدمعلومات کے لیے میری عربی کتاب دراسات فی الجرح والتعدیل اور معجم مصطلحات الحدیث کامطالعہ کریں۔ ثانی الذکرکا اردو ترجمہ بھی دہلی سے شائع ہوچکاہے۔","",{}],[375,"§صحیفہ\nصحیفہ کے معنی ہیں مذہبی کتاب۔جس کی جمع صحف ہے،قرآن کریم میں یہی لفظ مختلف جگہوں پر آیا ہے جس کی تفصیل کچھ یوں ہے:\n§۱-ابراہیم علیہ السلام کے صحیفے:\nقرآن کریم میں دو جگہوں پر ابراہیم علیہ السلام کے صحیفے کا ذکر ہوا ہے:\n(۱)سورۃ النجم میں:﴿أَمۡ لَمۡ يُنَبَّأۡ بِمَا فِي صُحُفِ مُوسَىٰ وَإِبۡرَٰهِيمَ ٱلَّذِي وَفَّىٰٓ أَلَّا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰ وَأَن لَّيۡسَ لِلۡإِنسَٰنِ إِلَّا مَا سَعَىٰ وَأَنَّ سَعۡيَهُۥ سَوۡفَ يُرَىٰ ثُمَّ يُجۡزَىٰهُ ٱلۡجَزَآءَ ٱلۡأَوۡفَىٰ﴾ [النجم: ۳۶-۴۱] \"کیا جو باتیں موسیٰ کے صحیفوں میں ہیں ان کی اس کو خبر نہیں پہنچی۔ اور جو ابراہیم کےصحیفوں میں ہیں،جنھوں نے (طاعت ورسالت کا حق) پورا کیا: یہ کہ کوئی شخص دوسرے (کے گناہ) کا بوجھ نہیں اٹھائے گا اوریہ کہ انسان کو وہی ملتا ہے جس کی وہ کوشش کرتا ہے۔ یہ کہ اس کی کوشش دیکھی جائے گی۔ پھر اس کو اس کا پورا پورا بدلا دیا جائے گا\"۔\nسورہ النجم کی آیت: ۳۶ سے لےکر آخر تک پڑھنے سے ایسا لگتا ہے کہ جو کچھ قرآن میں بیان ہوا ہے وہ سب ابراہیم علیہ السلام کے صحیفے میں تھا۔ اصل صحیفے تو اب اس دنیا میں نہیں پائے جاتے، لیکن قرآن میں جو کچھ بیان ہوا ہے وہ گویا ان بنیادی تعلیمات کا خلاصہ ہے جن کا ذکران صحف میں آیا ہے اور وہی سارے نبیوں کی بھی اصل تعلیمات تھیں۔ لیکن کچھ لوگوں نے اس میں بگاڑ پیدا کرلیا اور عیسیٰ علیہ السلام کو اپنے نجات دہندہ بنا لیا۔ (دیکھیں: بائیل: لوقا: ۲: ۱۱)\n(۲)دوسرے سورۃ الاعلیٰ میں: ﴿إِنَّ هَٰذَا لَفِي ٱلصُّحُفِ ٱلۡأُولَىٰ صُحُفِ إِبۡرَٰهِيمَ وَمُوسَىٰ﴾ [الأعلی: ۱۸-۱۹] \"یہ بات پہلے صحیفوں میں ہے۔ یعنی ابراہیم اور موسیٰ کے صحیفوں میں\"۔\nاس سورہ میں انیس(۱۹) آیتیں ہیں اس سے یہ واضح ہوتا ہے کہ یہ ساری باتیں ابراہیم و موسیٰ علیہما السلام کے صحیفے میں بھی تھیں۔ عبد اللہ بن عباس رضی اللہ عنہما کا بھی یہی قول ہے۔(دیکھیں: تفسیر ابن ابی حاتم: ۱/ ۳۴۱۹)\n§۲-موسیٰ علیہ السلام کے صحیفے:\nقرآن کریم میں موسیٰ علیہ السلام کے صحیفے کا تذکرہ ابراہیم علیہ السلام کے صحیفے کے ساتھ ہوا ہے۔\nتورات سے مراد یہودونصاریٰ کی تاریخ میں مذکور بائبل کی مندرجہ ذیل پانچ کتابیں ہیں :\n(۱) پيدایش (GENESIS)\n(۲)خروج (EXODUS)\n(۳)احبار (LEVITICUS)\n(۴)تعداد (NUMBERS)\n(۵)استثنا(CEUTERONOMY)\nان پانچ کتابوں کو عہد عتیق (OLDTESTAMENT)کہا جاتا ہے۔ یہ پانچوں موسی علیہ السلام پر اللہ کی طرف سے نازل کی گئی ہیں،لیکن ان کتابوں کے مطالعے سے معلوم ہوتا ہے کہ یہ خیال مناسب نہیں ہے، کیونکہ ان میں بہت کچھ تحریف کردی گئی ہے۔ لیکن بہت سی باتیں اس میں ایسی ہیں جن کی تصدیق قرآن کریم سے ہوتی ہے۔ انھیں باتوں کو قرآن ہدیٰ اور نور قرار دیتا ہے۔ جیسا کہ قرآن میں ہے: ﴿إِنَّآ أَنزَلۡنَا ٱلتَّوۡرَىٰةَ فِيهَا هُدࣰ ى وَنُورࣱۚ يَحۡكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسۡلَمُواْ لِلَّذِينَ هَادُواْ وَٱلرَّبَّٰنِيُّونَ وَٱلۡأَحۡبَارُ بِمَا ٱسۡتُحۡفِظُواْ مِن كِتَٰبِ ٱللَّهِ وَكَانُواْ عَلَيۡهِ شُهَدَآءَۚ فَلَا تَخۡشَوُاْ ٱلنَّاسَ وَٱخۡشَوۡنِ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنࣰ ا قَلِيلࣰ اۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ وَكَتَبۡنَا عَلَيۡهِمۡ فِيهَآ أَنَّ ٱلنَّفۡسَ بِٱلنَّفۡسِ وَٱلۡعَيۡنَ بِٱلۡعَيۡنِ وَٱلۡأَنفَ بِٱلۡأَنفِ وَٱلۡأُذُنَ بِٱلۡأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلۡجُرُوحَ قِصَاصࣱۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةࣱ لَّهُۥۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ وَقَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبۡنِ مَرۡيَمَ مُصَدِّقࣰ ا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِۖ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَ فِيهِ هُدࣰ ى وَنُورࣱ وَمُصَدِّقࣰ ا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِ وَهُدࣰ ى وَمَوۡعِظَةࣰ لِّلۡمُتَّقِينَ﴾ [المائدة: ۴۴-۴۶] \"بےشک ہم نے توریت نازل فرمائی جس میں ہدایت اور روشنی ہے اسی کے مطابق انبیا جو(اللہ تعالیٰ کے) فرماں بردار تھے یہودیوں کو حکم دیتے رہے ہیں اور مشائخ اور علماءبھی کیوں کہ وہ کتاب اللہ تعالی کے نگہبان مقرر کیے گئے تھے اور اس پر گواہ تھے (یعنی حکم الہٰی کا یقین رکھتے تھے) تو تم لوگوں سے مت ڈرنا اور مجھ ہی سے ڈرتے رہنا اور میری آیتوں کے بدلے تھوڑی سی قیمت نہ لینا اور جو اللہ تعالی کے نازل فرمائے ہوے احکام کے مطابق حکم نہ دیں تو ایسے ہی لوگ کافر ہیں۔ اور ہم نے ان لوگوں کے لیے تورات میں یہ حکم لکھ دیا تھا کہ جان کے بدلے جان اور آنکھ کے بدلے آنکھ اور ناک کے بدلےناک اور کان کے بدلے کان اور دانت کے بدلےدانت اور سب زخموں کا اسی طرح بدلہ ہے، لیکن جو شخص بدلہ معاف کر دے وہ اس کے لیے کفارہ ہوگا اور جو اللہ تعالیٰ کے نازل فرمائے ہوے احکام کے مطابق حکم نہ دے تو ایسے ہی لوگ بےانصاف ہیں۔ ان نبیوں کے بعد انھی کے قدموں پر ہم نے عیسیٰ بن مریم کو بھیجا جو اپنے سے پہلے کی کتاب تورات کی تصدیق کرتے تھے اور ان کو انجیل عنایت کی جس میں ہدایت اور نور ہے اور تورات کی جو اس سے پہلی کتاب (ہے) تصدیق کرتی ہے اور پرہیزگاروں کو راہ بتاتی اور نصیحت کرتی ہے\"۔\nاسی طریقے سے موسیٰ علیہ السلام کے صحیفے کے کچھ حصہ کا ذکر قرآن کریم میں کیا گیا ہے: ﴿مِنۡ أَجۡلِ ذَٰلِكَ كَتَبۡنَا عَلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفۡسَۢا بِغَيۡرِ نَفۡسٍ أَوۡ فَسَادࣲ فِي ٱلۡأَرۡضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعࣰ ا وَمَنۡ أَحۡيَاهَا فَكَأَنَّمَآ أَحۡيَا ٱلنَّاسَ جَمِيعࣰ اۚ وَلَقَدۡ جَآءَتۡهُمۡ رُسُلُنَا بِٱلۡبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرࣰ ا مِّنۡهُم بَعۡدَ ذَٰلِكَ فِي ٱلۡأَرۡضِ لَمُسۡرِفُونَ﴾ [المائدة: ۳۲] \"اس قتل کی وجہ سے ہم نے بنی اسرائیل پر یہ حکم نازل کیا کہ جو شخص کسی کو(ناحق)قتل کرے گا (یعنی) بغیر اس کے کہ جان کا بدلہ لیا جائے یا ملک میں خرابی پیدا کرنے کی سزا دی جائے اُس نے گویا تمام لوگوں کو قتل کیا اور جو اس کی زندگانی کا موجب ہوا تو گویا تمام لوگوں کی زندگانی کا موجب ہوا اور ان لوگوں کے پاس ہمارے رسول روشن دلیلیں لا چکے ہیں پھر اس کے بعد بھی ان سے بہت سے لوگ ملک میں حدِ اعتدال سے نکل جاتے ہیں\"۔\nاورفرمایا: ﴿وَكَتَبۡنَا عَلَيۡهِمۡ فِيهَآ أَنَّ ٱلنَّفۡسَ بِٱلنَّفۡسِ وَٱلۡعَيۡنَ بِٱلۡعَيۡنِ وَٱلۡأَنفَ بِٱلۡأَنفِ وَٱلۡأُذُنَ بِٱلۡأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلۡجُرُوحَ قِصَاصࣱۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةࣱ لَّهُۥۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ﴾ [المائدة: ۴۵] \"اور ہم نے ان لوگوں کے لیے تورات میں یہ حکم لکھ دیا تھا کہ جان کے بدلے جان اورآنکھ کے بدلے آنکھ اور ناک کے بدلے ناک اور کان کے بدلے کان اور دانت کے بدلے دانت اور سب زخموں کا اسی طرح بدلہ ہے لیکن جو شخص بدلہ معاف کر دے وہ اس کے لیے کفارہ ہوگا اورجو اللہ تعالیٰ کے نازل فرمائے ہوے احکام کے مطابق حکم نہ دے تو ایسے ہی لوگ بےانصاف ہیں\"۔\nنیزفرمایا: ﴿وَكَتَبۡنَا لَهُۥ فِي ٱلۡأَلۡوَاحِ مِن كُلِّ شَيۡءࣲ مَّوۡعِظَةࣰ وَتَفۡصِيلࣰ ا لِّكُلِّ شَيۡءࣲ فَخُذۡهَا بِقُوَّةࣲ وَأۡمُرۡ قَوۡمَكَ يَأۡخُذُواْ بِأَحۡسَنِهَاۚ سَأُوْرِيكُمۡ دَارَ ٱلۡفَٰسِقِينَ﴾ [الأعراف: ۱۴۵] اور ہم نے (تورات) کی تختیوں میں ان کے لیے ہر قسم کی نصیحت اور ہر چیز کی تفصیل لکھ دی، پھر (ارشاد فرمایا کہ) اسے زور سے پکڑے رہو اور اپنی قوم سے بھی کہہ دو کہ ان باتوں کو جو اس میں (درج ہیں اور) بہت بہتر ہیں پکڑے رہیں۔ میں عنقریب تم کو نافرمان لوگوں کا گھر دکھاؤں گا\"۔\nبلکہ ایک جگہ تو قرآن میں تعجب ظاہر کرتے ہوے کہا گیا ہے:﴿وَكَيۡفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوۡرَىٰةُ فِيهَا حُكۡمُ ٱللَّهِ ثُمَّ يَتَوَلَّوۡنَ مِنۢ بَعۡدِ ذَٰلِكَۚ وَمَآ أُوْلَٰٓئِكَ بِٱلۡمُؤۡمِنِينَ﴾ [المائدة: ۴۳] \"اور یہ تم سے (اپنے مقدمات) کیونکر فیصل کراتے ہیں جب کہ خود ان کے پاس تورات (موجود) ہے جس میں اللہ تعالی کا حکم (لکھا ہوا) ہے (یہ اسے جانتے ہیں) پھر اس کے بعد اس سے پھر جاتے ہیں اور یہ لوگ ایمان ہی نہیں رکھتے\"۔\n۳-قرآن کے لیے بھی صحف لفظ کا استعمال کیا گیا ہے : ﴿فِي صُحُفࣲ مُّكَرَّمَةࣲ مَّرۡفُوعَةࣲ مُّطَهَّرَةِۭ بِأَيۡدِي سَفَرَةࣲ كِرَامِۭ بَرَرَةࣲ‏﴾ [عبس: ۱۳-۱۶] \"قابل احترام صحیفوں (اوراق) میں(لکھا ہوا)۔جو بلند مقام پر رکھے ہوے (اور)پاک ہیں۔(ایسے)لکھنے والوں کے ہاتھوں میں\"۔\nاورفرمایا: ﴿رَسُولࣱ مِّنَ ٱللَّهِ يَتۡلُواْ صُحُفࣰ ا مُّطَهَّرَةࣰ‏﴾ [البینة: ۲] \"اللہ تعالیٰ کا ایک رسول جو پاک آسمانی صحیفے پڑھے\"۔\n۴-نامۂ اعمال کے لیے بھی صحف لفظ کا استعمال کیا گیا ہے : ﴿وَإِذَا ٱلصُّحُفُ نُشِرَتۡ﴾ [التکویر: ۱۰] \"اور جب(اعمال کے) دفتر کھولے جائیں گے\"۔\n۵-نجات نامہ کے لیے بھی صحف لفظ کا استعمال کیا گیا ہے: ﴿بَلۡ يُرِيدُ كُلُّ ٱمۡرِيࣲٕ مِّنۡهُمۡ أَن يُؤۡتَىٰ صُحُفࣰ ا مُّنَشَّرَةࣰ‏﴾ [المدثر: ۵۲] \"بل کہ ان میں سے ہر ایک شخص چاہتا ہے کہ اسے کھلی ہوئی کتابیں دی جائیں \"۔\nاصل یہ ہےکہ ان میں سےہرشخص یہ چاہتا ہے کہ اس کے پاس کھلی ہوئی کتاب آئے\"۔","",{}],[376,"§صدقۃ الفطر\nدیکھیے: زکاۃ الفطر","",{}],[377,"§صدقہ\nدیکھیے: زکاۃ","",{}],[378,"§صفا\nصفا ایک پہاڑی کا نام ہے جو کعبہ سے تقریباً سو(۱۰۰) میٹر کی دوری پر ہے۔ اس کا ذکر قرآن میں ایک بارہواہے: ﴿إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِۖ فَمَنۡ حَجَّ ٱلۡبَيۡتَ أَوِ ٱعۡتَمَرَ فَلَا جُنَاحَ عَلَيۡهِ أَن يَطَّوَّفَ بِهِمَاۚ وَمَن تَطَوَّعَ خَيۡرࣰ ا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ﴾ [البقرة: ۱۵۸] \"بےشک(کوہ) صفا اور مروہ اللہ تعالی کی نشانیوں میں سے ہیں،تو جو شخص خانہٴ کعبہ کا حج یا عمرہ کرے اس پر کچھ گناہ نہیں کہ دونوں کا طواف کرے۔ (بلکہ طواف ایک قسم کا نیک کام ہے) اور جو کوئی نیک کام کرے تو اللہ تعالی قدر شناس اور دانا ہے\"۔\nصفا و مروہ یہ وہی دو پہاڑیاں ہیں جن کے درمیان حج و عمرہ کرنے والےسعی کرتے ہیں۔ تاکہ ہاجرہ علیہا السلام کے اس واقعہ کی یاد تازہ ہو جب انھوں نے پانی کے لیے ان دو پہاڑیوں کے بیچ دوڑ لگائی تھی۔ اس کی پوری تفصیل لفظ: مروہ کے تحت بیان کی گئی ہے۔\nصفا کی اس پہاڑی سے خود نبی اکرم صلی اللہ علیہ وسلم کا بھی گہرا تعلق رہا ہے جب آپ کو یہ حکم دیا گیا تھا: ﴿وَأَنذِرۡ عَشِيرَتَكَ ٱلۡأَقۡرَبِينَ﴾ [الشعراء: ۲۱۴] \"اور اپنے قریب کے رشتہ داروں کو ڈر سنا دو\"۔\nعبداللہ بن عباس رضی اللہ عنہما کہتےہیں: «لَمَّا نَزَلَتْ:﴿وَأَنذِرۡ عَشِيرَتَكَ ٱلۡأَقۡرَبِينَ﴾ [الشعراء: ۲۱۴] صَعِدَ النَّبِيُّ صلی اللہ علیہ وسلم عَلَی الصَّفَا فَجَعَلَ يُنَادِي: يَا بَنِي فِهْرٍ يَا بَنِي عَدِيٍّ، لِبُطُونِ قُرَيْشٍ، حَتَّی اجْتَمَعُوا، فَجَعَلَ الرَّجُلُ إِذَا لَمْ يَسْتَطِعْ أَنْ يَخْرُجَ أَرْسَلَ رَسُولا لِيَنْظُرَ مَا هُوَ، فَجَاءَ أَبُو لَهَبٍ وَقُرَيْشٌ، فَقَالَ: أَرَأَيْتَکُمْ لَوْ أَخْبَرْتُکُمْ أَنَّ خَيْلا بِالْوَادِي تُرِيدُ أَنْ تُغِيرَ عليکُمْ أَکُنْتُمْ مُصَدِّقِيَّ؟ قَالُوا: نَعَمْ مَا جَرَّبْنَا عليکَ إِلا صِدْقًا، قَالَ: فَإِنِّي نَذِيرٌ لَکُمْ بَيْنَ يَدَيْ عَذَابٍ شَدِيدٍ، فَقَالَ أَبُو لَهَبٍ: تَبًّا لَکَ سَائِرَ الْيَوْمِ أَلِهَذَا جَمَعْتَنَا؟ فَنَزَلَتْ:﴿تَبَّتۡ يَدَآ أَبِي لَهَبࣲ وَتَبَّ مَآ أَغۡنَىٰ عَنۡهُ مَالُهُۥ وَمَا كَسَبَ سَيَصۡلَىٰ نَارࣰ ا ذَاتَ لَهَبࣲ وَٱمۡرَأَتُهُۥ حَمَّالَةَ ٱلۡحَطَبِ فِي جِيدِهَا حَبۡلࣱ مِّن مَّسَدِۭ﴾ [المسد: ۱-۵]». (صحیح البخاری: ۴۷۷۰، وصحیح مسلم: ۲۰۸/۳۵۵) جب یہ آیت نازل ہوئی: \"اور آپ اپنے خاندانی قرابت داروں کو ڈرائیے\"تو رسول اللہ صلی اللہ علیہ وسلم صفا پہاڑی پر چڑھ گئے اور پکارنے لگے: اےبنی فہر! اور اے بنی عدی! اور قریش کے دوسرے خاندان والو! اس آواز پرسب جمع ہوگئے اگر کوئی کسی وجہ سے نہ آسکا تو اس نے اپنا کوئی نمایندہ بھیج دیا، تاکہ معلوم ہو کہ کیا بات ہے۔ابولہب قریش کے دوسرے لوگوں کےساتھ مجمع میں تھا۔رسول اللہ صلی اللہ علیہ وسلم نےانھیں خطاب کرکے فرمایا: تمھارا کیا خیال ہے، اگر میں تم سے کہوں کہ وادی میں (پہاڑی کے پیچھے ) ایک لشکر ہے اور وہ تم پرحملہ کرنا چاہتا ہے، تو کیا تم میری بات سچ مانوگے؟ سب نے کہا کہ ہاں، ہم آپ کی تصدیق کریں گے،ہم نے ہمیشہ آپ کو سچا ہی پایا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ پھرسنو، میں تمھیں اس سخت عذاب سے ڈراتا ہوں جو بالکل سامنے ہے۔ اس پر ابولہب بولا: تجھ پر سارے دن تباہی نازل ہو، کیا تو نے ہمیں اسی لیے اکٹھا کیا تھا۔ اسی واقعہ پر یہ آیت نازل ہوئی: ابولہب کے دونوں ہاتھ ٹوٹ گئے اور وہ برباد ہوگیا، نہ اس کا مال اس کے کام آیا اور نہ اس کی کمائی ہی اس کے کام آئی۔ وہ جلد بھڑکتی ہوئی آگ میں داخل ہو گا اور اس کی جورو بھی جو ایندھن سر پر اٹھائے پھرتی ہے۔ اس کے گلے میں مونج کی رسّی ہوگی\"۔\nصفا نام کی یہ وہی پہاڑی ہے جس پر فتح مکہ کے بعد نبی اکرم صلی اللہ علیہ وسلم نے کھڑے ہوکر یہ اعلان کیا تھا: «مَنْ دَخَلَ دَارَ أَبِي سُفْيَانَ فَهُوَ آمِنٌ، وَمَنْ أَلْقَی السِّلاحَ فَهُوَ آمِنٌ، وَمَنْ أَغْلَقَ بَابَهُ فَهُوَ آمِنٌ». (صحیح مسلم: ۱۷۸۰/۸۶ بروایت ابوہریرہ رضی اللہ عنہ ) \" جو ابو سفیان کے گھر میں داخل ہو گیا اسے امان ہے۔ جس نے ہتھیار ڈال دیے اسے امان ہے، جس نے اپنا دروازہ بند کر لیا اسے بھی امان ہے \"۔","",{}],[379,"§صلاة\nعربی زبان میں نمازکو صلاة کہتے ہیں۔قرآن کریم میں صلاة(نماز) لفظ کا استعمال ایک سے زیادہ معنوں میں ہوا ہے۔ ان میں سے کچھ خاص معنوں کا تذکرہ یہاں کیا جارہا ہے:\n۱- ایک تو وہ اہم عبادت اور اسلام کا رکن جسے صلاة(نماز) کہتے ہیں۔ قرآن کریم میں جہاں کہیں بھی صلاة(نماز) قائم کرنے اور زکاۃ دینے کا حکم آیا ہے، وہاں صلاة(نماز) سے مراد یہی عبادت ہے۔\nجیسےقرآن مجیدمیں آیا ہے:﴿ٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡغَيۡبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ﴾ [البقرة: ۳] \"جو غیب پر ایمان رکھتے ہیں،صلاة (نماز) قائم کرتے ہیں اور جوکچھ ہم نے انھیں دیا ہے اس میں سے خرچ کرتے ہیں\"۔\nقرآن کریم میں سب سے زیادہ جس عبادت کا ذکر آیا ہے وہ یہی صلاة(نماز) ہے جوہر دن پانچ بار مقرر وقت پرادا کی جاتی ہے:﴿فَإِذَا قَضَيۡتُمُ ٱلصَّلَوٰةَ فَٱذۡكُرُواْ ٱللَّهَ قِيَٰمࣰ ا وَقُعُودࣰ ا وَعَلَىٰ جُنُوبِكُمۡۚ فَإِذَا ٱطۡمَأۡنَنتُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَۚ إِنَّ ٱلصَّلَوٰةَ كَانَتۡ عَلَى ٱلۡمُؤۡمِنِينَ كِتَٰبࣰ ا مَّوۡقُوتࣰ ا﴾ [النساء: ۱۰۳] \"جب تم صلاۃ (خوف) سے فارغ ہوجاؤ تواللہ کو کھڑے، بیٹھے اور پہلو کے بل (لیٹنے پر) اللہ کو یاد کرتے رہو اور جب تم (لڑائی سے) مطمئن ہو جاؤ تو صلاۃ کو (اپنے اصل وقت پر) ادا کیا کرو۔ بےشک ایمان والوں پر مقررہ وقت میں صلاة (نماز) پڑھنا فرض کر دیا گیا ہے\"۔\nاس کی ايک اہم خصوصیت يہ ہے کہ دیگر عبادات تو وحی کے ذریعے جبرئیل علیہ السلام لے کر آتے تھے،ليکن صلاة (نماز) کو معراج کی رات اللہ تعالیٰ نےنبی اکرم صلی اللہ علیہ وسلم اپنے پاس بلوا کر آپ پر اور آپ کے امتیوں پر خود فرض کیا، جس میں اللہ تعالیٰ اورآپ کے درميان کوئی اور نہیں تھا،جس کا ذکر بہت تفصيل سے صحيح بخاری اور صحيح مسلم میں آيا ہے۔انس بن مالک رضی اللہ عنہ کہتے ہیں: «کَانَ أَبُوذَرٍّ يُحَدِّثُ أَنَّ رَسُولَ اللَّهِ صلی اللہ علیہ وسلم قَالَ: فُرِجَ عَنْ سَقْفِ بَيْتِي وَأَنَا بِمَکَّةَ، فَنَزَلَ جِبْرِيلُ عليه السلام فَفَرَجَ صَدْرِي، ثُمَّ غَسَلَهُ بِمَاءِ زَمْزَمَ ثُمَّ جَاءَ بِطَسْتٍ مِنْ ذَهَبٍ مُمْتَلِئٍ حِکْمَةً وَإِيمَانًا، فَأَفْرَغَهُ فِي صَدْرِي ثُمَّ أَطْبَقَهُ، ثُمَّ أَخَذَ بِيَدِي فَعَرَجَ بِي إِلَی السَّمَاءِ الدُّنْيَا، فَلَمَّا جِئْتُ إِلَی السَّمَاءِ الدُّنْيَا قَالَ جِبْرِيلُ لِخَازِنِ السَّمَاءِ: افْتَحْ، قَالَ: مَنْ هَذَا؟ قَالَ: هَذَا جِبْرِيلُ قَالَ: هَلْ مَعَکَ أَحَدٌ؟ قَالَ: نَعَمْ مَعِي مُحَمَّدٌ صلی اللہ علیہ وسلم، فَقَالَ: أُرْسِلَ إِلَيْهِ؟ قَالَ: نَعَمْ فَلَمَّا فَتَحَ عَلَوْنَا السَّمَاءَ الدُّنْيَا، فَإِذَا رَجُلٌ قَاعِدٌ عَلَی يَمِينِهِ أَسْوِدَةٌ وَعَلَی يَسَارِهِ أَسْوِدَةٌ، إِذَا نَظَرَ قِبَلَ يَمِينِهِ ضَحِکَ وَإِذَا نَظَرَ قِبَلَ يَسَارِهِ بَکَی، فَقَالَ: مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالابْنِ الصَّالِحِ، قُلْتُ لِجِبْرِيلَ: مَنْ هَذَا؟ قَالَ: هَذَا آدَمُ وَهَذِهِ الأَسْوِدَةُ عَنْ يَمِينِهِ وَشِمَالِهِ نَسَمُ بَنِيهِ، فَأَهْلُ الْيَمِينِ مِنْهُمْ أَهْلُ الْجَنَّةِ وَالأَسْوِدَةُ الَّتِي عَنْ شِمَالِهِ أَهْلُ النَّارِ، فَإِذَا نَظَرَ عَنْ يَمِينِهِ ضَحِکَ وَإِذَا نَظَرَ قِبَلَ شِمَالِهِ بَکَی، حَتَّی عَرَجَ بِي إِلَی السَّمَاءِ الثَّانِيَةِ، فَقَالَ لِخَازِنِهَا: افْتَحْ فَقَالَ: لَهُ خَازِنِهَا مِثْلَ مَا قَالَ الأَوَّلُ، فَفَتَحَ، قَالَ أَنَسٌ: فَذَکَرَ أَنَّهُ وَجَدَ فِي السَّمَوَاتِ آدَمَ وَإِدْرِيسَ وَمُوسَی وَعِيسَی وَإِبْرَاهِيمَ صَلَوَاتُ اللَّهِ عليهِمْ، وَلَمْ يُثْبِتْ کَيْفَ مَنَازِلُهُمْ غَيْرَ أَنَّهُ ذَکَرَ أَنَّهُ وَجَدَ آدَمَ فِي السَّمَاءِ الدُّنْيَا وَإِبْرَاهِيمَ فِي السَّمَاءِ السَّادِسَةِ، قَالَ: أَنَسٌ فَلَمَّا مَرَّ جِبْرِيلُ بِالنَّبِيِّ صلی اللہ علیہ وسلم بِإِدْرِيسَ قَالَ: مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالأَخِ الصَّالِحِ، فَقُلْتُ: مَنْ هَذَا؟ قَالَ: هَذَا إِدْرِيسُ، ثُمَّ مَرَرْتُ بِمُوسَی فَقَالَ: مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالأَخِ الصَّالِحِ، قُلْتُ: مَنْ هَذَا؟ قَالَ: هَذَا مُوسَی، ثُمَّ مَرَرْتُ بِعِيسَی فَقَالَ: مَرْحَبًا بِالأَخِ الصَّالِحِ وَالنَّبِيِّ الصَّالِحِ، قُلْتُ: مَنْ هَذَا؟ قَالَ: هَذَا عِيسَی، ثُمَّ مَرَرْتُ بِإِبْرَاهِيمَ فَقَالَ: مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالابْنِ الصَّالِحِ، قُلْتُ: مَنْ هَذَا؟ قَالَ: هَذَا إِبْرَاهِيمُ عليه السلام، قَالَ ابْنُ شِهَابٍ: فَأَخْبَرَنِي ابْنُ حَزْمٍ أَنَّ ابْنَ عَبَّاسٍ وَأَبَا حَبَّةَ الأَنْصَارِيَّ کَانَا يَقُولانِ: قَالَ النَّبِيُّ صلی اللہ علیہ وسلم : ثُمَّ عُرِجَ بِي حَتَّی ظَهَرْتُ لِمُسْتَوَی أَسْمَعُ فِيهِ صَرِيفَ الأَقْلامِ، قَالَ ابْنُ حَزْمٍ وَأَنَسُ بْنُ مَالِکٍ: قَالَ النَّبِيُّ صلی اللہ علیہ وسلم : فَفَرَضَ اللَّهُ عَزَّ وَجَلَّ عَلَی أُمَّتِي خَمْسِينَ صَلاةً، فَرَجَعْتُ بِذَلِکَ حَتَّی مَرَرْتُ عَلَی مُوسَی فَقَالَ: مَا فَرَضَ اللَّهُ لَکَ عَلَی أُمَّتِکَ؟ قُلْتُ: فَرَضَ خَمْسِينَ صَلاةً قَالَ: فَارْجِعْ إِلَی رَبِّکَ فَإِنَّ أُمَّتَکَ لا تُطِيقُ ذَلِکَ، فَرَاجَعْتُ فَوَضَعَ شَطْرَهَا فَرَجَعْتُ إِلَی مُوسَی قُلْتُ: وَضَعَ شَطْرَهَا فَقَالَ: رَاجِعْ رَبَّکَ فَإِنَّ أُمَّتَکَ لا تُطِيقُ فَرَاجَعْتُ فَوَضَعَ شَطْرَهَا فَرَجَعْتُ إِلَيْهِ فَقَالَ: ارْجِعْ إِلَی رَبِّکَ فَإِنَّ أُمَّتَکَ لا تُطِيقُ ذَلِکَ فَرَاجَعْتُهُ، فَقَالَ: هِيَ خَمْسٌ وَهِيَ خَمْسُونَ لا يُبَدَّلُ الْقَوْلُ لَدَيَّ، فَرَجَعْتُ إِلَی مُوسَی فَقَالَ: رَاجِعْ رَبَّکَ فَقُلْتُ: اسْتَحْيَيْتُ مِنْ رَبِّي ثُمَّ انْطَلَقَ بِي حَتَّی انْتَهَی بِي إِلَی سِدْرَةِ الْمُنْتَهَی وَغَشِيَهَا أَلْوَانٌ لا أَدْرِي مَا هِيَ ثُمَّ أُدْخِلْتُ الْجَنَّةَ فَإِذَا فِيهَا حَبَايِلُ اللُّؤْلُؤِ وَإِذَا تُرَابُهَا الْمِسْکُ». (صحیح البخاری: ۳۴۹وصحیح مسلم: ۱۶۳/۲۶۳)\nابوذرغفاری رضی اللہ عنہ کہتےہیں کہ رسول اللہ صلی اللہ علیہ وسلم نےفرمایا: \"میرے گھر کی چھت کھول دی گئی، اس وقت میں مکہ میں تھا۔ پھر جبرئیل اترے اور انھوں نے میرا سینہ چاک کیا۔ پھر اسے زمزم کےپانی سے دھویا۔ پھر ایک سونے کا طشت لائے جو حکمت اور ایمان سے بھرا ہوا تھا۔ اس کو میرے سینے میں رکھ دیا، پھر سینے کو جوڑ دیا، پھر میرا ہاتھ پکڑا اور مجھے آسمان کی طرف لے کر چلے۔ جب میں پہلے آسمان پر پہنچا تو جبرئیل نے آسمان کے داروغہ سے کہا: کھولو۔ اس نے پوچھا: آپ کون ہیں؟ جواب دیا کہ جبرئیل، پھر انھوں نے پوچھا: کیا آپ کے ساتھ کوئی اور بھی ہے؟ جواب دیا: ہاں میرے ساتھ محمد صلی اللہ علیہ وسلم ہیں۔ انھوں نے پوچھا:کیا ان کے بلانے کے لیے آپ کو بھیجا گیا تھا؟ کہا: جی ہاں! پھر جب انھوں نے دروازہ کھولا تو ہم پہلے آسمان پر چڑھ گئے، وہاں ہم نے ایک شخص کو بیٹھے ہوے دیکھا۔ ان کے داہنی طرف کچھ لوگوں کے جھنڈ تھے اور کچھ جھنڈ بائیں طرف تھے۔ جب وہ اپنی داہنی طرف دیکھتے تو مسکراتے اور جب بائیں طرف نظر کرتے تو روتے۔ انھوں نے مجھے دیکھ کر فرمایا : آو اچھے آئے ہو، صالح نبی اور صالح بیٹے! میں نے جبرئیل سے پوچھا: یہ کون ہیں؟ انھوں نے کہا: یہ آدم ہیں اور ان کے دائیں بائیں جو جھنڈ ہیں یہ ان کی اولاد کی روحیں ہیں، جو جھنڈ دائیں طرف ہیں وہ جنتی ہیں اور بائیں طرف کے جھنڈ جہنمی روحیں ہیں۔ اس لیے جب وہ اپنے دائیں طرف دیکھتے ہیں تو خوشی سے مسکراتے ہیں اور جب بائیں طرف دیکھتے ہیں تو (رنج سے) روتے ہیں۔ پھر جبرئیل مجھے لے کر دوسرے آسمان تک پہنچے اور اس کے داروغہ سے کہا: کھولو۔اس آسمان کے داروغہ نے بھی پہلے داروغہ کی طرح پوچھا پھر کھول دیا۔ انس رضی اللہ عنہ نے کہا: ابو ذر رضی اللہ عنہ نے ذکر کیاکہ آپ یعنی نبی اکرم صلی اللہ علیہ وسلم نے آسمان پرآدم، ادریس موسیٰ، عیسیٰ اور ابراہیم کو موجود پایا۔ اور ابوذر رضی اللہ عنہ نے ہر ایک کا ٹھکانا نہیں بیان کیا۔ البتہ اتنا بیان کیا نبی اکرم صلی اللہ علیہ وسلم نے آدم کو پہلے آسمان پر پایا اورابراہیم کو چھٹے آسمان پر۔انس رضی اللہ عنہ نے بیان کیا: جب جبرئیل نبی کریم کے ساتھ ادریس کے پاس سے گزرے تو انھوں نے فرمایا: آؤ اچھے آئے ہو صالح نبی اور صالح بھائی۔ میں نے پوچھا: یہ کون ہیں؟ جواب دیا: یہ ادریس ہیں۔پھرموسیٰ تک پہنچا انھوں نے فرمایا: آؤ اچھے آئے ہو صالح نبی اور صالح بھائی۔ میں نے پوچھا: یہ کون ہیں؟ جبرئیل نے بتایا کہ یہ موسیٰ ہیں۔ پھر میں عیسیٰ تک پہنچا، انھوں نے کہا:آؤ اچھے آئے ہو صالح نبی اور صالح بھائی۔ میں نے پوچھا: یہ کون ہیں؟ جبرئیل نے بتایا کہ یہ عیسیٰ ہیں۔ پھر میں ابراہیم تک پہنچا انھوں نے فرمایا: آؤ اچھے آئےہو صالح نبی اور صالح بیٹے۔ میں نے پوچھا: یہ کون ہیں؟ جبرئیل نے بتایا کہ یہ ابراہیم ہیں۔ابن شہاب نے کہا: مجھے ابو بکر بن حزم نےخبر دی کہ عبد اللہ بن عباس رضی اللہ عنہما اورابوحبۃ انصاری کہا کرتے تھے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: پھر مجھے جبرئیل لے کر چڑھے، اب میں اس بلند مقام تک پہنچ گیا جہاں میں نے قلم کی آواز سنی (جو لکھنے والے فرشتوں کی قلموں کی آواز تھی)۔پس اللہ تعالیٰ نے میری امت پر پچا س وقت کی نمازیں فرض کیں۔ میں یہ حکم لے کر واپس لوٹا۔ جب موسیٰ تک پہنچا تو انھوں نے پوچھا: آپ کی امت پر اللہ نے کیا فرض کیا ہے؟ میں نے کہا: پچاس وقت کی نمازیں فرض کی ہیں۔ انھوں نے فرمایا: آپ واپس اپنے رب کی بارگاہ میں جائیے۔ کیوں کہ آپ کی امت اتنی نمازوں کو ادا کرنے کی طاقت نہیں رکھتی ہے۔ میں واپس بارگاہ رب العزت میں گیا تو اللہ نے اس میں سے ایک حصہ کم کر دیا،پھر موسیٰ کے پاس آیا اور کہا کہ ایک حصہ کم کر دیا گیا ہے، انھوں نے کہا کہ دوبارہ جائیے کیوں کہ آپ کی امت میں اس کے برداشت نہ کر سکے گی۔پھر میں باربار آیا گیا، پس اللہ تعالیٰ نے فرمایا کہ یہ نمازیں (عمل میں) پانچ ہیں اور (ثواب میں) پچاس (کے برابر ) ہیں۔ میری بات بدلی نہیں جاتی۔اب میں موسیٰ کے پاس آیا تو انھوں نے پھر کہا: اپنے رب العزت کے پاس جاؤ۔لیکن میں نے کہا: مجھے اب اپنے رب سے شرم آتی ہے۔پھرجبرئیل مجھے سدرۃ المنتہیٰ تک لے گئے جسے کئی طرح کے رنگوں نے ڈھانک رکھا تھا۔ جن کے متعلق مجھے معلوم نہیں ہوا کہ وہ کیا ہیں۔ اس کے بعد مجھے جنت میں لے جایا گیا، میں نے دیکھا کہ اس میں موتیوں کے ہار ہیں اور اس کی مٹی مشک کی ہے\"۔ (مزید معلومات کے لیے دیکھیں:سورہ الاسراء)\nصلاة(نماز) کے سوا دوسری عبادات کے لیے کچھ قواعدمتعین کیےگئے ہیں۔جیسے زکاۃ کے لیے ایک مخصوص نصاب تک مال کا ہونا لازم ہے۔اگر اس نصاب تک مال نہ ہو تو زکاۃلازم نہیں۔ اسی طرح حج کےلیےاتنا مال ہونا ضروری ہے کہ آدمی مکہ کا سفر کرسکے۔اگر اتنا مال نہ ہوتو حج فرض نہیں، لیکن صلاة (نماز)کی اہمیت یہ ہے کہ یہ ایک ایسی عبادت ہے جو ہر مسلمان مرد اورعورت پر فرض ہے چاہے وہ کسی حالت میں ہوں تاکہ ایک مسلمان کا دل اللہ کی یاد سے کبھی بھی غافل نہ ہو۔ صبح بھی اللہ کی یاد سے ہو اور دوپہر اور رات بھی۔ حقیقت میں صلاة(نماز) ہی تو وہ عبادت ہے جو اسلام اور کفر (غیر اسلام) کے درمیان فرق کو واضح کرتی ہے جس کی شہادت صحیح احادیث سے ہوتی ہے:\n۱- جابر رضی اللہ عنہ سے روایت ہےکہ میں نے نبی اکرم صلی اللہ علیہ وسلم سےکہتے سناہے: «إِنَّ بَيْنَ الرَّجُلِ وَبَيْنَ الشِّرْکِ وَالْکُفْرِ تَرْکَ الصَّلاةِ». (صحیح مسلم: ۱۳۴/۸۲) \"صلاة(نماز) کا چھوڑنا کفر اور شرک کے درمیان علامت ہے\"۔\n۲-بریدہ رضی اللہ عنہ سے صحیح حدیث میں آیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «الْعَهْدُ الَّذِي بَيْنَنَا وَبَيْنَهُمْ الصَّلاَةُ، فَمَنْ تَرَکَهَا فَقَدْ کَفَرَ». (سنن الترمذی: ۲۶۲۱،سنن النسائی:۴۶۴، سنن ابن ماجہ: ۱۰۷۹، مسنداحمد:۵/۳۴۶، ۳۵۵، امام ترمذی کہتےہیں: یہ حدیث حسن صحیح غریب ہے) \"ہمارے اور ان کے درمیان جوحد فاصل ہے وہ نماز ہے۔ تو جس نے صلاة(نماز) چھوڑ دی وہ کافر ہوگیا\"۔\n۳- ابوہریرہ رضی اللہ عنہ کا قول ہے:«کَانَ أَصْحَابُ رَسُولِ اللهِ صلی اللہ علیہ وسلم لاَ يَرَوْنَ شَيْئًا مِنْ الأَعْمَالِ تَرْکُهُ کُفْرًا غَيْرَ الصِّلاَةِ». (مستدرک الحاکم ۱/۷۰، حاکم نے اس کی تصحیح کی ہے اور ذہبی کا قول ہے کہ اس کی سند صالح ہے) \" صحابۂ رسول کسی عمل کو چھوڑنا کفر نہیں سمجھتے تھے سوائے صلاة(نماز)کے\"۔\n۴- عبداللہ بن شقیق عقیلی کہتے ہیں:«کَانَ أَصْحَابُ مُحَمَّدٍ صلی اللہ علیہ وسلم لاَ يَرَوْنَ شَيْئًا مِنَ الأَعْمَالِ تَرکه کُفْرٌ غَيْرَ الصَّلاَةِ». \"صحابہ کرام( رضی اللہ عنہم )صلاۃ کے سواکسی عمل کے چھوڑدینے کو کفرنہیں سمجھتے تھے\"۔ (سنن الترمذی : ۲۶۲۲، دیکھیے: تعظیم قدر الصلاۃ للمروزی، بحث تارک الصلاۃ)\nان احادیث سے صلاة (نماز) کی اہمیت اور خصوصیت ثابت ہوتی ہے جو ایک مسلم اور غیرمسلم میں فرق کو ظاہر کرتی ہے کیونکہ مسلم کا معنیٰ ہی اللہ کے احکامات کی پیروی کرنے والا ہے۔ اور اللہ کے احکام کو یاد کرنے والی چیز یہی صلاة(نماز) ہے جو صبح سے لے کر رات میں سونے تک پانچ بار ادا کی جاتی ہے۔اب ایسا شخص جو پانچ مرتبہ صلاة(نماز) پڑھتا ہو وہ زندگی کے کسی لمحہ میں کیسے اللہ کی نافرمانی کرسکتا ہے۔اسی کی طرف قرآن کریم میں اشارہ کیا گیا ہے: ﴿ٱتۡلُ مَآ أُوحِيَ إِلَيۡكَ مِنَ ٱلۡكِتَٰبِ وَأَقِمِ ٱلصَّلَوٰةَۖ إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۗ وَلَذِكۡرُ ٱللَّهِ أَكۡبَرُۗ وَٱللَّهُ يَعۡلَمُ مَا تَصۡنَعُونَ﴾ [العنکبوت: ۴۵] \"یقیناًصلاة(نماز) بے حیائی اوربرائی سے روکتی ہے اور اللہ کو یاد کرنا بہت بڑی چیز ہے اور اللہ وہ سب کچھ جانتا ہے جو تم کرتے ہو\"۔\nصلاة(نماز)پڑھ کر بھی اگرتم بد اعمالیوں سے بازنہیں آسکتے تو تم جان لو کہ اللہ تمھاری بد اعمالیوں سے اچھی طرح واقف ہے۔\nکسی بھی مذہب میں عبادت کا مقصد اس سےزیادہ واضح طور پر نہیں بتایا گیا ہے۔ اب یہ عبادت کرنے والے پر ہے کہ عبادت سے اچھی طرح فائدہ اٹھاتا ہے یا نہیں۔ اللہ ایمان والوں کو خبردار کرتے ہوے کہتا ہے:﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ وَمَن يَتَّبِعۡ خُطُوَٰتِ ٱلشَّيۡطَٰنِ فَإِنَّهُۥ يَأۡمُرُ بِٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۚ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدࣰ ا وَلَٰكِنَّ ٱللَّهَ يُزَكِّي مَن يَشَآءُۗ وَٱللَّهُ سَمِيعٌ عَلِيمࣱ‏﴾ [النور: ۲۱] \"اے ایمان والو! شیطان کی راہ پر نہ چلو اور جو کوئی شیطان کی راہ پر چلے گا تو وہ اسے بیہودگی اور برائیوں ہی کا حکم دیتا ہے\"۔\nصلاة(نماز) پڑھنے سے انسان کو بہت سے روحانی فوائدحاصل ہوتے ہیں جن میں سے کچھ اہم کا ذکر یہاں کیا جارہا ہے:\n(۱)صلاة(نماز) انسان کی کامیابی کا ضامن ہے:﴿قَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ هُمۡ فِي صَلَاتِهِمۡ خَٰشِعُونَ﴾ [المؤمنون: ۱-۲]\"بے شک ایمان والے کامیاب ہوگیے جو اپنی صلاة(نماز)میں خشوع اختیارکرتے ہیں\"۔\nیعنی جو صلاة(نماز) میں اللہ سے ڈرتے ہیں وہ اس طرح سے صلاة(نماز) پڑھتے ہیں جیسے اللہ ان کو دیکھ رہا ہے۔ایسی حالت میں انسان اپنے پورے جسم اورذہن کے ساتھ اس کی عبادت کرتا ہے، اس کے ذہن میں اللہ کے سوا کوئی اور بات نہیں آسکتی۔\n(۲)صلاة(نماز) کے ذریعےسے مدد مانگنے کا بھی حکم دیا گیا ہے:﴿وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلۡخَٰشِعِينَ﴾ [البقرة: ۴۵] \"صبراور صلاة(نماز) سےمدد لو۔بے شک صلاة(نماز) بہت شاق ہے لیکن ان لوگوں کے لیے نہیں جو اللہ سے ڈرتے ہیں\"۔\nاورفرمایا: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ﴾ [البقرة: ۱۵۳] \"اے ایمان والو! صبر اور صلاة(نماز)سے مدد لو۔ بےشک اللہ صبر کرنے والوں کے ساتھ ہے\"۔\n(۳)صلاة(نماز) کے ذریعےانسان اپنے رب کے نزدیک ہوجاتا ہے۔ایسی حالت میں وہ اپنے دل کوبڑےاحتیاط کےساتھ اللہ سے جوڑ سکتا ہےاور جس کا دل اللہ سے جڑجائے وہ دنیا کی تکالیف کی پروا نہیں کرتا۔اسی کی طرف قرآن نےکچھ اس طرح اشارہ کیا ہے:﴿أَلَآ إِنَّ أَوۡلِيَآءَ ٱللَّهِ لَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ﴾ [یونس: ۶۲] \"سنو! اللہ کے دوستوں کو نہ تو کوئی خوف ہوگا اور نہ وہ غمگین ہوں گے\"۔\n(۴)صلاة(نماز) ہی وہ عبادت ہے جس کے بارے میں آپ صلی اللہ علیہ وسلم نے فرمایا تھا:«جُعِلَ قُرَّةُ عَيْنِي فِي الصَّلاةِ». (مسند احمد: ۱۲۲۹۳بروایت انس رضی اللہ عنہ ) \"میری آنکھوں کی ٹھنڈک صلاة (نماز) میں ہے\"۔\n§صلاةاداکرنے کا طریقۂ نبوی:\nنبی اکرم صلی اللہ علیہ وسلم نے فرمایا:\"صلاة(نماز) ایسے ادا کرو جس طرح مجھےادا کرتے دیکھ رہے ہو\"۔ (صحیح البخاری: ۶۳۱ و صحیح مسلم: ۶۷۴)\nآپ صلاة(نماز) کیسے پڑھتے تھے؟ اب اس پر غور کرتے ہیں :\n(۱)نبی اکرم صلی اللہ علیہ وسلم مدینہ میں سترہ ماہ تک بیت المقدس کی طرف منہ کرکے صلاة(نماز) پڑھتے رہے۔ لیکن آپ یہ چاہتے تھے کہ بیت اللہ (کعبہ) کی طرف منہ کرکے صلاة(نماز) پڑھیں۔ اس پر یہ آیت نازل ہوئی: ﴿قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ فِي ٱلسَّمَآءِۖ فَلَنُوَلِّيَنَّكَ قِبۡلَةࣰ تَرۡضَىٰهَاۚ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥۗ وَإِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ﴾ [البقرة: ۱۴۴] \"ہم تمھارے چہرے کوآسمان کی طرف گردش کرتے دیکھ رہے ہیں، تو ہم تمھیں اس قبلے کی طرف پھیردیں گے جسے تم پسند کرتے ہو پس تم اپنا منہ مسجد حرام (کعبہ) کی طرف پھیر لو اور جہاں کہیں بھی ہو اسی کی طرف صلاة(نماز) میں اپنا منہ کرلو\"۔\n(۲)کعبہ کی طرف منہ کرنے کے بعد اللہ اکبر کہہ کر دونوں ہاتھوں کو اپنے کندھوں کے برابر لے جائیں اور پھردونوں ہاتھوں کو سینے پر اس طرح باندھیں کہ داہنا ہاتھ بائیں ہاتھ کے اوپر ہو۔(دیکھیے: صحیح ابن خزیمہ:۴۷۹)\n(۳)پھردعاےاستفتاح(تکبیر تحریمہ کے بعد، سورہ فاتحہ پڑھنے سے پہلے، صلاةشروع کرنے کی دعاپڑھیں)۔ احادیث میں متعدد دعاوں کا ذکر ہے،ان میں سے ایک یہ ہے: «اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ کَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنْ الْخَطَايَا کَمَا يُنَقَّی الثَّوْبُ الأَبْيَضُ مِنْ الدَّنَسِ، اللَّهُمَّ اغْسِلْ خَطَايَايَ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ». (صحیح البخاری: ۷۴۴،صحیح مسلم: ۵۹۸/۱۴۷)\nایک دوسری دعا جو علی رضی اللہ عنہ نے بیان کی ہے اسے بھی پڑھ سکتے ہیں۔ اسی طرح عمر رضی اللہ عنہ سے بھی ایک دعا منقول ہے،جس میں کہا گیا ہے: «سُبْحَانَکَ اللَّهُمَّ وَبِحَمْدِکَ وَتَبَارَکَ اسْمُکَ وَتَعَالَی جَدُّکَ وَلاَ إِلَهَ غَيْرُکَ»\n(۴)پھر سورہ فاتحہ پڑھیں،سورہ فاتحہ کے بغیرصلاة (نماز) نہیں ہوتی۔ (صحیح البخاری:۷۵۶ وصحیح مسلم:۳۹۴)\nاس کے بعد قرآن کی کوئی بھی سورہ پڑھناسنت ہے۔\n(۵)پھر اللہ اکبر کہتے ہوے دونوں ہاتھوں کو اپنے کندھوں تک لے جائیں۔ پھر رکوع میں چلے جائیں اور پورے اطمینان کے ساتھ رکوع میں رہیں۔ (صحیح البخاری:۷۰۷)اور یہ دعا پڑھیں:«سُبْحَانَکَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِکَ اللَّهُمَّ اغْفِرْ لِي».(صحیح البخاری:۴۹۶۸ وصحیح مسلم:۴۸۴)\nیہ دعا بھی پڑھی جاسکتی ہے: «سُبْحَانَ رَبِّيَ الْعَظِيمِ»(صحیح مسلم: ۷۷۲)\n(۶)پھر«سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ رَبَّنَا لَکَ الْحَمْدُ»کہتے ہوے اپنے دونوں ہاتھوں کو کندھوں تک لے جائیں اور پوری طرح سے سیدھے کھڑے ہوجائیں اور کھڑے کھڑے یہ دعا پڑھیں:«اللَّهُمَّ رَبَّنَا لَکَ الْحَمْدُ مِلْءُ السَّمَاوَاتِ وَمِلْءُ الأَرْضِ وَمَا بَيْنَهُمَا وَمِلْءُ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ أَهْلَ الثَّنَاءِ وَالْمَجْدِ لامَانِعَ لِمَا أَعْطَيْتَ وَلا مُعْطِيَ لِمَا مَنَعْتَ وَلا يَنْفَعُ ذَا الْجَدِّ مِنْکَ الْجَدُّ». (صحیح مسلم: ۴۷۸)\nیہ دعا بھی پڑھ سکتے ہیں:«رَبَّنَا وَلَکَ الحَمْدُ، حَمْدًا کَثِيرًا طَيِّبًا مَبَارَکًا فَيهِ»(صحیح البخاری: ۷۹۹)\n(۷)پھر اللہ اکبر کہتے ہوے سجدے میں چلے جائیں اور پورے اطمینان کے ساتھ سجدہ کریں۔ وہ اس طرح کہ دونوں ہاتھوں کی انگلیاں سامنے کی طرف ہوں۔ بازو اور بغل میں اتنا فاصلہ ہوکہ چھوٹا جانور جیسے بلّی وغیرہ اس کے اندر سےگزر جائے۔ (صحیح مسلم: ۴۹۷)\nسجدے میں جسم کے سات اعضا زمین سے لگے ہوں: پیشانی ناک کے ساتھ،دونوں ہاتھ،دونوں گھٹنے اور دونوں پاؤں۔ (مسلم :۴۹۱) اور سجدے میں یہ دعا پڑھیں :«سُبْحَانَ رَبِّيَ الأَعْلَی» (صحیح مسلم: ۷۷۲)\nيا يہ دعا پڑھیں:«اللَّهُمَّ اغْفِرْ لِي ذَنْبِي کُلَّهُ دِقَّهُ وَجِلَّهُ وَأَوَّلَهُ وَآخِرَهُ وَعَلانِيَتَهُ وَسِرَّهُ». (صحیح مسلم: ۴۸۳)\n(۸)پھر اللہ اکبر کہتے ہوے سجدے سے اٹھیں اور اطمینان سے بیٹھ جائیں اور یہ دعا پڑھیں: «اللَّهُمَّ اغْفِرْ لِي اللَّهُمَّ اغْفِرْ لِي» (سنن ابن ماجہ:۸۹۷ وحاکم: ۲۷۱:۱)\nیہ دعابھی صحیح اور ثابت ہے:«اللَّهُمَّ اغْفِرْلِي وارْحَمْنِي، واهْدِنِي، وعَافِنِي، وارْزُقْنِي» (سنن ابی داود:۸۵۰، سنن الترمذی: ۲۸۴)\n(۹)پھر اللہ اکبر کہتے ہوے سجدے میں چلے جائیں اور اطمینان سے سجدہ کریں اور وہ دعائیں پڑھیں جن کا ذکر پیچھے کیا جا چکا ہے۔ ان کے علاوہ اور بھی کوئی دعا پڑھنی چاہیں تو پڑھ سکتے ہیں۔\n(۱۰)پھر اللہ اکبر کہتے ہوے سجدے سےاٹھیں اور بیٹھ جائیں۔اطمینان سے بیٹھنےکے بعد دونوں ہاتھوں کو زمین پر ٹکا کر کھڑے ہوجائیں اور دوبارہ دائیں ہاتھ کو بائیں ہاتھ پر باندھ کر سینہ پر رکھ لیں۔ اس طرح آپ کی ایک رکعت صلاة (نماز) پوری ہوگئی۔\n(۱۱)دوسری رکعت اسی طرح ادا کرنے کے بعد (پہلے)تشہد میں زمین پر ٹیک لگا کر اس طرح بیٹھیں کہ بائیں پیرکو زمین پر بچھالیں اور اسی پر بیٹھ جائیں اور دائیں پیر کو کھڑا کرکے اس کی انگلیاں قبلہ کی طرف موڑ لیں (اگر آسانی سے مڑ جائیں)۔ تشہد اخیر میں اس طرح بیٹھیں کہ دایاں پیر تو اسی طرح کھڑا رہے اور بایاں پیر دائیں پیر کی پنڈلی سے باہر نکل کر قبلہ رو ہوجائے۔ (صحیح البخاری: حدیث ابو حمید الساعدی، حدیث: ۸۲۸) دونوں ہاتھوں کو گھٹنے پر رکھ لیں اور دائیں ہاتھ کی وہ انگلی جو انگوٹھے سے ملی ہوتی ہے،اس کوکھڑا کرلیں اور بائیں ہاتھ سے بائیں گھٹنے کو مضبوطی سے پکڑلیں اور تشہد کی یہ دعا پڑھیں : «التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلامُ عَلَيْکَ أَيُّهَا النَّبِيُّ، وَرَحْمَةُ اللَّهِ وَبَرَکَاتُهُ، السَّلامُ عَلَيْنَا وَعَلَی عِبَادِ اللَّهِ الصَّالِحِينَ، فَإِنَّکُمْ إِذَا قُلْتُمُوهَا أَصَابَتْ کُلَّ عَبْدٍ لِلَّهِ صَالِحٍ فِي السَّمَاءِ وَالأَرْضِ، أَشْهَدُ أَنْ لا إِلَهَ إِلا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ». \"تمام آداب بندگی، تمام عبادتیں اور تمام بہترین تعریفیں اللہ کے لئے ہیں،آپ پر سلام ہو اے نبی اور اللہ کی رحمتیں اور اس کی برکتیں آپ پرہوں،ہم پرسلام اور اللہ کے تمام صالح بندوں پر سلام۔ جب تم یہ کہو گے تو تمھارا سلام آسمان وزمین میں جہاں کوئی اللہ کا نیک بندہ ہے اس کو پہنچ جائے گا، میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی حقیقی معبود نہیں اور گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم اس کے بندے اور رسول ہیں \"۔(صحیح البخاری:۸۳۱ وصحیح مسلم:۴۰۲)\nتشہدکےاخیر میں التحیات کےبعد درود بھی ملائیں جو اس طرح ہے: «اللَّهُمَّ صَلِّ عَلَی مُحَمَّدٍ وَعَلَی آلِ مُحَمَّدٍ کَمَا صَلَّيْتَ عَلَی إِبْرَاهِيمَ وَعَلَی آلِ إِبْرَاهِيمَ إِنَّکَ حَمِيدٌ مَجِيدٌ اللَّهُمَّ بَارِکْ عَلَی مُحَمَّدٍ وَعَلَی آلِ مُحَمَّدٍ کَمَا بَارَکْتَ عَلَی إِبْرَاهِيمَ وَعَلَی آلِ إِبْرَاهِيمَ إِنَّکَ حَمِيدٌ مَجِيدٌ». \"اے اللہ! اپنی رحمت نازل فرما محمد صلی اللہ علیہ وسلم پر اور آل محمد پر جیسا کہ تو نے اپنی رحمت نازل فرمائی ابراہیم پر اور آل ابراہیم پر۔ بیشک تو بڑی خوبیوں والا اور بزرگی والا ہے۔ اے اللہ! برکت نازل فرما محمد پر اور آل محمد پر جیسا کہ تو نے برکت نازل فرمائی ابراہیم پر اور آل ابراہیم پر۔ بیشک تو بڑی خوبیوں والا اور بڑی عظمت والا ہے\"۔(صحیح البخاری: ۳۳۷۰)\nیہ عبداللہ بن مسعود رضی اللہ عنہ سےمروی مشہور تشہدکی دعا ہے۔ اسی طرح کی دیگر دعائیں دوسرے صحابہ سے بھی مذکور ہیں۔\n(۱۲)پھر جو بھی دوسری دعا پڑھنا چاہیں پڑھیں۔ سلام پھیرنے سے پہلے چار چیزوں سے اللہ کی پناہ مانگیں: «اللَّهُمَّ إِنِّي أَعُوذُ بِکَ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ عَذَابِ النَّارِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ وَمِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ». (صحیح البخاری:۱۳۷۷ وصحیح مسلم:۵۸۸) \"اے اللہ! میں قبر کے عذاب سے تیری پناہ چاہتا ہوں اور جہنم کے عذاب سے اور زندگی اور موت کی آزمائشوں سے اور کانے دجال کے فتنے سے تیری پناہ چاہتا ہوں\"۔\n«اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا کَثِيرًا، وَلا يَغْفِرُ الذُّنُوبَ إِلا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِکَ، وَارْحَمْنِي، إِنَّک أَنْتَ الْغَفُورُ الرَّحِيمُ». (صحیح البخاری:۸۳۴ وصحیح مسلم:۲۷۰۵) \"اے اللہ! میں نے اپنی جان پر (گناہ کر کے ) بہت زیادہ ظلم کیا،گناہوں کو تیرے سوا کوئی دوسرا معاف کرنے والا نہیں۔ مجھے اپنے پاس سے بھر پور مغفرت عطا فرما اور مجھ پر رحم کر کہ غفور(مغفرت کرنے والا) اوررحیم (رحم کرنے والا)بیشک تو ہی ہے\"۔\n(۱۳) پھر دائیں اور بائیں دونوں طرف سلام پھیریں اورسلام پھیرتے ہوےالسلام علیکم ورحمۃ اللہ کہیں۔ اس طرح دورکعت صلاة(نماز) مکمل ہوگئی۔\nیہ آپ صلی اللہ علیہ وسلم کا صلاة(نماز) پڑھنے کا وہ طریقہ ہے جو صحیح احادیث میں بیان کیا گیا ہے اس کوبیان کرنے والوں میں ابوہریرہ ابن عمر، وائل بن حجر، علی، عبادہ ابن ثابت، ابو حمید ساعدی و غیرہ صحابہ ہیں بلکہ ابوحمیدساعدی نے تو یہ کہہ کر صلاة(نماز) پڑھی کہ میں آپ صلی اللہ علیہ وسلم کی طرح صلاة(نماز) پڑھ کر دکھاتا ہوں اورپھرانهوں نے اس طرح صلاة(نماز) پڑھی، وہاں دس (۱۰)دیگر صحابی بھی موجود تھے۔ (مزید معلومات کے لیے میری کتاب المنة الکبری فی شرح وتخریج السنن الصغری للبیهقیدیکھیے: ۴۸۹:۱)\n۲- صلاة کا دوسرا معنیٰ عام عبادت (پرستش) ہے جو کسی طرح بھی کی جائے۔ اس بارے میں ہم یہ کہہ سکتے ہیں کہ پہلےانبیا کے تعلق سے جولفظ صلاة(نماز) کا استعمال ہوا ہے اس کاعام معنیٰ عبادت ہی ہے۔کیونکہ جس طرح آپ صلی اللہ علیہ وسلم نےصلاة(نماز) پڑھی ہے اس طرح دوسرے انبیا نے نہیں پڑھی ہوگی۔ یا یہ کہا جاسکتا ہے کہ ہم اس کے بارے کچھ زیادہ نہیں جانتے۔ قرآن میں جن انبیا کے تعلق سے صلاة(نماز) کا ذکر ہوا ہے ان میں سے کچھ یہ ہیں:\nابرہیم علیہ السلام:\n﴿رَبِّ ٱجۡعَلۡنِي مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِيۚ رَبَّنَا وَتَقَبَّلۡ دُعَآءِ﴾ [إبراهیم: ۴۰] \"اے رب! مجھے صلاة (نماز) قائم کرنے والا بنادے۔ اور میری اولاد کو بھی\"۔\nاسماعیل علیہ السلام:\n﴿وَكَانَ يَأۡمُرُ أَهۡلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرۡضِيࣰّ ا﴾ [مریم: ۵۵] \"وہ اپنے گھر والوں کو صلاة (نماز)اور زکاۃ کا حکم دیتا تھا اور وہ اپنے رب کے یہاں پسند کیا ہوا بندہ تھا\"۔\nموسیٰ علیہ السلام:\n﴿إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدۡنِي وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِيٓ﴾ [طه: ۱۴] \"یقیناًمیں اللہ ہوں۔ میرےسوا کوئی حقیقی معبود نہیں۔پس تو میری عبادت کر اور میری یاد کے لیے صلاة(نماز)قائم کر\"۔\nعیسیٰ علیہ السلام:\n﴿ٱشۡدُدۡ بِهِۦٓ أَزۡرِي﴾ [طه: ۳۱] \"مجھے برکت والا بنایا، جہاں بھی رہوں اور مجھے صلاة(نماز) اور زکاۃ کی تاکید کی جب تک میں زندہ رہوں\"۔\nلقمان علیہ السلام نے بھی اپنی اولاد کو صلاة(نماز) پڑھنے کی تاکید کی:﴿يَٰبُنَيَّ أَقِمِ ٱلصَّلَوٰةَ وَأۡمُرۡ بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَآ أَصَابَكَۖ إِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ﴾ [لقمان: ۱۷] \"اے میرے بیٹے! صلاة(نماز) قائم کر اور اچھائی کا حکم دے اور برائی سے روک\"۔\nتورات سےبھی معلوم ہوتا ہے کہ انبیا کو صلاة (نماز) کا حکم دیا گیا۔ جیسے ابرہیم (پیدایش:۱۷:۲۰) یعقوب۔ (پیدایش:۳۱ـ۲۶: ۳۲)، موسیٰ(گنتی،۲:۱۱) وغیرہ کو صلاة(نماز) کا حکم دیا گیا تھا۔\nلیکن بائبل کے ہندی ترجمے میں صلاة (نماز) کا ترجمہ دعا سے کیا گیا ہے۔\n(۳)صلاة کے ایک معنیٰ دعا کےبھی ہیں۔ جیسے اللہ نےآپ صلی اللہ علیہ وسلم کو یہ حکم دیا :﴿خُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةࣰ تُطَهِّرُهُمۡ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيۡهِمۡۖ إِنَّ صَلَوٰتَكَ سَكَنࣱ لَّهُمۡۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ﴾ [التوبة: ۱۰۳] \"ان کے لیے دعا کریں۔ بےشک آپ کی دعا ان کے لیے موجب اطمینان ہے\"۔\n(۴)صلاة کا ایک معنی سلام (درود) بھیجنا بھی ہے۔ جیسے قرآن کریم میں آیا ہے: ﴿إِنَّ ٱللَّهَ وَمَلَٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِيِّۚ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ صَلُّواْ عَلَيۡهِ وَسَلِّمُواْ تَسۡلِيمًا﴾ [الأحزاب: ۵۶] \"اللہ اور اس کے فرشتے آپپر سلام بھیجتے ہیں۔ اے ایمان والو! تم بھی ان پردرود بھیجو اور خوب سلام بھیجتے رہو\"۔\n(۵)صلاة کا ایک معنی معبود کی رحمتیں بھی ہیں۔ قرآن کریم میں ایک جگہ پر آیا ہے:﴿أُوْلَٰٓئِكَ عَلَيۡهِمۡ صَلَوَٰتࣱ مِّن رَّبِّهِمۡ وَرَحۡمَةࣱۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُهۡتَدُونَ﴾ [البقرة: ۱۵۷] \"یہی لوگ ہیں جن کے اوپر رب کی خاص رحمتیں ہیں اور اس کی رحم دلی بھی اور یہی لوگ ہیں جو سیدھے راہ پر ہیں\"۔\n(۶)صلاة کا ایک معنیٰ عبادت گاہ بھی ہے۔قرآن مجیدمیں چار قوموں کے لیے چار طرح کی عبادت گاہوں کا ذکر ہےاور ان میں سے ایک صلاۃبھی ہے جو یہودیوں کی عبادت گاہ ہے: ﴿دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضࣲ لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعࣱ وَصَلَوَٰتࣱ وَمَسَٰجِدُ يُذۡكَرُ فِيهَا ٱسۡمُ ٱللَّهِ كَثِيرࣰ اۗ وَلَيَنصُرَنَّ﴾ [الحج: ۴۰] \"اگر اللہ لوگوں کو آپس میں ایک دوسرے کے ذریعے نہ ہٹاتا رہتاتوعبادت خانے، گرجا گھر، یہودیوں کا معبد (صلاۃ) اور مسلمانوں کی مساجد، جن میں اللہ کا نام زیادہ لیا جاتا ہے سب گرادیے جاتے\"۔\nحقیقت میں صلاۃ لفظ نمازکے معنیٰ میں سب سے زیادہ استعمال ہوا ہے۔\nفرض نمازیں تو وہی ہیں جو ہرروز پانچ بار پڑھی جاتی ہیں۔ باقی نمازیں یہ ہیں :\n§صلاةِتہجد:\nیہ رات کے تیسرے پہر میں پڑھی جاتی ہے۔ کیونکہ اس وقت اللہ تعالیٰ آسمانِ دنیا کی طرف اترتا اورفرماتاہے: کوئی ہے جو مجھ سے دعا کرے میں اس کی دعا کو قبول کروں۔ کوئی ہے جو مجھ سے مانگے اور میں اس کو دوں۔ کوئی ہے جو مجھ سے معافی مانگے اور میں اس کو معاف کردوں۔ (صحیح البخاری:۱۱۴۵ وصحیح مسلم:۷۸۵)\nاس لیےاللہ کے نیک بندے تہجد کی صلاةکو بہت اہم سمجھتے ہیں۔نبی اکرم صلی اللہ علیہ وسلم تو صلاةتہجداس طرح پڑھتے تھے کہ کھڑے کھڑےآپ کے پاؤں میں ورم آجاتا تھا۔ جب آپ کو کہاجاتا کہ اللہ نے تو آپ کے سارے گناہ معاف کردیے ہیں پھر آپ اتنی مشقت کیوں کرتے ہیں؟ تو آپ کہتے:\"کیا میں اللہ کا شکرگزار اوراحسان مند بندہ نہ بنوں\"۔\n§صلاةِعيدین:\nیعنی دو عید کی نماز۔ ایک کو عیدا لفطر کہتے ہیں، جوماہِ رمضان کے روزوں کے مکمل ہونے کے بعد اداکی جاتی ہے۔ دوسری کو عیدالاضحیٰ کہتے ہیں، جو دسویں ذوالحجہ کو اداکی جاتی ہے۔ اس دن حاجی عرفات سےمنی آکر قربانی کرتے ہیں۔عیدالاضحیٰ میں عیدکی نمازکے بعد قربانی کی جاتی ہے۔یہ حقیقت میں ابرہیم علیہ السلام کی اس قربانی کی یاد ہے جب انھوں نے اللہ تعالیٰ کے حکم سے اپنے اکلوتے بیٹے اسماعیل کو قربان کرنا چاہا تو اللہ تعالیٰ نے ان سے خوش ہوکر بیٹے کی جگہ پر ایک بھیڑ کو قربان کرا دیا، جس کا تذکرہ قرآن کریم میں اس طرح آیا ہے:﴿فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعۡيَ قَالَ يَٰبُنَيَّ إِنِّيٓ أَرَىٰ فِي ٱلۡمَنَامِ أَنِّيٓ أَذۡبَحُكَ فَٱنظُرۡ مَاذَا تَرَىٰۚ قَالَ يَٰٓأَبَتِ ٱفۡعَلۡ مَا تُؤۡمَرُۖ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ فَلَمَّآ أَسۡلَمَا وَتَلَّهُۥ لِلۡجَبِينِ وَنَٰدَيۡنَٰهُ أَن يَٰٓإِبۡرَٰهِيمُ قَدۡ صَدَّقۡتَ ٱلرُّءۡيَآۚ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ إِنَّ هَٰذَا لَهُوَ ٱلۡبَلَٰٓؤُاْ ٱلۡمُبِينُ وَفَدَيۡنَٰهُ بِذِبۡحٍ عَظِيمࣲ وَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ سَلَٰمٌ عَلَىٰٓ إِبۡرَٰهِيمَ كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ﴾ [الصافات: ۱۰۲-۱۱۱] \"پھر جب وہ (اسماعیل) اس عمر کو پہنچا کہ اس کے ساتھ چلے پھرے تو اس (ابرہیم) نےکہا: میرے پیارے بیٹے! میں خواب میں اپنے آپ کو تیری قربانی کرتے ہوے دیکھ رہا ہوں۔اب تو بتا کہ تیرا کیا خیال ہے؟ بیٹے نے جواب دیا کہ اباجان! آپ کوجو حکم دیا جارہا ہے اس کی پیروی کیجئے۔ اللہ نے چاہا تو آپ مجھے صبرکرنے والوں میں سے پائیں گے۔ غرض جب دونوں نے حکم قبول کر لیا اور اس (باپ) نے اس (بیٹے) کو پیشانی کے سہارے لٹادیا، تو ہم نے آواز دیا کہ اے ابراہیم، بےشک تو نے خواب کو سچ کر دکھایا۔ یقیناً ہم نیک لوگ کو اسی طرح بدلہ دیتے ہیں۔ حقیقت میں یہ ظاہر اورمشکل امتحان تھا۔ اور ہم نے ایک عظیم قربانی اس کی آزادی کی شکل میں دے دی۔ اور ہم نے ان کا ذکرخیر بعد کی امتوں میں باقی رکھا۔ ابرہیم پر سلام ہو۔ ہم نیک لوگوں کو اسی طرح بدلہ دیتے ہیں۔ یقیناً وہ ہمارے ایمان والے بندوں میں سے تھا\"۔\nابرہیم علیہ السلام کی اسی یاد میں ہرسال مسلمان عید الاضحیٰ کےموقع پر قربانی کرتے ہیں۔\n§صلاةِجنازہ:\nجب کسی مسلمان کی موت ہو جائے تو اس کو قبر میں دفن کرنے سے پہلے اس کی صلاةجنازہ اداکی جاتی ہے۔اگر کچھ لوگ اداکرلیں تو باقی لوگوں پر سے یہ فرض ختم ہو جاتا ہے،جس کو فقہ اسلامی میں فرض کفایہ کہتے ہیں۔لیکن اگر کوئی بھی نہ پڑھے تو پورا اسلامی معاشرہ گنہگار ہوگا، کیونکہ معاشرے پرایک مسلمان کے جس طرح زندگی میں کچھ حقوق ہیں اسی طرح موت کے بعد بھی کچھ حقوق ہیں۔ جیسےاسے غسل دینا، کفن پہنانا اور صلاةجنازہ اداکرنا اور پھر قبر میں دفن کرنا۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:«حَقُّ الْمُسْلِمِ عَلَی الْمُسْلِمِ خَمْسٌ: رَدُّ السَّلامِ، وَعِيَادَةُ الْمَرِيضِ، وَاتِّبَاعُ الْجَنَائِزِ، وَإِجَابَةُ الدَّعْوَةِ، وَتَشْمِيتُ الْعَاطِسِ». (صحیح البخاری: ۱۲۴۰، صحیح مسلم: ۲۱۶۲/۴) \"ایک مسلمان کے دوسرے مسلمان پر پانچ حقوق ہیں: سلام کا جواب دینا، بیمار کا حال چال پوچھنا، جنازہ کے ساتھ نکلنا، کھانے کی دعوت میں شامل ہونا، چھینکنے والے کا جواب دینا\"۔(یعنی جب وہ الحمد للہ کہے تو اس کے جواب میں یرحمک اللہ کہے۔)\nنمازجنازہ جس کو عربی میں صلاةِجنازةکہتے ہیں حقیقت میں یہ دعا ہے جو مرنے والے کے لیے کی جاتی ہے۔ ان دعاؤں میں ایک مشہور دعا یہ ہے:«اللَّهُمَّ اغْفِرْ لِحَيِّنَا، وَمَيِّتِنَا، وَصَغِيرِنَا وَکَبِيرَنَا، وَذَکَرِنَا وَأُنْثَانَا، وَشَاهِدِنَا وَغَائِبَنَا، اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَی الإِسْلاَمِ، وَمَنْ تَوَفِّيْتَهُ مِنَّا فَتَوَفِّهِ عَلَی الإِيْمَانِ، اللَّهُمَّ لاَ تَحْرِمْنَا أَجْرَهُ، وَلاَ تَفْتِنَّا بَعْدَهُ». (سنن ابی داود:۳۲۰۱، سنن الترمذی:۱۰۲۴، سنن ابن ماجہ:۱۴۹۸) \"اے اللہ ہمارے زندہ لوگوں اور ہمارے مرنے والے، ہمارے چھوٹے اور ہمارے بڑے،ہمارے مرد اور ہماری عورتیں، یہاں موجود اور غیر موجود سب کو تو معاف کردے۔ اے اللہ ہم میں سے جسے تو زندہ رکھ اسے اسلام پر زندہ رکھ اور جسے موت دے تو اسے ایمان پر موت دے۔ اے اللہ اس کے بعد ہمیں اس کے ثواب سے مایوس نہ کر اور نہ اس کے بعد ہمیں گمراہ کر\"۔\n§صلاة خوف(ڈر کی حالت میں نماز):\nصلاة(نماز) کی اہمیت کا اس سے بڑا ثبوت اور کیا ہوسکتا ہے کہ میدان جنگ میں بھی اسے اداکرنے کا حکم دیا گیا ہے۔ ہاں اتنا ضرور ہے کہ چار رکعت والی نمازیں دو رکعت کر دی گئیں۔\nقرآن مجیدمیں ہے:﴿وَإِذَا ضَرَبۡتُمۡ فِي ٱلۡأَرۡضِ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَقۡصُرُواْ مِنَ ٱلصَّلَوٰةِ إِنۡ خِفۡتُمۡ أَن يَفۡتِنَكُمُ ٱلَّذِينَ كَفَرُوٓاْۚ إِنَّ ٱلۡكَٰفِرِينَ كَانُواْ لَكُمۡ عَدُوࣰّ ا مُّبِينࣰ ا وَإِذَا كُنتَ فِيهِمۡ فَأَقَمۡتَ لَهُمُ ٱلصَّلَوٰةَ فَلۡتَقُمۡ طَآئِفَةࣱ مِّنۡهُم مَّعَكَ وَلۡيَأۡخُذُوٓاْ أَسۡلِحَتَهُمۡۖ فَإِذَا سَجَدُواْ فَلۡيَكُونُواْ مِن وَرَآئِكُمۡ وَلۡتَأۡتِ طَآئِفَةٌ أُخۡرَىٰ لَمۡ يُصَلُّواْ فَلۡيُصَلُّواْ مَعَكَ وَلۡيَأۡخُذُواْ حِذۡرَهُمۡ وَأَسۡلِحَتَهُمۡۗ وَدَّ ٱلَّذِينَ كَفَرُواْ لَوۡ تَغۡفُلُونَ عَنۡ أَسۡلِحَتِكُمۡ وَأَمۡتِعَتِكُمۡ فَيَمِيلُونَ عَلَيۡكُم مَّيۡلَةࣰ وَٰحِدَةࣰۚ وَلَا جُنَاحَ عَلَيۡكُمۡ إِن كَانَ بِكُمۡ أَذࣰ ى مِّن مَّطَرٍ أَوۡ كُنتُم مَّرۡضَىٰٓ أَن تَضَعُوٓاْ أَسۡلِحَتَكُمۡۖ وَخُذُواْ حِذۡرَكُمۡۗ إِنَّ ٱللَّهَ أَعَدَّ لِلۡكَٰفِرِينَ عَذَابࣰ ا مُّهِينࣰ ا﴾ [النساء: ۱۰۱-۱۰۲] \"جب تم زمین پرسفر کرو تو تم پر صلاة(نماز) قصر کرنے (چار رکعت کی صلاة(نماز) دورکعت پڑھنے)میں حرج نہیں اگر تمھیں یہ خوف ہو کہ دشمن تمھیں نقصان پہنچا دیں گے۔ بیشک کافر تمھارے کھلے دشمن ہیں۔ اور جب آپ ان میں (مسلمانوں میں ہوں)اور ان کے لیے صلاة(نماز)کا انتظام کریں تو چاہیے کہ ان کا ایک گروہ آپ کے ساتھ ہتھیار لیے کھڑا ہو۔ پھر جب یہ سجدہ کر چکیں تو یہ ہٹ کر آپ کے پیچھے آجائیں اور دوسرا گروہ جس نے صلاة(نماز) نہیں پڑھی ہے وہ آجائیں اور آپ کے ساتھ صلاة(نماز) ادا کریں اوراپنے ہتھیارلیے رہیں، دشمن چاہتے ہیں کہ تم کسی طرح اپنے ہتھیار اور سامان سے بے خبر ہوجاؤ تو وہ تم پر اچانک حملہ کردیں۔ اور ہاں اگر بارش کی وجہ سے تکلیف ہو تی ہو یا مرض ہو تو اپنے ہتھیار اتار کر رکھنے میں تم پر کوئی حرج نہیں مگر پھر بھی خبردار رہو۔ بےشک اللہ نے انکار کرنے والوں کے لیے ذلت والا عذاب تیار کر رکھا ہے\"۔\nصحیح احادیث سے معلوم ہوتا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے خوف کی حالت میں مختلف طرح سے صلاة (نماز)پڑھی جو جنگ کی مختلف حالتوں پرمنحصرتھی۔اس لیے امام احمد کا خیال ہے کہ سبھی طریقے صحیح ہیں جیسی حالت ہو اس کے مطابق کوئی بھی طریقہ اپنایا جا سکتا ہے۔ مقصد یہ ہے کہ صلاة(نماز) بھی نہ فوت ہو نے پائے اور دشمن گھات لگاکر حملہ بھی نہ کرسکے، اگر رکوع اور سجدے کے ساتھ صلاة(نماز) پڑھنی مشکل ہو تو کھڑے یا گھوڑے کی پیٹھ پر بیٹھے بیٹھےبھی صلاة(نماز) پڑھی جاسکتی ہے۔ ایک مسلمان کے لیے لازم ہےکہ وہ اللہ کی یاد سے کبھی بھی غافل نہ رہے۔ میدان جنگ میں بھی اللہ کو یاد کرے بلکہ اس سے مدد کا خواہشمند رہے۔\n§صلاةِسفر(سفر میں نماز):\nجس طرح خوف کی حالت میں صلاة(نماز) قصر ہوجاتی ہے اسی طرح سفر میں بھی صلاة(نماز) قصر ہوجاتی ہے۔ یعلی بن امیہ رضی اللہ عنہ کہتے ہیں کہ میں نے عمربن خطاب رضی اللہ عنہ سے کہا:﴿فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَقۡصُرُواْ مِنَ ٱلصَّلَوٰةِ إِنۡ خِفۡتُمۡ أَن يَفۡتِنَكُمُ ٱلَّذِينَ كَفَرُوٓاْۚ إِنَّ﴾ [النساء: ۱۰۱] فَقَدْ أَمِنَ النَّاسُ؟ فَقَالَ: عَجِبْتُ مِمَّا عَجِبْتَ مِنْهُ فَسَأَلْتُ رَسُولَ اللَّهِ صلی اللہ علیہ وسلم عَنْ ذَلِکَ فَقَالَ: صَدَقَةٌ تَصَدَّقَ اللَّهُ بِهَا عليکُمْ فَاقْبَلُوا صَدَقَتَهُ». (صحیح مسلم: ۴/۶۸۶) \"مطلب یہ ہے کہ اللہ نے تو خوف کی حالت میں قصر کرنے کا حکم دیا ہے۔ اب تو خوف نہیں ہے۔ پھر ہم سفر میں قصر کیوں کرتے ہیں۔ انھوں نے کہا یہی سوال میں نےآپ صلی اللہ علیہ وسلم سے کیا تھا تو آپ نے فرمایا: یہ اللہ کی طرف سے تمھارے لیےصدقہ ہے۔ اس کے صدقہ کو قبول کرلو\"۔\nیہ قصر صلاةحقیقت میں خوف کی حالت میں پڑھی جاتی ہے۔لیکن اب تم سفر کی حالت میں بھی قصر صلاة(نماز) پڑھ سکتے ہو۔ اکثرعلماء کا خیال ہے کہ سفر میں نمازقصر کرکے پڑھنا زیادہ صحیح ہے۔\nسفرمیں ایک اور سہولت یہ دی گئی ہے کہ دونمازیں ملاکر ایک وقت میں پڑھی جاسکتی ہیں۔ جیسے ظہر، عصراور مغرب،عشا۔ایک صحیح حدیث میں آتا ہے: انس بن مالک رضی اللہ عنہ کہتے ہیں: «کَانَ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم إِذَا ارْتَحَلَ قَبْلَ أَنْ تَزِيغَ الشَّمْسُ أَخَّرَ الظُّهْرَ إِلَی وَقْتِ الْعَصْرِ ثُمَّ نَزَلَ فَجَمَعَ بَيْنَهُمَا، فَإِنْ زَاغَتْ الشَّمْسُ قَبْلَ أَنْ يَرْتَحِلَ صَلَّی الظُّهْرَ ثُمَّ رَکِبَ». (صحیح البخاری: ۱۱۱۱، وصحیح مسلم: (۷۰۴/۴۶)\"اگررسول اللہ صلی اللہ علیہ وسلم سورج ڈھلنے سے پہلے سفر کرتے تو ظہرمیں دیر کردیتے اور عصر کے وقت دونوں کوملاکر پڑھتے۔ لیکن اگر سورج ڈھلنے کے بعد سفر شروع کرتے تو ظہر ادا کرنے کے بعد سفر شروع کرتے\"۔\nایک دوسری حدیث میں اس طرح آیا ہے:معاذ بن جبل رضی اللہ عنہ کہتے ہیں : «خَرَجْنَا مَعَ رَسُولِ اللَّهِ صلی اللہ علیہ وسلم فِي غَزْوَةِ تَبُوکَ، فَکَانَ يُصَلِّي الظُّهْرَ وَالْعَصْرَ جَمِيعًا وَالْمَغْرِبَ وَالْعِشَاءَ جَمِيعًا». (صحیح مسلم: ۵۲/۷۰۶) \"ہم جنگ کرنے کےلیے تبوک کی طرف نکلے تو دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم ظہر اورعصر ملاکر پڑھتےتھے۔ اسی طرح مغرب اورعشاملاکر پڑھتے تھے۔ دو نمازوں کو ملاکر پڑھنا حقیقت میں سفر کی حالت میں ہے تاکہ مسافر کو پریشانی نہ ہو۔لیکن ضرورت پڑنے پر اگر کوئی سفر کے بغیر بھی کبھی کبھی دونمازوں کو ملا کر پڑھ لے تو کوئی حرج نہیں۔ \" عبداللہ بن عباس رضی اللہ عنہما کی روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ظہر اورعصر، مغرب اور عشابغیر خوف اور بغیر سفر کے مدینہ میں ملاکر پڑھی۔ (دیکھیے: صحیح مسلم:۷۰۵/۴۹، ۵۰)\n§صلاةالضحی (چاشت کی نماز):\nضحی اس وقت کوکہتے ہیں جب سورج کی شدت کا احساس ہونے لگے۔ نبی اکرم صلی اللہ علیہ وسلم صلاۃالضحی دو رکعت سے لےکرآٹھ رکعت تک پڑھا کرتے تھے۔ ام ہانی ڤکہتی ہیں: \"نبی اکرم صلی اللہ علیہ وسلم مکہ فتح ہونےکے دن میرے گھر آئے۔ آپ نے پہلے غسل کیا۔ پھر آٹھ رکعت اداکی، جو تھی تو بہت ہلکی، لیکن رکوع اورسجدہ پوراکرتے تھے\"۔(صحیح البخاری: ۱۱۷۶، وصحیح مسلم: ۳۳۶/۸۰)\nام المومنین عائشہڤکہتی ہیں: رسول اللہ صلی اللہ علیہ وسلم صلاۃ الضحی چار رکعت اور کبھی اس سے زیادہ بھی پڑھتے تھے۔ (صحیح مسلم:۷۱۹: ۷۸)\nایک صحیح حدیث میں ہے کہ بر یدہ رضی اللہ عنہ کہتےہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوے سنا ہے:«فِي الإِنْسَانِ ثَلاثُ مِائَةٍ وَسِتُّونَ مَفْصِلا، فَعليهِ أَنْ يَتَصَدَّقَ عَنْ کُلِّ مَفْصِلٍ مِنْهُ بِصَدَقَةٍ، قَالُوا: وَمَنْ يُطِيقُ ذَلِکَ يَانَبِيَّ اللَّهِ؟ قَالَ: النُّخَاعَةُ فِي الْمَسْجِدِ تَدْفِنُهَا، وَالشَّيْءُ تُنَحِّيهِ عَنِ الطَّرِيقِ، فَإِنْ لَمْ تَجِدْ فَرَکْعَتَا الضُّحَی تُجْزِئُکَ». (سنن ابی داود: ۵۲۴۲، مسند احمد: ۵/۳۵۴، ۳۵۹) \"انسان کےاندر کل تین سوساٹھ جوڑ ہیں اور ہرجوڑ پرصدقہ نکالنا ضروری ہے۔ لوگوں نے کہا:اے اللہ کےرسول!کس کے پاس اتنی طاقت ہے۔تو آپ نے فرمایا: اگر کوئی مسجد سے گندگی صاف کر دے یا راستاسے کوئی چیز ہٹا دے (جس سے لوگوں کو تکلیف ہوتی ہو)یا اگر ان میں سے کچھ بھی نہ کر سکے تو دورکعت صلاةالضحی اداکرلے(تو اس کا صدقہ پورا ہوجائے گا)\"۔\n§صلاةِاستسقا:\nاستسقا کےمعنی ہیں پانی طلب کرنا۔ اس لیے استسقاکی نمازاس وقت پڑھی جاتی ہے، جب ملک میں قحط سالی ہو جائے یاپانی کی ضرورت محسوس ہو۔ ایک صحیح حدیث میں آیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم استسقاکی صلاة(نماز)اداکرنے کے لیے باہر نکلے۔ پہلے دو رکعت صلاةاداکی۔ اس کے بعد اپنی چادر کو الٹا کر دیا اورجو حصہ دائیں تھا اسے بائیں کیا اور جو بائیں تھا اسے دائیں۔ پھر ہاتھ اٹھا کر بارش کے لیے دعا کی۔ آپ کی دعا سے پورے مدینے میں پانی بھر گیا۔\n§صلاةِکسوف:\nکسوف کے معنی ہیں گرہن۔اسلام سے قبل لوگوں نے سورج گرہن یا چاند گرہن کو مختلف قسم کے بے بنیاد عقیدوں سے جوڑرکھا تھا۔مغیرہ بن شعبہ رضی اللہ عنہ کہتے ہیں کہ جس دن نبی اکرم صلی اللہ علیہ وسلم کےبیٹے ابراہیم کی وفات ہوئی، اسی دن سورج گرہن ہوگیا تو پرانے رسم و رواج کے مطابق کچھ لوگ کہنے لگے کہ دیکھو ابراہیم کی موت کی وجہ سے گرہن لگ گیا۔ جب آپ کو اس کی خبر ملی تو آپ نے لوگوں کو جمع کیا اور فرمایا :«إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ لا يَنْکَسِفَانِ لِمَوْتِ أَحَدٍ وَلا لِحَيَاتِهِ، فَإِذَا رَأَيْتُمُوهُمَا فَادْعُوا اللَّهَ وَصَلُّوا حَتَّی يَنْجَلِيَ». (صحیح البخاری: ۱۰۶۰،صحیح مسلم: ۹۱۵/۲۹) \"سورج اور چاند اللہ کی نشانیاں ہے۔ کسی کی موت ہوجانے یا زندہ رہنے سے ان کو گرہن نہیں لگتا۔ اس لیے اگر کبھی گرہن لگے تو اللہ سے دعاکرو اور صلاةاداکرو\"۔\nصلاةِکسوف کی متعین رکعات نہیں ہیں، بلکہ جب تک گرہن لگا ہو دو،دو رکعت صلاة ادا کرتے رہیں،یہاں تک کہ گرہن ختم ہوجائے۔\nایک دوسری صحیح حدیث میں ابو موسی اشعری رضی اللہ عنہ کہتے ہیں کہ ایک دن سورج گرہن لگا، تو نبی اکرم صلی اللہ علیہ وسلم ایسے اٹھ کھڑے ہوے کہ خوف کھا رہے ہوں کہ ابھی قیامت ہوجائے گی، آپ مسجد آئے اور بہت ہی لمبے قیام، رکوع اور سجدے کے ساتھ صلاۃاداکی، پھر فرمایا: «هَذِهِ الآيَاتُ الَّتِي يُرْسِلُ اللَّهُ لاتَکُونُ لِمَوْتِ أَحَدٍ وَلا لِحَيَاتِهِ، وَلَکِنْ يُخَوِّفُ اللَّهُ بِهِ عِبَادَهُ، فَإِذَا رَأَيْتُمْ شَيْئًا مِنْ ذَلِکَ فَافْزَعُوا إِلَی ذِکْرِهِ وَدُعَائِهِ وَاسْتِغْفَارِهِ». (صحیح البخاری: ۱۰۵۹، صحیح مسلم: ۹۱۲/۲۴) \" یہ نشانیاں ہیں جنھیں اللہ تعالی بھیجتا ہے، یہ کسی موت وزندگی کے سبب نہیں وقوع پذیر ہوتیں، ان کے ذریعے تو اللہ اپنے بندوں کو ڈراتا ہے جب اس طرح کی کوئی چیز دیکھو تو اس کے ذکر (نماز)اور اس س دعا اور استغفار کی طرف جلدی کرو\"۔\n§صلاةِاستخارہ:\nاستخارہ کےمعنی ہیں دو چیزوں میں سے کسی ایک کو اختیار کرنا۔ یہ صلاة اس وقت اداکی جاتی ہے جب آدمی کے سامنے کوئی پریشانی ہو۔ ایسی حالت میں اللہ تعالی سے دعا کی جاتی ہے کہ اس کے لیے جو مناسب ہو اس کی طرف اس کا دل پھیر دے۔ صحیح احادیث میں اس کی شرط یہ بتائی گئی ہے کہ سونے سے پہلے فرض صلاة(نماز) کے علاوہ دو رکعت صلاةاداکرنے کے بعد یہ دعا پڑھے:«اللَّهُمَّ إِنِّي أَسْتَخِيرُکَ بِعِلْمِکَ، وَأَسْتَقْدِرُکَ بِقُدْرَتِکَ، وَأَسْأَلُکَ مِنْ فَضْلِکَ الْعَظِيمِ، فَإِنَّکَ تَقْدِرُ وَلا أَقْدِرُ، وَتَعْلَمُ وَلا أَعْلَمُ، وَأَنْتَ عَلامُ الْغُيُوبِ، اللَّهُمَّ إِنْ کُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي- أَوْ قَالَ عَاجِلِ أَمْرِي وَآجِلِهِ- فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِکْ لِي فِيهِ، وَإِنْ کُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي - أَوْ قَالَ فِي عَاجِلِ أَمْرِي وَآجِلِهِ- فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِي الْخَيْرَ حَيْثُ کَانَ ثُمَّ أَرْضِنِي»اور اس کے بعد اپنی ضرورت کا نام لے۔ (دیکھیے صحیح البخاری:۱۱۶۲) \"اس صلاة(نماز) کے ذریعے اس کی پریشانی کا صحیح حل نکل جائے گا اور اس کے لیے جو مناسب ہوگا اس سے اللہ اس کے دل کو مطمئن کر دے گا اور اس مناسب کام کا اس کے لیے فیصلہ کردےگا\"۔\n§صلاةِالتسبیح:\nیہ ایک خاص قسم کی صلاةہے،جس کی کوئی سند صحیح نہیں ہے(اس کی پوری تفصیل میں نے اپنی کتاب المنۃ الکبری فی شرح السنن الصغری للبیهقی۴۲۱/۲ میں بیان کردی ہے)۔یہ صلاةکچھ اس طرح ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے اپنے چچا عباس رضی اللہ عنہ سے فرمایا: ہوسکے تو ہر دن ایک بار پڑھ لیا کرو، اگر ایسا نہ کرسکو تو ہر ہفتہ ایک بار پڑھ لیا کرو، اگر یہ بھی نہ ہوسکے تو ہر ماہ ایک بار پڑھ لیا کرو اور اگر یہ بھی نہ ہوسکے تو ہر سال ایک بار پڑھ لیا کرواور اگر یہ بھی نہ ہوسکے تو پوری عمر میں ایک بار پڑھ لو۔ (دیکھیے کتاب:المنة الکبری: ۴۲۱:۲)\n§صلاۃ الرغائب :\nاس صلاة(نماز) کا ذکرجامع الاصول میں آیا ہے۔ لیکن علماء کا خیال ہے کہ یہ صلاة چوتھی صدی ہجری میں مشہور ہوئی۔ اس لیے اس کا پڑھنا بدعت (غیر اسلامی) ہے۔\n§صلاةالحاجہ:\nیعنی وہ صلاة(نماز) جو کسی ضرورت کی تکمیل کے لیےادا کی جائے۔اس بارے میں مجھے تین حدیثیں ملی ہیں اور وہ سب بہت ضعیف ہیں۔اس لیے صلاة الحاجہ کے نام سے جو صلاةادا کی جاتی ہے اس کا کوئی ثبوت نہیں ملتا۔اس کے لیے میری کتاب الجامع الکامل دیکھیں۔\nصلاةِجمعہ=جمعہ","",{}]]);
